// ---------------------------------------------------------------------------
// Module-wide addresses.
//
// A REL has no runtime load address. The constants below are the canonical
// analysis addresses produced by `tools/rel2elf.mjs` (base 0x80A00000); they
// are *not* values seen by the retail loader.
// ---------------------------------------------------------------------------

/// Head of the global `fState` registration list, in BSS
/// (`DAT_80b6e500` in the export). Empty until a state table runs.
const STATE_LIST_HEAD: usize = 0x80B6_E500;

/// `fState`/name constructor at `0x8015F7C0` (`main.dol`). It writes a string
/// vtable at `+0x00`, the `char*` at `+0x04`, and a fresh integer id at
/// `+0x08`. The state table then overwrites `+0x00` with the state subclass
/// vtable, leaving the name and id in place.
///
/// Ghidra: `work/ghidra/main-gb/export/8015f7c0_FUN_8015f7c0.c`
const STATE_NAME_INIT: usize = 0x8015_F7C0;

/// Pushes one registration node onto [`STATE_LIST_HEAD`]:
/// `node[0] = head; node[1] = callback; node[2] = state; head = node`.
/// Implemented by [`fn_80a00160`] in this module.
const STATE_PUSH: usize = 0x80A0_0160;

/// Walks [`STATE_LIST_HEAD`] and invokes `callback(state, -1)` for each node.
/// Implemented by [`fn_80a00180`] in this module.
const STATE_DRAIN: usize = 0x80A0_0180;

// ---------------------------------------------------------------------------
// Opaque callees shared by the actor constructors and the early framework
// functions. Each is an address from the export; names are inferred only where
// the call shape is unambiguous.
// ---------------------------------------------------------------------------

/// Allocates a zeroed object of the requested size (`main.dol`). Observed in
/// every actor constructor as `FUN_801628c0(size)`; returns 0 on failure.
const FN_801628C0: usize = 0x8016_28C0;

/// Base actor constructor (`main.dol`), called immediately after allocation.
/// It is shown with no explicit arguments, so the receiver is passed in `r3`
/// by the original calling convention.
// unknown: exact class is not established; role inferred from the allocation
// sequence shared by every constructor in the export.
const FN_80094E80: usize = 0x8009_4E80;

/// Actor sub-object initialiser used by the constructors (`main.dol`).
/// Ghidra: `80069020_FUN_80069020.c`.
const FN_80069020: usize = 0x8006_9020;

/// Initialises a small embedded list/owner object (`main.dol`).
/// Ghidra: `80169cd0_FUN_80169cd0.c`.
const FN_80169CD0: usize = 0x8016_9CD0;

/// Initialises an embedded colour/animation holder (`main.dol`).
/// Ghidra: `80168d10_FUN_80168d10.c`.
const FN_80168D10: usize = 0x8016_8D10;

/// Installs a small polymorphic helper (`main.dol`).
/// Ghidra: `802d7aa0_FUN_802d7aa0.c`.
const FN_802D7AA0: usize = 0x802D_7AA0;

/// Initialises an embedded animation object (`main.dol`).
/// Ghidra: `8007f7a0_FUN_8007f7a0.c`.
const FN_8007F7A0: usize = 0x8007_F7A0;

