// ---------------------------------------------------------------------------
// Local helpers.
// ---------------------------------------------------------------------------

/// Reads a big-endian `f32` without changing its bit pattern.
#[inline]
unsafe fn read_f32(addr: usize) -> f32 {
    f32::from_bits(platform::read_u32(addr))
}

/// Writes a big-endian `f32` without changing its bit pattern.
#[inline]
unsafe fn write_f32(addr: usize, value: f32) {
    platform::write_u32(addr, value.to_bits());
}

/// Calls a zero-argument function that returns a word. `platform::call0`
/// discards the return value, and several state tables store it, so this
/// helper exists only for those call sites.
#[inline]
unsafe fn call0_ret_u32(addr: usize) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn() -> u32);
    f()
}

/// Reads a big-endian IEEE-754 `f64` from target memory.
///
/// The damage handlers pass `double` constants to engine helpers. The value is
/// assembled from two big-endian words so the bit pattern is preserved.
#[inline]
unsafe fn read_f64(addr: usize) -> f64 {
    let high = platform::read_u32(addr) as u64;
    let low = platform::read_u32(addr + 4) as u64;
    f64::from_bits((high << 32) | low)
}

/// Calls a function with one `f64` and two integer arguments.
///
/// Used only by the two damage handlers whose Ghidra call sites show a
/// `double` first argument (`0x80169F80`, `0x801662F0`). Passing the value as
/// raw bits through the integer helpers would put it in the wrong register
/// class, so this small adapter keeps the original ABI.
#[inline]
unsafe fn call3_f64(addr: usize, first: f64, second: u32, third: u32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f64, u32, u32) -> u32);
    f(first, second, third)
}

// ===========================================================================
// 1. Module bootstrap and state registry
// ===========================================================================

/// REL entry point: hands one static table to `0x80160A20`, then calls the
/// (empty) local prolog helper.
///
/// `0x80160A20` is outside the `d_enemiesNP` export, so its role is unknown;
/// the argument is a pointer to `PTR_LAB_80b2a518`, which is exactly the end
/// of the module's text section and therefore likely the start of the data
/// section's descriptor table.
///
/// # Original
/// - Ghidra: `entry` at `0x80A000F0` (44 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a000f0_entry.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Side effects
/// Calls into `main.dol`; the local callee `0x80A001E0` is a bare `return`.
///
/// # Safety
/// Must run on a PowerPC target (or ABI-compatible host) with the REL image
/// mapped at the synthetic base and `main.dol` mapped at its usual address.
///
/// # Confidence
/// high - the two calls and the argument are explicit; only the callee role is
/// unknown.
pub unsafe fn entry() {
    call1(0x8016_0A20, 0x80B2_A518);
    // 0x80A001E0 is `{ return; }` in the export.
    call0(0x80A0_01E0);
}

/// Pushes one state registration onto the global list.
///
/// The three-word record is:
/// `node[0] = previous head`, `node[1] = callback`, `node[2] = state object`.
/// The head lives in BSS at [`STATE_LIST_HEAD`]. This is the primitive every
/// state table in the module uses.
///
/// # Original
/// - Ghidra: `FUN_80a00160` at `0x80A00160` (28 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a00160_FUN_80a00160.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `state` Ã¢-- `fState` object being registered.
/// * `callback` Ã¢-- per-registration callback invoked by [`fn_80a00180`].
/// * `node` Ã¢-- caller-owned three-word link record.
///
/// # Side effects
/// Writes `node[0..3]` and updates the BSS list head.
///
/// # Safety
/// `node` must be a writable three-word record; `state` is stored, not
/// dereferenced here.
///
/// # Confidence
/// high - explicit three stores followed by a head update.
pub unsafe fn fn_80a00160(state: usize, callback: usize, node: usize) {
    platform::write_u32(node, platform::read_u32(STATE_LIST_HEAD));
    platform::write_u32(node + 4, callback as u32);
    platform::write_u32(node + 8, state as u32);
    platform::write_u32(STATE_LIST_HEAD, node as u32);
}

/// Drains the global state list: for each node, call
/// `callback(state, -1)`, then unlink it.
///
/// The callback is read before the state so the order matches the original:
/// `puVar1 = head + 1; puVar2 = head + 2; head = *head; callback(*puVar2,
/// 0xFFFFFFFF)`.
///
/// # Original
/// - Ghidra: `FUN_80a00180` at `0x80A00180` (84 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a00180_FUN_80a00180.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Side effects
/// Calls every registered callback and empties [`STATE_LIST_HEAD`].
///
/// # Safety
/// Every node must remain valid until the loop reaches it, and each callback
/// must accept `(state, -1)`.
///
/// # Confidence
/// high - the loop and the two field reads are explicit.
pub unsafe fn fn_80a00180() {
    while platform::read_u32(STATE_LIST_HEAD) != 0 {
        let node = platform::read_u32(STATE_LIST_HEAD) as usize;
        let callback = platform::read_u32(node + 4) as usize;
        let state = platform::read_u32(node + 8) as usize;
        platform::write_u32(STATE_LIST_HEAD, platform::read_u32(node));
        call2(callback, state as u32, 0xFFFF_FFFF);
    }
}

/// Builds one `fState` record and registers it.
///
/// This is the common body of every `StateID` table in this file. Observed
/// sequence:
///
/// 1. `STATE_NAME_INIT(desc, name)` Ã¢-- writes name vtable/pointer/id;
/// 2. `desc+0x00 = vtable` Ã¢-- replaces the string vtable with the state's;
/// 3. nine words are copied from the read-only state-parameter block into
///    `desc+0x24, +0x28, +0x2C, +0x18, +0x1C, +0x20, +0x0C, +0x10, +0x14`;
/// 4. an optional tenth word (a callback returned by a constructor) is stored
///    at `desc+0x30`;
/// 5. [`STATE_PUSH`] links `(desc, callback, node)` into the global list.
///
/// The word order in step 3 is the order Ghidra shows, not address order:
/// the compiler grouped the three high fields first.
///
/// # Arguments
/// * `node` Ã¢-- three-word link record that is passed to [`STATE_PUSH`].
/// * `desc` Ã¢-- `fState` object; usually `node + 0x10`, but `node + 0x0C` for
///   records that include the optional `+0x30` word.
/// * `name` Ã¢-- address of the `daEn<Class>_c::StateID_<Name>` C string.
/// * `vtable` Ã¢-- address installed at `desc+0x00`.
/// * `params` Ã¢-- base of the nine-word read-only parameter block.
/// * `callback` Ã¢-- per-registration callback passed to [`STATE_PUSH`].
/// * `extra` Ã¢-- optional tenth word for states that carry an extra callback.
///
/// # Side effects
/// Writes the descriptor, the link node and the BSS list head.
///
/// # Safety
/// All addresses must be mapped and writable as described.
///
/// # Confidence
/// high - the descriptor layout is repeated identically by all seven tables.
unsafe fn register_state(
    node: usize,
    desc: usize,
    name: usize,
    vtable: u32,
    params: usize,
    callback: usize,
    extra: Option<u32>,
) {
    call2(STATE_NAME_INIT, desc as u32, name as u32);
    platform::write_u32(desc, vtable);

    platform::write_u32(desc + 0x24, platform::read_u32(params));
    platform::write_u32(desc + 0x28, platform::read_u32(params + 0x04));
    platform::write_u32(desc + 0x2C, platform::read_u32(params + 0x08));
    platform::write_u32(desc + 0x18, platform::read_u32(params + 0x0C));
    platform::write_u32(desc + 0x1C, platform::read_u32(params + 0x10));
    platform::write_u32(desc + 0x20, platform::read_u32(params + 0x14));
    platform::write_u32(desc + 0x0C, platform::read_u32(params + 0x18));
    platform::write_u32(desc + 0x10, platform::read_u32(params + 0x1C));
    platform::write_u32(desc + 0x14, platform::read_u32(params + 0x20));

    if let Some(word) = extra {
        platform::write_u32(desc + 0x30, word);
    }

    call3(STATE_PUSH, desc as u32, callback as u32, node as u32);
}

