    platform::write_u32(actor + 0x424, platform::read_u32(0x80B2_FD40));
    platform::write_u32(actor + 0x428, platform::read_u32(0x80B2_FD44));
    platform::write_u32(actor + 0x42C, platform::read_u32(0x80B2_FD48));
