///
/// Observed sequence: base updates (`0x8006CD90`, `0x8006CDE0(this)`,
/// `0x800955F0(this)`), a shared update at `0x80AB5BD0`, then an animation
/// query at `this+0x1EC`. When the query returns non-zero:
///
/// * if vertical speed equals `0x80B2FCE4`, horizontal speed is reloaded from
///   the byte-indexed table at `0x80B2FC98` and scaled by `0x80B2FCD8`;
/// * vertical speed is scaled by `0x80B2FD50`;
/// * a 16-byte stack buffer holding the `this+0xAC` vector is passed to
///   sound/effect helper `0x80198C30` with id `0x2D0`;
/// * the `u16` timer at `+0x550` is halved, clamped to `0x10`;
/// * the state vtable's `+0xD4` method is called with `&0x80B75390` (the
///   next-state descriptor).
///
/// # Original
/// - Ghidra: `FUN_80ab5f20` at `0x80AB5F20` (256 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80ab5f20_FUN_80ab5f20.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` Ã¢-- `daEnKuribo_c` instance; `+0x60` is the class vtable,
///   `+0x1EC` the animation object, `+0x348` the direction byte.
///
/// # Side effects
/// Writes speed and timer fields, emits one effect/sound request, and may
/// change the actor state through the vtable.
///
/// # Safety
/// `actor` and its vtable/animation sub-objects must be valid.
///
/// # Confidence
/// medium - the flow is explicit but the state role and table constants are
/// inferred from the cluster; no StateID string is attached to this address.
pub unsafe fn fn_80ab5f20(actor: usize) {
    // inferred: Ghidra prints no argument, but the actor is still live in r3.
    call1(0x8006_CD90, actor as u32);
    call1(0x8006_CDE0, actor as u32);
    call1(0x8009_55F0, actor as u32);
    call1(0x80AB_5BD0, actor as u32);

    if call1(0x8007_2BC0, (actor + 0x1EC) as u32) != 0 {
        if read_f32(0x80B2_FCE4) == read_f32(actor + 0xE8) {
            let index = platform::read_u8(actor + 0x348) as usize;
            write_f32(
                actor + 0xF4,
                read_f32(0x80B2_FC98 + index * 4) * read_f32(0x80B2_FCD8),
            );
        }
        write_f32(actor + 0xEC, read_f32(0x80B2_FD50) * read_f32(actor + 0xEC));

        let mut vector = [0u8; 16];
        call2(0x8006_A4B0, vector.as_mut_ptr() as u32, (actor + 0xAC) as u32);
        call4(
            0x8019_8C30,
            platform::read_u32(0x8042_9D60),
            0x2D0,
            vector.as_mut_ptr() as u32,
            0,
        );

        let timer = (platform::read_u16(actor + 0x550) as i16) >> 1;
        platform::write_u16(actor + 0x550, timer as u16);
        if timer < 0x10 {
            platform::write_u16(actor + 0x550, 0x10);
        }

        let vtable = platform::read_u32(actor + 0x60) as usize;
        let switch_state = platform::read_u32(vtable + 0xD4) as usize;
        call2(switch_state, actor as u32, 0x80B7_5390);
    }
}

/// Per-frame handler for a walking/turning state: mirrors horizontal speed
/// when the actor is on the ground and halves the timer each frame.
///
/// Observed sequence: base updates, shared update `0x80AB5B40`, a ground test
/// at `this+0x1EC`. On the ground:
///
/// * if `|horizontal speed| >= 0x80B2FCE4`, it calls [`fn_80ab5e50`] and
///   returns (the "hit something" branch);
/// * otherwise both horizontal speeds are multiplied by `0x80B2FD50` and the
///   direction byte `+0x348` is toggled;
/// * two more shared updates run; when the animation query is non-zero,
///   vertical speed is damped and the timer at `+0x550` is set to `0xC00` or
///   halved/clamped to `0x10`;
/// * when the vertical speed is below `0x80B2FD2C`, it is cleared, two
///   animation direction bytes are saved at `+0x554`/`+0x555`, and the state
///   switches through vtable `+0xD4` with `&0x80B753D0`.
///
/// # Original
/// - Ghidra: `FUN_80ab60a0` at `0x80AB60A0` (420 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80ab60a0_FUN_80ab60a0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` Ã¢-- `daEnKuribo_c` instance.
///
/// # Side effects
/// Writes speed, direction, timer and animation-direction fields; emits one
/// effect/sound request; may switch state.
///
/// # Safety
/// `actor` and its vtable/animation sub-objects must be valid.
///
/// # Confidence
/// medium - explicit flow, but the handler's StateID is not recoverable.
pub unsafe fn fn_80ab60a0(actor: usize) {
    // inferred: Ghidra prints no argument, but the actor is still live in r3.
    call1(0x8006_CD90, actor as u32);
    call1(0x8006_CDE0, actor as u32);
    call1(0x8009_55F0, actor as u32);
    call1(0x80AB_5B40, actor as u32);

    if call2(0x8006_FA40, (actor + 0x1EC) as u32, 0) != 0 {
        if read_f32(0x80B2_FCE4) <= read_f32(actor + 0xE8).abs() {
            fn_80ab5e50(actor);
            return;
        }
        let speed_x = read_f32(0x80B2_FD50) * read_f32(actor + 0xE8);
        let speed_y = read_f32(0x80B2_FD50) * read_f32(actor + 0xF4);
        let direction = platform::read_u8(actor + 0x348) ^ 1;
        platform::write_u8(actor + 0x348, direction);
        write_f32(actor + 0xE8, speed_x);
        write_f32(actor + 0xF4, speed_y);
    }

    call1(0x80AB_5BD0, actor as u32);
    call1(0x80AB_5C70, actor as u32);
    if call1(0x8007_2BC0, (actor + 0x1EC) as u32) != 0 {
        write_f32(actor + 0xEC, read_f32(0x80B2_FD50) * read_f32(actor + 0xEC));
        if platform::read_u16(actor + 0x550) == 0 {
            platform::write_u16(actor + 0x550, 0x0C00);
            platform::write_u16(actor + 0x552, 0);
        } else {
            let timer = (platform::read_u16(actor + 0x550) as i16) >> 1;
            platform::write_u16(actor + 0x550, timer as u16);
            if timer < 0x10 {
                platform::write_u16(actor + 0x550, 0x10);
            }
        }

        let mut vector = [0u8; 12];
        call2(0x8006_A4B0, vector.as_mut_ptr() as u32, (actor + 0xAC) as u32);
        call4(
            0x8019_8C30,
            platform::read_u32(0x8042_9D60),
            0x2D0,
            vector.as_mut_ptr() as u32,
            0,
        );

        if read_f32(actor + 0xEC).abs() < read_f32(0x80B2_FD2C) {
            write_f32(actor + 0xEC, read_f32(0x80B2_FCE4));
            let direction = platform::read_u8(actor + 0x348);
            // observed: both helpers return the byte directly, not a pointer.
            let first =
                call2(0x8007_0820, (actor + 0x1EC) as u32, direction as u32) as u8;
            platform::write_u8(actor + 0x554, first);
            let second = call1(0x8007_0760, (actor + 0x1EC) as u32) as u8;
            platform::write_u8(actor + 0x555, second);

            let vtable = platform::read_u32(actor + 0x60) as usize;
            let switch_state = platform::read_u32(vtable + 0xD4) as usize;
            call2(switch_state, actor as u32, 0x80B7_53D0);
        }
    }
}

/// Per-frame handler for a running/turning state, including the ground/air
/// split.
///
/// Observed differences from [`fn_80ab60a0`]: the shared update is
/// `0x80AB5D30`, both horizontal speeds are tested together, an effect is
/// emitted when the `0x80070CB0` query is zero, and the state switch target is
/// `&0x80B75390` when the `0x80072BC0` animation query returns zero or
/// `&0x80B753D0` when it succeeds.
