    platform::write_u8(actor + 0xAF4, platform::read_u8(actor + 0x07));

    let speed_lo = platform::read_u32(0x80B2_C6D4);
    platform::write_u32(actor + 0xDC, speed_lo);
    platform::write_u32(actor + 0xE0, speed_lo);
    platform::write_u32(actor + 0xE4, speed_lo);
    let speed_hi = platform::read_u32(0x80B2_C6D8);
    platform::write_u32(actor + 0xD0, speed_hi);
    platform::write_u32(actor + 0xD4, speed_hi);
