        let zero = platform::read_u32(0x80B3_1A58);
        platform::write_u32(0x80B7_8438, zero);
        platform::write_u32(0x80B7_843C, zero);
        platform::write_u32(0x80B7_8440, zero);
        platform::write_u32(0x80B7_8444, platform::read_u32(0x80B3_1A6C));
        platform::write_u32(0x80B7_8448, zero);
        platform::write_u32(0x80B7_844C, platform::read_u32(0x80B3_1A70));
        platform::write_u32(0x80B7_8450, platform::read_u32(0x80B3_1A70));
        platform::write_u32(0x80B7_8454, zero);
        platform::write_u32(0x80B7_8458, platform::read_u32(0x80B3_1A6C));
        platform::write_u32(0x80B7_845C, zero);
        // The guard is written last, exactly as in the original.
        platform::write_u8(0x80B7_8430, 1);
