const DAT_80B2A9E8: usize = 0x80B2_A9E8;

/// Two-entry `f32` table selected by the facing byte at `+0x6E1`; both entries
/// observed as `0.5`.
const DAT_80B2AA00: usize = 0x80B2_AA00;

/// `f32` 96.0, the horizontal half-width used by the turn decision.
const DAT_80B2AA08: usize = 0x80B2_AA08;

/// `f32` 0.03125, the forward speed written while the actor keeps its facing.
const DAT_80B2AA0C: usize = 0x80B2_AA0C;

/// `f32` 1.5, the animation blend time used when the actor turns around.
const DAT_80B2AA10: usize = 0x80B2_AA10;

/// `f32` 0.015625, the slower speed written while turning.
const DAT_80B2AA14: usize = 0x80B2_AA14;

/// Two-entry `f32` pitch-step table `[-0.0625, +0.0625]` indexed by
/// `(byte at +0x6E2) & 1`.
const DAT_80B2AA18: usize = 0x80B2_AA18;

/// Two-entry `f32` pitch-limit table `[-0.25, +0.25]` with the same index.
const DAT_80B2AA20: usize = 0x80B2_AA20;

/// `f32` 6400.0, the squared chase distance below which `AttackSwim` ends.
const DAT_80B2AA2C: usize = 0x80B2_AA2C;

/// `f32` 3000.0, the default vertical speed restored by `AttackWait`.
const DAT_80B2AA30: usize = 0x80B2_AA30;

/// `f32` 0.75, the vertical speed multiplier stored at `+0x6A4` by
/// `AttackWait`.
const DAT_80B2AA34: usize = 0x80B2_AA34;

/// `"g3d/bakubaku.brres"` - the archive path passed to `0x800DF180`.
const STR_G3D_BAKUBAKU: usize = 0x80B3_3674;

/// `"bakubaku"` - the model name passed to `0x800DF180`/`0x80239E30`.
const STR_BAKUBAKU: usize = 0x80B3_3688;

/// `"swim"` - the clip name passed to `0x8023A0B0`.
const STR_SWIM: usize = 0x80B3_3694;

/// Animation-name pointer table; `+4 * index` is passed to `0x8023A0B0`.
/// The entries are relocation-filled, so the file image holds zeroes here.
const PTR_TABLE_80B336B4: usize = 0x80B3_36B4;

/// `daEnBuku_c::StateID_SrcSwim` state object (BSS).
const STATE_BUKU_SRC_SWIM: usize = 0x80B6_E7F8;

/// `daEnBuku_c::StateID_AttackSwim` state object (BSS).
const STATE_BUKU_ATTACK_SWIM: usize = 0x80B6_E838;

/// Base collision/hit callback used by the `bakubaku` actor's vtable helper
/// (`main.dol`).
const FN_8009F840: usize = 0x8009_F840;

/// Spawns a four-word effect record: `(manager, position, rgba, mask, count,
/// a, b, byte)` (`main.dol`).
const FN_800A77A0: usize = 0x800A_77A0;

/// Ground probe used by the `AttackSwim` handler (`main.dol`). It returns
/// non-zero when the actor is standing on the surface it tests.
const FN_80097B30: usize = 0x8009_7B30;

/// Calls a function with eight integer arguments.
///
/// `platform` stops at [`platform::call7`] and this lane does not own
/// `platform.rs`, so the one eight-argument call site (`0x800A77A0`) gets a
/// local adapter. The argument order is exactly the Ghidra call order.
#[inline]
unsafe fn call8_u32(
    addr: usize,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
    f: u32,
    g: u32,
    h: u32,
) -> u32 {
    let func = crate::platform::guest_fn!(addr, fn(u32, u32, u32, u32, u32, u32, u32, u32) -> u32);
    func(a, b, c, d, e, f, g, h)
}

