///
/// # Arguments
/// * `actor` - lift actor with the two signed angles.
///
/// # Side effects
/// Writes `+0x496` and possibly `+0x490`.
///
/// # Safety
/// `actor` must be readable and writable at those offsets.
///
/// # Confidence
/// high - the decay, the range test and both step directions are explicit.
pub unsafe fn fn_80a6da70(actor: usize) {
    let mut wobble = read_i16(actor + 0x496) as i32;
    wobble -= wobble >> 5;
    platform::write_u16(actor + 0x496, wobble as u16);

    if (wobble as i16 as u16).wrapping_add(7) > 0xE {
        return;
    }

    let mut tilt = read_i16(actor + 0x490) as i32;
    if tilt < 0 {
        tilt += 8;
        platform::write_u16(actor + 0x490, tilt as u16);
        if (tilt as i16) < 1 {
            return;
        }
        platform::write_u16(actor + 0x490, 0);
        return;
    }
    if tilt < 1 {
        return;
    }
    tilt -= 8;
    platform::write_u16(actor + 0x490, tilt as u16);
    if (tilt as i16) >= 0 {
        return;
    }
    platform::write_u16(actor + 0x490, 0);
}

/// Damps the vertical speed and walks the spring offset back to zero.
///
/// Observed: `+0x488 -= 0.05 * +0x488`; if the speed is small enough
/// (`|speed| < 0.0625`) the offset `+0x484` is stepped by `0.0625` toward zero
/// and snapped to zero when it crosses.
///
/// # Original
/// - Ghidra: `FUN_80a6dae0` at `0x80A6DAE0` (120 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a6dae0_FUN_80a6dae0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` - lift actor with the speed and offset fields.
///
/// # Side effects
/// Writes `+0x488` and possibly `+0x484`.
///
/// # Safety
/// `actor` must be readable and writable at those offsets.
///
/// # Confidence
/// high - the damping factor, threshold and both step directions are explicit.
pub unsafe fn fn_80a6dae0(actor: usize) {
    let mut speed = read_f32(actor + 0x488);
    speed -= read_f32(0x80B2_D984) * speed;
    platform::write_f32(actor + 0x488, speed);

    if speed <= read_f32(0x80B2_D988) {
        return;
    }
    if speed >= read_f32(0x80B2_D98C) {
        return;
    }

    let zero = read_f32(0x80B2_D978);
    let step = read_f32(0x80B2_D98C);
    let mut offset = read_f32(actor + 0x484);
    if offset < zero {
        offset += step;
        platform::write_f32(actor + 0x484, offset);
        if offset <= zero {
            return;
        }
        platform::write_f32(actor + 0x484, zero);
        return;
    }
    if offset <= zero {
        return;
    }
    offset -= step;
    platform::write_f32(actor + 0x484, offset);
    if zero <= offset {
        return;
    }
    platform::write_f32(actor + 0x484, zero);
}

/// Integrates the vertical spring and writes the resulting world Y.
///
/// Observed order:
/// 1. `+0x488 += +0x48C`, clamped to `[-2, 2]`;
/// 2. [`fn_80a6dae0`] damps the speed;
/// 3. `+0x484 += +0x488`, clamped to `[-64, 64]`;
/// 4. `+0x48C = -0.0024 * +0x484`, clamped to `[-2, 2]`;
/// 5. `+0xB0 = +0x480 + +0x484`.
///
/// # Original
/// - Ghidra: `FUN_80a6db60` at `0x80A6DB60` (232 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a6db60_FUN_80a6db60.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` - lift actor with the spring state.
///
/// # Side effects
/// Writes `+0x488`, `+0x484`, `+0x48C` and the world Y at `+0xB0`.
///
/// # Safety
/// `actor` must be readable and writable at those offsets.
///
/// # Confidence
/// high - every add, clamp and store is explicit.
pub unsafe fn fn_80a6db60(actor: usize) {
    let low = read_f32(0x80B2_D97C);
    let high = read_f32(0x80B2_D980);

    let mut speed = read_f32(actor + 0x488) + read_f32(actor + 0x48C);
    platform::write_f32(actor + 0x488, speed);
    if speed < low {
        platform::write_f32(actor + 0x488, low);
    } else if speed > high {
        platform::write_f32(actor + 0x488, high);
    }

    fn_80a6dae0(actor);

    let low_offset = read_f32(0x80B2_D990);
    let high_offset = read_f32(0x80B2_D994);
    let mut offset = read_f32(actor + 0x484) + read_f32(actor + 0x488);
    platform::write_f32(actor + 0x484, offset);
    if offset < low_offset {
        platform::write_f32(actor + 0x484, low_offset);
    } else if offset > high_offset {
        platform::write_f32(actor + 0x484, high_offset);
    }

    let mut accel = read_f32(0x80B2_D998) * read_f32(actor + 0x484);
    platform::write_f32(actor + 0x48C, accel);
    platform::write_f32(actor + 0xB0, read_f32(actor + 0x480) + read_f32(actor + 0x484));
    if accel < low {
        platform::write_f32(actor + 0x48C, low);
    } else if accel > high {
        platform::write_f32(actor + 0x48C, high);
    }
}

/// Builds both model matrices for the lift and commits them to the holders.
///
/// Observed: the world position `+0xAC..+0xB4` and rotation `+0x100..+0x104`
/// are converted to a matrix at `+0x7C` through `0x80064AF0`/`0x801C0BD0`,
/// the yaw reference `+0x46E` and roll `+0x104` are applied through
/// `0x8016ECB0`/`0x8016EEF0`, and the matrix is copied into the `+0x3F4`
/// holder. A second matrix using `y - 4.0` is copied into the `+0x400` holder
/// with the extra `0x8016A1A0` call.
///
/// # Original
/// - Ghidra: `FUN_80a6de90` at `0x80A6DE90` (364 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a6de90_FUN_80a6de90.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` - lift actor with a valid matrix scratch block at `+0x7C`.
///
/// # Returns
/// Always `1`.
///
/// # Side effects
/// Writes the matrix at `+0x7C`, both holder transforms, and advances both
/// holder vtables.
///
/// # Safety
/// The actor, the scratch matrix and both holders must be valid.
///
/// # Confidence
/// high - every position, angle and matrix call is explicit.
pub unsafe fn fn_80a6de90(actor: usize) -> u32 {
    let mut position = [
        read_f32(actor + 0xAC),
        read_f32(actor + 0xB0),
        read_f32(actor + 0xB4),
    ];
    let mut rotation = [
        platform::read_u16(actor + 0x100),
        platform::read_u16(actor + 0x102),
        platform::read_u16(actor + 0x104),
    ];
    call3(
        0x8006_4AF0,
        position.as_mut_ptr() as u32,
        rotation.as_mut_ptr() as u32,
        1,
    );
    call4_f64x3(
        0x801C_0BD0,
        position[0] as f64,
        position[1] as f64,
        position[2] as f64,
        (actor + 0x7C) as u32,
    );

    let mut yaw = platform::read_u16(actor + 0x46E);
    call2(0x8016_ECB0, (actor + 0x7C) as u32, &mut yaw as *mut u16 as u32);
    let mut roll = rotation[2];
    call2(0x8016_EEF0, (actor + 0x7C) as u32, &mut roll as *mut u16 as u32);
    call2(0x8016_A170, (actor + 0x3F4) as u32, (actor + 0x7C) as u32);
    call2(0x8016_A150, (actor + 0x3F4) as u32, (actor + 0xDC) as u32);
    let vtable = platform::read_u32(actor + 0x3F4) as usize;
    call1(
        platform::read_u32(vtable + 0x14) as usize,
        (actor + 0x3F4) as u32,
    );

    position[0] = read_f32(actor + 0xAC);
    position[1] = read_f32(actor + 0xB0) - read_f32(0x80B2_D9C4);
    position[2] = read_f32(actor + 0xB4);
    rotation[0] = platform::read_u16(actor + 0x100);
    rotation[1] = platform::read_u16(actor + 0x102);
    rotation[2] = platform::read_u16(actor + 0x104);
    call3(
        0x8006_4AF0,
        position.as_mut_ptr() as u32,
        rotation.as_mut_ptr() as u32,
        1,
    );
    call4_f64x3(
        0x801C_0BD0,
        position[0] as f64,
        position[1] as f64,
        position[2] as f64,
        (actor + 0x7C) as u32,
    );
    call2(0x8016_A170, (actor + 0x400) as u32, (actor + 0x7C) as u32);
    call2(0x8016_A150, (actor + 0x400) as u32, (actor + 0xDC) as u32);
    call2(0x8016_A1A0, (actor + 0x400) as u32, 0);
    let vtable = platform::read_u32(actor + 0x400) as usize;
    call1(
        platform::read_u32(vtable + 0x14) as usize,
        (actor + 0x400) as u32,
    );

    1
}

/// Main per-frame update of the lift actor.
///
/// Observed order:
/// 1. play sound `0x2C6` when `+0xC8 <= -0.125`, using the position vector
///    built by `0x8006A4B0`;
/// 2. add `+0x494` to the wobble `+0x496` and clamp it to `[-0x7F, 0x7F]`;
/// 3. call [`fn_80a6da70`], fold `+0x496` into the tilt `+0x490`, clamp the
///    tilt to `+/-+0x492`, and run [`fn_80a6d6e0`];
/// 4. copy the tilt into the roll `+0x104` and run [`fn_80a6db60`];
/// 5. resample neighbours with [`fn_80a6d950`]; when the returned bitmask
///    differs from `+0x498`, copy `+0x47A` into the latch `+0x46C` and store
///    the new mask at `+0x498`.
///
/// # Original
/// - Ghidra: `FUN_80a6e080` at `0x80A6E080` (304 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a6e080_FUN_80a6e080.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` - lift actor in the `Wait`/`Still` states.
///
/// # Side effects
/// May issue sound `0x2C6`; writes the wobble, tilt, roll, spring and
/// neighbour-snapshot fields.
///
/// # Safety
/// The actor, its sound manager at `0x80429D60` and its neighbour list must be
/// valid.
///
/// # Confidence
/// medium - the flow and every store are explicit; the sound trigger and the
/// bitmask meaning are inferred from the fields around them.
pub unsafe fn fn_80a6e080(actor: usize) {
    if read_f32(actor + 0xC8) <= read_f32(0x80B2_D9C8) {
        let mut position = [0u8; 16];
        call2(
            0x8006_A4B0,
            position.as_mut_ptr() as u32,
            (actor + 0xAC) as u32,
        );
        call5(
            0x8019_9390,
            platform::read_u32(DAT_80429D60),
            0x2C6,
            platform::read_u32(actor),
            position.as_mut_ptr() as u32,
            0,
        );
    }

    let mut wobble = read_i16(actor + 0x496).wrapping_add(read_i16(actor + 0x494));
    platform::write_u16(actor + 0x496, wobble as u16);
    if wobble < -0x7F {
        wobble = -0x7F;
        platform::write_u16(actor + 0x496, wobble as u16);
    } else if wobble > 0x7F {
        wobble = 0x7F;
        platform::write_u16(actor + 0x496, wobble as u16);
    }

    fn_80a6da70(actor);

    let limit = platform::read_u16(actor + 0x492) as i32;
    let mut tilt = read_i16(actor + 0x490).wrapping_add(read_i16(actor + 0x496));
    platform::write_u16(actor + 0x490, tilt as u16);
    if limit < tilt as i32 {
        platform::write_u16(actor + 0x490, limit as u16);
    } else if (tilt as i32) < -limit {
        platform::write_u16(actor + 0x490, (-limit) as u16);
    }

    fn_80a6d6e0(actor);
    platform::write_u16(actor + 0x104, platform::read_u16(actor + 0x490));
    fn_80a6db60(actor);

    let flags = fn_80a6d950(actor);
    if flags != platform::read_u8(actor + 0x498) as u32 {
        platform::write_u16(actor + 0x46C, platform::read_u16(actor + 0x47A));
    }
    platform::write_u8(actor + 0x498, flags as u8);
}

/// Releases one lift actor and optionally frees its memory.
///
/// Observed order: release `+0x40C`, release both animation holders
/// `+0x400`/`+0x3F4`, release the model holder `+0x3D4`, run the base
/// destructor `0x800671B0(this, 0)`, then call `0x80162920(this)` when the
/// caller's free flag is positive.
///
/// # Original
/// - Ghidra: `FUN_80a6e1b0` at `0x80A6E1B0` (144 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a6e1b0_FUN_80a6e1b0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` - lift actor to release; may be `0`.
/// * `free_flag` - positive values also free the allocation.
///
/// # Returns
/// `actor`, unchanged.
///
/// # Side effects
/// Releases four embedded objects and may free `actor`.
///
/// # Safety
/// `actor` must be null or a fully constructed lift actor.
///
/// # Confidence
/// high - every release call and the free guard are explicit.
pub unsafe fn fn_80a6e1b0(actor: usize, free_flag: i32) -> usize {
    if actor != 0 {
        if actor + 0x40C != 0 {
            call2(FN_800DAE00, (actor + 0x40C) as u32, 0);
        }
        call2(FN_8016A340, (actor + 0x400) as u32, 0xFFFF_FFFF);
        call2(FN_8016A340, (actor + 0x3F4) as u32, 0xFFFF_FFFF);
        call2(FN_80069060, (actor + 0x3D4) as u32, 0xFFFF_FFFF);
        call2(FN_800671B0, actor as u32, 0);
        if free_flag > 0 {
            call1(FN_80162920, actor as u32);
        }
    }
    actor
}

