/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a6e680_FUN_80a6e680.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` - `guru` actor with an initialised `+0x524` holder.
///
/// # Side effects
/// Loads one brres, binds one model and one clip, and writes
/// `+0x540/+0x544/+0x584`.
///
/// # Safety
/// The actor, the archive manager at `0x8042A038` and the holder must be
/// valid.
///
/// # Confidence
/// high - asset strings, holder offsets and every call are explicit.
pub unsafe fn fn_80a6e680(actor: usize) {
    // observed: reset the model holder at +0x524.
    call5(
        FN_800690C0,
        (actor + 0x524) as u32,
        0xFFFF_FFFF,
        platform::read_u32(DAT_80377C48),
        0,
        0x20,
    );

    let model = call3(
        FN_800DF180,
        platform::read_u32(DAT_8042A038) + 4,
        STR_GURU as u32,
        STR_G3D_GURU as u32,
    );
    platform::write_u32(actor + 0x540, model);

    let body = call2(FN_80239E30, (actor + 0x540) as u32, STR_GURU as u32);
    let mut body_slot = [body, 0, 0, 0];
    call6(
        FN_80169D90,
        (actor + 0x544) as u32,
        body_slot.as_mut_ptr() as u32,
        (actor + 0x524) as u32,
        0x20,
        1,
        0,
    );
    call1(FN_80064BF0, (actor + 0x544) as u32);

    let mut clip = call2(FN_8023A0B0, (actor + 0x540) as u32, STR_ROTATE as u32);
    let mut body_pair = [body];
    let mut clip_pair = [clip];
    call5(
        FN_801650D0,
        (actor + 0x584) as u32,
        body_pair.as_mut_ptr() as u32,
        clip_pair.as_mut_ptr() as u32,
        (actor + 0x524) as u32,
        0,
    );

    call1(FN_800690E0, (actor + 0x524) as u32);
}

