/// Reads a big-endian signed 16-bit integer.
#[inline]
unsafe fn read_i16(addr: usize) -> i16 {
    platform::read_u16(addr) as i16
}

/// Calls a function taking two `f64` and two integer arguments.
///
/// Only the ground probe `0x80075270` uses this shape: its first two
/// arguments are coordinates and its last argument is an output pointer.
#[inline]
unsafe fn call4_f64x2(addr: usize, first: f64, second: f64, a: u32, b: u32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f64, f64, u32, u32) -> u32);
    f(first, second, a, b)
}

