/// Allocates and constructs one `0x868`-byte segmented actor.
///
/// The object starts as an item chain root: `+0x540` holds the extra-segment
/// count, `+0x544` the first segment (body holder plus `+0x584` rotate
/// object), and `+0x5C0` a three-word attachment block. The tail installs the
/// deferred object at `+0x71C`, the self-back-pointer at `+0x720` and the
/// helper at `+0x724`.
///
/// # Original
/// - Ghidra: `FUN_80a6ee90` at `0x80A6EE90` (280 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a6ee90_FUN_80a6ee90.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// None; the size and every vtable are constants.
///
/// # Returns
/// The new actor, or `0` when `0x801628C0` fails.
///
/// # Side effects
/// Allocates `0x868` bytes and writes the class vtable plus the embedded
/// holders.
///
/// # Safety
/// Must run on a PowerPC target (or ABI-compatible host) with the REL image
/// mapped at the synthetic base.
///
/// # Confidence
/// high - size, vtable stores and every field initialiser are explicit; the
/// class label is `// inferred:` from the shared chain layout.
pub unsafe fn fn_80a6ee90() -> usize {
    let base = call1(FN_801628C0, 0x868) as usize;
    if base != 0 {
        call1(FN_80094E80, base as u32);
        // observed: the original writes a pre-install vtable word first and
        // replaces it with the class vtable at the end of the body.
        platform::write_u32(base + 0x60, DAT_80302414);
        call1(FN_80069020, (base + 0x524) as u32);
        platform::write_u32(base + 0x540, 0);
        call1(FN_80169CD0, (base + 0x544) as u32);
        call1(FN_80168D10, (base + 0x584) as u32);
        platform::write_u32(base + 0x584, VTABLE_GURU_ROTATE);

        platform::write_u32(base + 0x5BC, 0);
        platform::write_u32(base + 0x5C0, DAT_803295D8);
        platform::write_u32(base + 0x5C4, 0);
        platform::write_u32(base + 0x5C8, 0);
        call1(FN_8016A5E0, (base + 0x5CC) as u32);
        platform::write_u32(base + 0x5C0, DAT_80329548);
        platform::write_u32(base + 0x5E8, 0);

        platform::write_u16(base + 0x704, 0);
        platform::write_u16(base + 0x706, 0);
        platform::write_u32(base + 0x718, 0);
        platform::write_u32(base + 0x71C, DAT_80302738);
        platform::write_u32(base + 0x720, base as u32);
        call1(FN_802D7AA0, (base + 0x724) as u32);
        platform::write_u32(base + 0x724, DAT_80329958);

        platform::write_u32(base + 0x838, 0);
        platform::write_u32(base + 0x83C, 0);
        platform::write_u8(base + 0x840, 0);
        platform::write_u8(base + 0x841, 0);
        platform::write_u32(base + 0x844, 0);
        platform::write_u32(base + 0x848, 0);
        platform::write_u32(base + 0x60, VTABLE_SEGMENTED_868);
        platform::write_u32(base + 0x84C, 0);
    }
    base
}

/// Returns the heading from the actor at `+0x5EC` toward the actor at `+0x61C`.
