/// # Original
/// - Ghidra: `FUN_80a70300` at `0x80A70300` (224 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a70300_FUN_80a70300.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `node` - chain node whose `+0x30` child is probed.
///
/// # Returns
/// The node whose probe reported an occupied entry, or the recursion result.
///
/// # Side effects
/// Calls one virtual predicate per level.
///
/// # Safety
/// Every visited `+0x30` link must point at a live object.
///
/// # Confidence
/// high - the five unrolled levels and the recursive tail are explicit.
pub unsafe fn fn_80a70300(node: usize) -> usize {
    let mut current = node;
    let mut taken = chain_probe_80a70300(current);
    if taken == 0 {
        current = platform::read_u32(current + 0x30) as usize;
        taken = chain_probe_80a70300(current);
        if taken == 0 {
            current = platform::read_u32(current + 0x30) as usize;
            taken = chain_probe_80a70300(current);
            if taken == 0 {
                current = platform::read_u32(current + 0x30) as usize;
                taken = chain_probe_80a70300(current);
                if taken == 0 {
                    current = platform::read_u32(current + 0x30) as usize;
                    taken = chain_probe_80a70300(current);
                    if taken == 0 {
                        current = fn_80a70300(platform::read_u32(current + 0x30) as usize);
                    }
                }
            }
        }
    }
    current
}

