/// Calls a function with seven integer arguments.
///
/// `platform` stops at `call6` and this lane does not own `platform.rs`, so the
/// two seven-argument call sites (`0x800E41C0`) get a local adapter. Argument
/// order is exactly the Ghidra call order.
#[inline]
unsafe fn call7_u32(
    addr: usize,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
    f: u32,
    g: u32,
) -> u32 {
    let func = crate::platform::guest_fn!(addr, fn(u32, u32, u32, u32, u32, u32, u32) -> u32);
    func(a, b, c, d, e, f, g)
}

