/// # Returns
/// The last node whose child was rejected by the filter, or the accepting
/// child's parent.
///
/// # Safety
/// Every `+0x30` link must point to a live object whose first word is a vtable.
///
/// # Confidence
/// medium - the calls are explicit but the receiver is inferred from the
/// register setup; the chain role is unnamed.
pub unsafe fn fn_80a6a450(actor: usize) -> usize {
    let mut node = actor;
    loop {
        let child = platform::read_u32(node + 0x30) as usize;
        let vtable = platform::read_u32(child) as usize;
        let filter = platform::read_u32(vtable + 0x0C) as usize;
        if call1(filter, child as u32) != 0 {
            return node;
        }
        node = child;
    }
}

