/// Runs the `Wm_ob_itemappear` phase machine.
///
/// `+0xD78` counts the phase: `0` starts the appear effect, `1` waits for the
/// effect hook `+0xABC` slot `+0xB0`, `2` stops. The effect position is the
/// actor position raised by `8.0` (or `4.0` for item type `0xD`) and the
/// request is delayed by the byte counter at `+0xE02`.
///
/// # Original
/// - Ghidra: `FUN_80a85f10` at `0x80A85F10` (340 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a85f10_FUN_80a85f10.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` - item that is appearing.
///
/// # Side effects
/// Decrements `+0xE02`, writes `+0xD78` and starts one effect through the
/// `+0xABC` hook.
///
/// # Safety
/// The hook at `+0xABC` must be a live object with slots `+0xA0`/`+0xB0`.
///
/// # Confidence
/// high - the countdown, both phases and the six-argument effect call are
/// explicit.
pub unsafe fn fn_80a85f10(actor: usize) {
    if platform::read_u32(actor + 0xD78) == 2 {
        return;
    }

    let mut delay = platform::read_u8(actor + 0xE02);
    if delay != 0 {
        delay -= 1;
        platform::write_u8(actor + 0xE02, delay);
    }
    if delay != 0 {
        return;
    }

    let mut position = [0u32; 3];
    let base = position.as_mut_ptr() as usize;
    platform::write_u32(base, platform::read_u32(actor + 0xAC));
    let height = if platform::read_u16(actor + 0xDCA) == 0xD {
        read_f32(DAT_80B2E5C0)
    } else {
        read_f32(DAT_80B2E58C)
    };
    write_f32(base + 4, read_f32(actor + 0xB0) + height);
    platform::write_u32(base + 8, platform::read_u32(actor + 0xB4));

    let phase = platform::read_u32(actor + 0xD78);
    if phase == 0 {
        platform::write_u32(actor + 0xD78, 1);
        let hook = platform::read_u32(actor + 0xABC) as usize;
        let name = if platform::read_u16(actor + 0xDCA) == 0xD {
            DAT_80B4E3C8
        } else {
            DAT_80B4E3DC
        };
        call6(
            platform::read_u32(hook + 0xA0) as usize,
            (actor + 0xABC) as u32,
            name as u32,
            0,
            base as u32,
            0,
            (actor + 0xDC) as u32,
        );
    } else if phase == 1 {
        let hook = platform::read_u32(actor + 0xABC) as usize;
        let finished = call4(
            platform::read_u32(hook + 0xB0) as usize,
            (actor + 0xABC) as u32,
            base as u32,
            0,
            (actor + 0xDC) as u32,
        );
        if finished == 0 {
            platform::write_u32(actor + 0xD78, 2);
        }
    }
}

