    // a trailing zero used by the original stack layout.
    let mut probe = [0u32; 7];
    if platform::read_u32(actor + 0x6E8) == 0 {
        platform::write_u32(actor + 0x6F0, 0);
        platform::write_u32(actor + 0x6E4, platform::read_u32(DAT_80B2E74C));
        if platform::read_u32(actor + 0x6EC) == 3 {
            platform::write_u16(actor + 0x104, 0x8000);
        }
        probe[1] = platform::read_u32(DAT_80B2E74C);
        fn_80a8acf0(actor);
        switch_state(actor, DESC_80B73BF8);
    } else {
        platform::write_u8(actor + 0x38E, platform::read_u8(actor + 0x38E) & 0xF7);
        switch_state(actor, DESC_80B73C78);
        fn_80a8acf0(actor);
        probe[1] = (read_f32(actor + 0x6DC) - read_f32(actor + 0xB0)).to_bits();
    }
    probe[0] = platform::read_u32(DAT_80B2E750);
    probe[2] = platform::read_u32(DAT_80B2E754);
    probe[3] = platform::read_u32(DAT_80B2E74C);

    let mut extent = [platform::read_u32(DAT_80B2E748); 3];
