/// The `+0x30` chain and every vtable must be live.
///
/// # Confidence
/// high - the five unrolled tests and the recursion tail are explicit.
pub unsafe fn fn_80a91440(node: usize) -> usize {
    let mut current = node;
    for _ in 0..5 {
        let parent = platform::read_u32(current + 0x30) as usize;
        let vtable = platform::read_u32(parent) as usize;
        if call1(
            platform::read_u32(vtable + 0xC) as usize,
            parent as u32,
        ) != 0
        {
            return current;
        }
        current = parent;
    }
    fn_80a91440(platform::read_u32(current + 0x30) as usize)
}

/// Compares the class name after the last `:` with the requested suffix.
///
/// `0x802E1C40` is a `strchr`-like search for `':'` (character `0x3A`); the
/// object's name comes from its vtable slot `+0x20`, and `0x802E1AB4` is the
/// `strcmp`-like compare. When the object name has no colon the original still
/// passes `result + 1`; that is preserved.
///
/// # Original
/// - Ghidra: `FUN_80a91520` at `0x80A91520` (136 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a91520_FUN_80a91520.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `this` - object whose `vtable+0x20` returns its name.
/// * `name` - requested name.
///
/// # Returns
/// `true` when the two suffixes compare equal.
///
/// # Side effects
/// None.
///
/// # Safety
/// Both strings and the object's vtable must be valid.
///
/// # Confidence
/// high - the two string helpers and the compare are explicit.
pub unsafe fn fn_80a91520(this: usize, name: usize) -> bool {
    let colon = call2(FN_802E1C40, name as u32, 0x3A) as usize;
    let tail = if colon != 0 { colon + 1 } else { name };
    let vtable = platform::read_u32(this) as usize;
    let own = call1(platform::read_u32(vtable + 0x20) as usize, this as u32) as usize;
    let own_colon = call2(FN_802E1C40, own as u32, 0x3A) as usize;
    call2(FN_802E1AB4, (own_colon + 1) as u32, tail as u32) == 0
}

