        call1(FN_80168D10, (actor + 0x588) as u32);
        platform::write_u32(actor + 0x588, DAT_80B330E0 as u32);
        call1(FN_802D7AA0, (actor + 0x5C0) as u32);
        platform::write_u32(actor + 0x5C0, 0x8032_9958);
        platform::write_u32(actor + 0x6D4, 0);
        platform::write_u32(actor + 0x6D8, 0);
        platform::write_u8(actor + 0x6DC, 0);
        platform::write_u8(actor + 0x6DD, 0);
