    let player = call1(
        FN_8005F900,
        platform::read_u8(actor + 0x38D) as i8 as i32 as u32,
    ) as usize;
    let side = platform::read_u8(actor + 0x348) as usize;
    let base = read_f32(DAT_80B2EDF0 + side * 4);
    let add = read_f32(DAT_80B2EDF8) * read_f32(player + 0xE8);

    platform::write_u32(actor + 0xEC, platform::read_u32(DAT_80B2EDFC));
    platform::write_u32(actor + 0xF0, platform::read_u32(DAT_80B2ECD4));
    write_f32(actor + 0xE8, base + add);

    let record = call1(FN_80070CB0, (player + 0x1EC) as u32);
    if record == 0 || read_f32(DAT_80B2EE00) <= read_f32(player + 0xE8).abs() {
        platform::write_u16(actor + 0x62E, 0);
    } else {
        platform::write_u16(actor + 0x62E, 1);
    }

    platform::write_u32(actor + 0x604, 1);
    call1(FN_80096F60, actor as u32);
    call2(
        FN_8006EF40,
        (actor + 0x1EC) as u32,
        platform::read_u32(actor + 0x274),
    );
    call1(FN_80097050, actor as u32);

