    call1(FN_800955F0, actor as u32);
    fn_80a97110(actor);
    call1(FN_80096F60, actor as u32);
    call2(
        FN_8006EF40,
        (actor + 0x1EC) as u32,
        platform::read_u32(actor + 0x274),
    );
    call1(FN_80097050, actor as u32);

    let zero = platform::read_u32(DAT_80B2ECD4);
    let record = call1(FN_80070CB0, (actor + 0x1EC) as u32);
    if record == 0 {
        if (platform::read_u32(actor + 0x274) & 0x3C00_0000) != 0 {
            platform::write_u32(actor + 0xEC, platform::read_u32(DAT_80B2EE04));
        }
    } else if read_i16(actor + 0x62E) == 0 {
        let speed = read_f32(actor + 0xE8) * read_f32(DAT_80B2EE00);
        platform::write_u32(actor + 0xEC, platform::read_u32(DAT_80B2ED44));
        write_f32(actor + 0xE8, speed);
        platform::write_u16(actor + 0x62E, 1);
    } else {
        platform::write_u32(actor + 0xEC, zero);
        platform::write_u32(actor + 0xE8, zero);
        platform::write_u8(actor + 0x38D, 0xFF);
        let vtable = platform::read_u32(actor + 0x60) as usize;
        call2(
            platform::read_u32(vtable + 0xD4) as usize,
            actor as u32,
            STATE_80B741B8 as u32,
        );
    }

    // observed: the mask is `0x15 << (u8 at +0x348)`; PowerPC `slw` yields 0
    // for a shift of 32 or more, which `checked_shl` reproduces.
    let shift = platform::read_u8(actor + 0x348) as u32;
    let mask = platform::read_u32(actor + 0x274) & 0x15u32.checked_shl(shift).unwrap_or(0);
    if mask != 0 {
        platform::write_u8(actor + 0x348, platform::read_u8(actor + 0x348) ^ 1);
        write_f32(actor + 0xE8, -read_f32(actor + 0xE8));
        write_f32(actor + 0xF4, -read_f32(actor + 0xF4));
    }

    call3_f64(
        FN_80097170,
        read_f32(DAT_80B2ED38) as f64,
        actor as u32,
        (actor + 0xAC) as u32,
    );
    call2(FN_80064F50, actor as u32, 0);
