        call1(platform::read_u32(class_vtable + 0x6C) as usize, other as u32) as usize;
    let class_byte = platform::read_u8(class_name);

    platform::write_u8(actor + 0x432, 1);
    platform::write_u32(actor + 0x414, first);
    platform::write_u32(actor + 0x418, platform::read_u32(DAT_80B2EEC4));
    platform::write_u32(actor + 0x41C, platform::read_u32(DAT_80B2EEC8));
    platform::write_u32(actor + 0x420, platform::read_u32(DAT_80B2EECC));
    platform::write_u32(actor + 0x424, platform::read_u32(DAT_80B2EED0));
    platform::write_u32(actor + 0x428, platform::read_u32(DAT_80B2EED4));
    platform::write_u32(actor + 0x42C, platform::read_u32(DAT_80B2EED8));
    platform::write_u8(actor + 0x430, side);
    platform::write_u8(actor + 0x431, class_byte);
