    platform::write_u32(actor + 0xB4, platform::read_u32(target + 0x764));

    platform::write_u32(actor + 0xE8, speed);
    platform::write_u32(actor + 0xEC, platform::read_u32(0x80B2_F438));
    platform::write_u32(actor + 0xF0, platform::read_u32(0x80B2_F430));
    platform::write_u32(actor + 0xF4, platform::read_u32(0x80B2_F430));
    platform::write_u32(actor + 0xF8, platform::read_u32(0x80B2_F490));
    platform::write_u32(actor + 0xFC, platform::read_u32(0x80B2_F430));

    platform::write_u16(actor + 0x102, platform::read_u16(target + 0x102));
    platform::write_i32(actor + 0x5D4, 0);
    platform::write_u32(actor + 0x114, platform::read_u32(0x80B2_F494));
    platform::write_u16(actor + 0x5DC, 0x400);
