/// Allocates and constructs one `iron_ball` actor (size `0x698`).
///
/// Installs class vtable `0x80B690E8`, initialises the model holder at
/// `+0x524`, the motion/animation holder at `+0x544` and the polymorphic
/// helper at `+0x55C`, then stores the helper's temporary vtable
/// `0x8032989C` and calls its `+0x98` slot.
///
/// # Original
/// - Ghidra: `FUN_80b12f80` at `0x80B12F80` (192 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b12f80_FUN_80b12f80.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Returns
/// The new actor address, or 0 if the allocator failed.
///
/// # Side effects
/// Allocates `0x698` bytes and runs three sub-object constructors.
///
/// # Safety
/// The allocator and every constructor must be callable; the returned object
/// must not be used before this function completes.
///
/// # Confidence
/// high - allocation size, vtable and every sub-object offset are explicit.
pub unsafe fn fn_80b12f80() -> usize {
    let base = call1(FN_801628C0, 0x698) as usize;
    if base != 0 {
        call1(FN_80094E80, base as u32);
        platform::write_u32(base + 0x60, VT_IRON_BALL as u32);
        call1(FN_80069020, (base + 0x524) as u32);
        platform::write_u32(base + 0x540, 0);
        call1(FN_8016A2F0, (base + 0x544) as u32);
        platform::write_u8(base + 0x556, 1);
        call1(FN_802D7AA0, (base + 0x55C) as u32);
        platform::write_u32(base + 0x670, 0);
        platform::write_u32(base + 0x674, 0);
        platform::write_u8(base + 0x678, 0);
        platform::write_u8(base + 0x679, 0);
        platform::write_u32(base + 0x67C, 0);
        platform::write_u32(base + 0x680, 0);
        platform::write_u32(base + 0x55C, VT_8032989C as u32);
        let vtable = platform::read_u32(base + 0x55C) as usize;
        call1(
            platform::read_u32(vtable + 0x98) as usize,
            (base + 0x55C) as u32,
        );
    }
    base
}

/// Spawn initialiser of the `iron_ball` actor.
///
/// The actor is the incoming `r3`. The spawn is validated by
/// [`fn_80b13220`] and rejected through `0x80162510`;
/// otherwise [`fn_80b13300`] fixes the side byte at `+0x348`,
/// [`fn_80b13370`] builds the model holder and the body seeds the motion and
/// scale words, installs the `+0x148` and `+0x1EC` helpers, and enters one of
/// the four state descriptors from the spawn flags at `+0x04`.
///
/// # Original
/// - Ghidra: `FUN_80b13040` at `0x80B13040` (480 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b13040_FUN_80b13040.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
/// - Removed: the modelled `_savegpr_27` prologue call (`0x802DCD74`) and the
///   two `_restgpr_27` epilogue calls (`0x802DCDC0`). The image reads the actor
///   from the incoming `r3` (`mr r27,r3`) and ends each path with `li r3,0` or
///   `li r3,1`, so that word is the return value.
///
/// # Arguments
/// * `actor` - the iron-ball actor; the incoming `r3`.
///
/// # Returns
/// `1` on a successful spawn, `0` when [`fn_80b13220`] rejects it.
///
/// # Side effects
/// Allocates the model, writes most motion/scale fields and calls one state
/// entry through the class vtable.
///
/// # Safety
/// `actor` must be live and the model archive at `0x8042A038` must be open.
///
/// # Confidence
/// medium - every call, mask and table index is literal; the meaning of the
/// `+0x338` word and of the model handle at `+0x550` is inferred.
pub unsafe fn fn_80b13040(actor: usize) -> u32 {
    // observed: the export prints `FUN_80b13300()` with no argument because
    // r3 still holds the actor; the Rust call below passes it explicitly.
    fn_80b13300(actor);

    if fn_80b13220(actor) == 0 {
        call1(FN_80162510, actor as u32);
        return 0;
    }

    fn_80b13370(actor);

    let one = read_f32(DAT_80B32118);
    let zero = read_f32(DAT_80B32120);
    let sixteen = read_f32(DAT_80B32124);
    let thirty_two = read_f32(DAT_80B32128);
    let height = read_f32(DAT_80B3211C) + read_f32(DAT_8042BB08);
    let extra = read_f32(DAT_8042BB0C);

    platform::write_u16(actor + 0x102, 0);
    write_f32(actor + 0xDC, one);
    write_f32(actor + 0xE0, one);
    write_f32(actor + 0xE4, one);
    write_f32(actor + 0x320, zero);
    write_f32(actor + 0x324, sixteen);
    write_f32(actor + 0x318, thirty_two);
    write_f32(actor + 0x31C, thirty_two);
    write_f32(actor + 0x338, extra);
    write_f32(actor + 0x33C, extra);
    write_f32(actor + 0x340, height);
    write_f32(actor + 0x344, height);

    call3(
        FN_8008C3E0,
        (actor + 0x148) as u32,
        actor as u32,
        DAT_80B320D0 as u32,
    );
    platform::write_u8(actor + 0x1E6, 1);
    call1(FN_8008C330, (actor + 0x148) as u32);
    call5(
        FN_8006D090,
        (actor + 0x1EC) as u32,
        actor as u32,
        DAT_80B320B0 as u32,
        DAT_80B320A0 as u32,
        DAT_80B320C0 as u32,
    );
    call1(FN_80072BC0, (actor + 0x1EC) as u32);

    let model = call1(FN_80070CB0, (actor + 0x1EC) as u32);
    platform::write_u32(actor + 0x550, model);
    let second = call1(FN_80070CB0, (actor + 0x1EC) as u32);
    platform::write_u8(actor + 0x554, (second == 0) as u8);

    let flags = platform::read_u32(actor + 4);
    if (flags >> 0x1C) & 1 == 0 {
        if (flags >> 0x1D) & 1 == 0 {
            let variant = ((flags >> 0x10) & 0xF) as u8;
            write_f32(actor + 0xB4, read_f32(DAT_80B3212C));
            platform::write_u8(actor + 0x555, variant);
            if variant == 0 {
                switch_state(actor, DESC_80B78DB8);
            } else {
                switch_state(actor, DESC_80B78D78);
            }
        } else {
            switch_state(actor, DESC_80B78E38);
        }
    } else {
        write_f32(actor + 0xB4, read_f32(DAT_80B3212C));
        switch_state(actor, DESC_80B78DF8);
    }

    1
}

/// Spawn predicate: rejects the spawn while the global input masks are active
/// and, for "forced" spawns, when the side byte does not match the probe.
///
/// # Original
/// - Ghidra: `FUN_80b13220` at `0x80B13220` (216 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b13220_FUN_80b13220.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` - candidate spawn object carrying flags at `+0x04` and a side
///   byte at `+0x348`.
///
/// # Returns
/// `1` when the spawn may proceed, `0` when it must be discarded.
///
/// # Side effects
/// Reads the global input words and runs the spatial query `0x80064740`.
///
/// # Safety
/// The actor must be readable and the query helper callable.
///
/// # Confidence
/// medium - the two global checks and the `clz` side comparison are literal;
/// the side-byte role is inferred from the neighbouring handlers.
pub unsafe fn fn_80b13220(actor: usize) -> u32 {
    if platform::read_u8(DAT_80429D19) != 0 {
        let second = platform::read_u32(DAT_8042A07C) & platform::read_u32(DAT_80429D24);
        let first = platform::read_u32(DAT_8042A078) & platform::read_u32(DAT_80429D20);
        if second != 0 || first != 0 {
            return 0;
        }
    }

    let mut probe = [0f32; 5];
    if call2(
        FN_80064740,
        actor as u32,
        probe.as_mut_ptr() as u32,
    ) == 0
    {
        return 0;
    }

    if (platform::read_u32(actor + 4) >> 8) & 1 != 0 {
        // observed: clz( (0.0 <= x) ) >> 5 is 1 exactly when x < 0.0.
        let below = (probe[0] < read_f32(DAT_80B32120)) as u8;
        if below != platform::read_u8(actor + 0x348) {
            return 0;
        }
    }

    1
}

/// Sets the side byte at `+0x348` from the spawn flags.
///
/// Flags `(flags >> 4) & 3` read `1`, `0`, or fall back to the spatial query
/// `0x80096240(actor, actor+0xAC)`.
///
/// # Original
/// - Ghidra: `FUN_80b13300` at `0x80B13300` (100 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b13300_FUN_80b13300.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` - spawn object; flags at `+0x04`, position at `+0xAC`.
///
/// # Side effects
/// Writes `+0x348`.
///
/// # Safety
/// The actor must be readable and the query helper callable.
///
/// # Confidence
/// medium - the mask and the three arms are literal; the returned value's
/// exact side encoding is inferred from its use as a byte.
pub unsafe fn fn_80b13300(actor: usize) {
    let variant = (platform::read_u32(actor + 4) >> 4) & 3;
    if variant == 0 {
        platform::write_u8(actor + 0x348, 1);
    } else if variant == 1 {
        platform::write_u8(actor + 0x348, 0);
    } else {
        let result = call2(FN_80096240, actor as u32, (actor + 0xAC) as u32);
        platform::write_u8(actor + 0x348, result as u8);
    }
}

