    platform::write_u16(this + 0x102, 0);
    platform::write_u16(this + 0x104, 0x2000);
    platform::write_u32(this + 0xDC, zero_seed);
    platform::write_u32(this + 0xE0, zero_seed);
    platform::write_u32(this + 0xE4, zero_seed);
    platform::write_u32(this + 0x320, base_seed);
    platform::write_u32(this + 0x324, base_seed);
    platform::write_u32(this + 0x318, left_seed);
    platform::write_u32(this + 0x31C, left_seed);
    platform::write_u32(this + 0x338, height_seed);
    platform::write_u32(this + 0x33C, height_seed);
    platform::write_f32(this + 0x340, vertical);
    platform::write_f32(this + 0x344, vertical);
    platform::write_u32(this + 0xD0, base_seed);
    platform::write_u32(this + 0xD4, lateral_seed);
    platform::write_u32(this + 0xD8, base_seed);

