/// `this` must be readable at `+0xE8` and `+0xEC`.
///
/// # Confidence
/// high - both absolute values, the maximum and the scale are literal.
pub unsafe fn fn_80a14de0(this: usize) -> i32 {
    let mut magnitude = read_f32(this + 0xEC).abs();
    let vertical = read_f32(this + 0xE8).abs();
    if magnitude <= vertical {
        magnitude = vertical;
    }
    (read_f32(DAT_80B2B0FC) * magnitude) as i32
}

/// Main per-frame handler of the `Wm_en_iron` actor.
