    if (platform::read_u32(this + 0x60C) & 0xE) != 0 {
        platform::write_u8(this + 0x68D, 3);
        platform::write_u8(this + 0x694, 0xFF);
        fn_80a20b10(this);
        return;
    }

    let owner = platform::read_u32(this + 0x394) as usize;
    let getter = platform::read_u32(platform::read_u32(owner) as usize + 0x28) as usize;
    let state = call1(getter, owner as u32) as usize;
    let test = platform::read_u32(platform::read_u32(state) as usize + 0x14) as usize;
    if call2(test, state as u32, EN58_STATE_X1) == 0 {
        return;
    }

    let mode = call1(EN58_FN_800212C0, this as u32) as u8;
    if mode == 0 {
        return;
    }

    let set_clip = platform::read_u32(platform::read_u32(this + 0x60) as usize + 0xD4) as usize;
    if mode == 1 {
        call2(set_clip, this as u32, EN58_CLIP_A);
        platform::write_u8(this + 0x68A, 2);
        platform::write_u8(this + 0x689, 0);
    } else {
        call2(set_clip, this as u32, EN58_CLIP_B);
        platform::write_u8(this + 0x68A, 1);
        platform::write_u8(this + 0x689, 1);
    }

    call5(
        EN58_FN_800D0470,
        EN58_DAT_80429FC8 as u32,
        (this + 0x6EC) as u32,
        platform::read_u8(EN58_DAT_8042A1C8 + 0x120E) as u32,
        0,
        platform::read_u32(this + 0x700),
    );

    if platform::read_u32(this + 0x6F8) == 0 {
        // observed: six-word stack block; word 3 carries one byte in its top
        // position, word 4 is the literal `1`, word 5 is zero.
        let mut spawn = [0u32; 6];
        spawn[0] = platform::read_u32(this + 0xAC);
        spawn[1] = platform::read_u32(this + 0xB0);
        spawn[2] = platform::read_u32(this + 0xB4);
        spawn[3] = (platform::read_u8(this + 0x694) as u32) << 24;
        spawn[4] = 1;
        spawn[5] = 0;
        call2(EN58_FN_80022600, this as u32, spawn.as_mut_ptr() as u32);
    } else {
        call3(
            EN58_FN_80022080,
            this as u32,
            platform::read_u32(this + 0x6F8),
            platform::read_u8(this + 0x689) as u32,
        );
    }
