    platform::write_u16(this + 0x6A0, 0x32);
    platform::write_u32(this + 0x6FC, 3);
    platform::write_u32(this + 0x6D4, 0);
    platform::write_u32(this + 0x6D8, 0);
    platform::write_u32(this + 0x6DC, 0);
    platform::write_u32(this + 0x574, 0);
    platform::write_u32(this + 0x578, 0);
    platform::write_u32(this + 0x57C, 0);
