    platform::write_u32(element + 0x4C, 0);
    platform::write_u32(element + 0x48, EN67_DAT_803295D8);
    platform::write_u32(element + 0x50, 0);
    call1(FN_8016A5E0, (element + 0x54) as u32);
    platform::write_u32(element + 0x70, 0);
    platform::write_u32(element + 0x48, EN67_DAT_80329518);
    platform::write_u32(element + 0x74, 0);
    platform::write_u32(element + 0x78, EN67_DAT_803295D8);
    platform::write_u32(element + 0x7C, 0);
    platform::write_u32(element + 0x80, 0);
    call1(FN_8016A5E0, (element + 0x84) as u32);
    platform::write_u32(element + 0xA0, 0);
    platform::write_u32(element + 0x78, EN67_DAT_80329578);
    call1(FN_8007F7A0, (element + 0xC8) as u32);
    platform::write_u32(element + 0x1B0, 0);
    platform::write_u16(element + 0x1B4, 0);
