/// are explicit.
pub unsafe fn fn_80b05df0(actor: usize) {
    let rail = platform::read_u32(actor + 0x2B1C) as usize;
    fn_80b043f0(actor + 0x540, rail);
    fn_80b043f0(actor + 0x6FC, rail);
    let count = platform::read_i32(actor + 0x2B18);
    let mut element = actor + 0x8B8;
    let mut index = 0;
    while index < count {
        fn_80b043f0(element, rail);
        element += 0x1B8;
        index += 1;
    }

    if fn_80b05620(actor) {
        call2(FN_80064D10, actor as u32, 1);
    }
}

/// Per-frame integration of the whole chain while the chain is still growing.
///
/// Each segment's holder is settled (`0x8007F950` on `+0xC8` when the
/// sub-object flag at `+0x6E4`/`+0x1A4` is set), then [`fn_80b043c0`] applies
/// gravity and the position is advanced by the per-segment velocity. The second
/// segment is only advanced while `count << 3` is below `+0x2B30`, and the
/// trailing loop is clamped to `+0x2B30 >> 3`. Finally `+0x2B30` is incremented
/// and the actor may switch out.
///
/// # Original
/// - Ghidra: `FUN_80b05f00` at `0x80B05F00` (420 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b05f00_FUN_80b05f00.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor`: the rail actor.
///
/// # Side effects
/// Float updates on every segment position, holder settles, `+0x2B30`
/// incremented and a possible call to `0x80064D10(actor, 1)`.
///
/// # Safety
/// Every segment holder and the frame timer must be valid.
///
/// # Confidence
/// high - the guards, the two clamps and every float add are literal; the
/// duplicated `0x8007F950` call in the trailing loop is reproduced as printed.
pub unsafe fn fn_80b05f00(actor: usize) {
    if platform::read_u8(actor + 0x6E4) != 0 {
        call1(FN_8007F950, (actor + 0x608) as u32);
    }
    fn_80b043c0(actor + 0x540);
    write_f32(
        actor + 0x5E4,
        read_f32(actor + 0x5E4) + read_f32(actor + 0x5F0),
    );
    write_f32(
        actor + 0x5E8,
        read_f32(actor + 0x5E8) + read_f32(actor + 0x5F4),
    );
    write_f32(
        actor + 0x5EC,
        read_f32(actor + 0x5EC) + read_f32(actor + 0x5F8),
    );

    if (platform::read_i32(actor + 0x2B18) << 3) < platform::read_i32(actor + 0x2B30) {
        if platform::read_u8(actor + 0x8A0) != 0 {
            call1(FN_8007F950, (actor + 0x7C4) as u32);
        }
        fn_80b043c0(actor + 0x6FC);
        write_f32(
            actor + 0x7A0,
            read_f32(actor + 0x7A0) + read_f32(actor + 0x7AC),
        );
        write_f32(
            actor + 0x7A4,
            read_f32(actor + 0x7A4) + read_f32(actor + 0x7B0),
        );
        write_f32(
            actor + 0x7A8,
            read_f32(actor + 0x7A8) + read_f32(actor + 0x7B4),
        );
    }

    let mut limit = platform::read_i32(actor + 0x2B30) >> 3;
    let last = platform::read_i32(actor + 0x2B18) - 1;
    if last < limit {
        limit = last;
    }

    let mut element = actor + 0x8B8;
    let mut index = 0;
    while index < limit + 1 {
        call1(FN_8007F950, (element + 0xC8) as u32);
        if platform::read_u8(element + 0x1A4) != 0 {
            call1(FN_8007F950, (element + 0xC8) as u32);
        }
        fn_80b043c0(element);
        write_f32(
            element + 0xA4,
            read_f32(element + 0xA4) + read_f32(element + 0xB0),
        );
        write_f32(
            element + 0xA8,
            read_f32(element + 0xA8) + read_f32(element + 0xB4),
        );
        write_f32(
            element + 0xAC,
            read_f32(element + 0xAC) + read_f32(element + 0xB8),
        );
        element += 0x1B8;
        index += 1;
    }

    platform::write_i32(
        actor + 0x2B30,
        platform::read_i32(actor + 0x2B30) + 1,
    );

    if fn_80b05620(actor) {
        call2(FN_80064D10, actor as u32, 1);
    }
}

