    call3_f64(
        FN_80169F80,
        read_f32(0x80B3_12A0) as f64,
        (actor + 0x544) as u32,
        (actor + 0x584) as u32,
    );
    call2_f64(
        FN_801680E0,
        read_f32(0x80B3_129C) as f64,
        (actor + 0x584) as u32,
    );
    call3(FN_80167B60, (actor + 0x5C0) as u32, 0, 0);
    call3_f64(
        FN_80169F80,
        read_f32(0x80B3_129C) as f64,
        (actor + 0x544) as u32,
        (actor + 0x5C0) as u32,
    );
