/// # Original
/// - Ghidra: `FUN_80af0660` at `0x80AF0660` (248 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80af0660_FUN_80af0660.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor`: red-ring actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the `+0xDC..+0xE4` triple, the `+0x102` angle and `+0x6D4` step, and
/// may switch the state record.
///
/// # Safety
/// The two holders, the `+0x394` object and the byte table must be valid.
///
/// # Confidence
/// high - the constants, the two branches and the table scaling are literal.
pub unsafe fn fn_80af0660(actor: usize) {
    invoke_slot(actor + 0x544, 0x1C);
    invoke_slot(actor + 0x5C0, 0x14);

    let next = read_f32(actor + 0xDC) - read_f32(0x80B3_12B8); // 0.03515625
    if read_f32(0x80B3_12A0) <= next {
        write_f32(actor + 0xDC, next);
        write_f32(actor + 0xE0, next);
        write_f32(actor + 0xE4, next);
        let step = platform::read_u16(actor + 0x6D4);
        platform::write_u16(
            actor + 0x102,
            platform::read_u16(actor + 0x102).wrapping_add(step),
        );
        if platform::read_u16(actor + 0x500) == 0 {
            // observed: the signed table byte is scaled by 0x300 and truncated
            // to a 16-bit angle before the 0x8015F340 call.
            let side = platform::read_u8(actor + 0x348) ^ 1;
            let signed = platform::read_u8(DAT_8042C1A0 + side as usize) as i8 as i32;
            let delta = signed.wrapping_mul(0x300) as i16 as i32;
            call3(FN_8015F340, (actor + 0x6D4) as u32, delta as u32, 0x20);
        }
    } else {
        let class_vtable = platform::read_u32(actor + 0x60) as usize;
        call2(
            platform::read_u32(class_vtable + 0xD4) as usize,
            actor as u32,
            0x80B7_7890,
        );
        invoke_slot(actor + 0x394, 0x1C);
    }
}

