    request[1] = if platform::read_u8(actor + 0x68D) == 2 {
        (read_f32(actor + 0xB0) + read_f32(0x80B3_1504)).to_bits()
    } else {
        (read_f32(actor + 0xB0) - read_f32(0x80B3_1504)).to_bits()
    };
    request[2] = read_f32(actor + 0xB4).to_bits();
    request[3] = (platform::read_u8(actor + 0x694) as u32) << 24;
    request[4] = item;
    request[5] = 2 << 24;

