///
/// # Confidence
/// medium - the shape is literal; the slot argument is inferred from `r3`.
pub unsafe fn fn_80a52780(object: usize) -> usize {
    let mut current = object;
    let mut step = 0;
    while step < 5 {
        let owner = platform::read_u32(current + 0x30) as usize;
        let vtable = platform::read_u32(owner) as usize;
        // inferred: the +0xC slot takes the owner in r3.
        if call1(platform::read_u32(vtable + 0xC) as usize, owner as u32) != 0 {
            return current;
        }
        current = owner;
        step += 1;
    }
    fn_80a52780(platform::read_u32(current + 0x30) as usize)
}

