/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b20300_FUN_80b20300.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor`: the `0x678`-byte actor.
/// - `other`: the neighbouring object whose `+0x38C` mode drives the test.
///
/// # Side effects
/// May decrement `actor + 0x568` and switch the actor's state.
///
/// # Safety
/// Both objects must be live and `other + 0x38C` readable.
///
/// # Confidence
/// medium - the two mode branches and the retraction block are literal; the
/// role of `0x80056BD0` is `// unknown:` and the descriptor is only known by
/// its address.
pub unsafe fn fn_80b20300(actor: usize, other: usize) {
    let mode = platform::read_u8(other + 0x38C);
    let probe = call2(FN_80056CF0, other as u32, 0x1C) != 0;
    let retract = if mode == 1 {
        probe && call1(FN_80056BD0, other as u32) == 0
    } else if mode == 2 {
        probe
    } else {
        false
    };

    if retract {
        let embedded = actor + 0x394;
        let getter = platform::read_u32(platform::read_u32(embedded) as usize + 0x28) as usize;
        let target = call1(getter, embedded as u32) as usize;
        let test = platform::read_u32(platform::read_u32(target) as usize + 0x14) as usize;
        if call2(test, target as u32, W79_DESC_80B794B8 as u32) != 0 {
            platform::write_i32(actor + 0x568, platform::read_i32(actor + 0x568) - 1);
            switch_state(actor, W79_DESC_80B794F8);
        }
    }
}

