/// # Original
/// - Ghidra: `FUN_80b24d90` at `0x80B24D90` (328 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b24d90_FUN_80b24d90.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor`: the `0x678`-byte actor; `+0x524` selects the variant.
///
/// # Side effects
/// Fills three BSS tables on first call and writes `+0x164`..`+0x170`.
///
/// # Safety
/// `actor` must be live, and the three BSS tables writable.
///
/// # Confidence
/// medium - the copies, strides and scales are literal; the meaning of the
/// resulting four words is `// unknown:`.
pub unsafe fn fn_80b24d90(actor: usize) {
    // observed: the three tables live in BSS with one-byte init guards.
    if platform::read_u8(W79_BSS_80B797A8) == 0 {
        let zero = platform::read_u32(W79_DAT_80B32A1C);
        let one = platform::read_u32(W79_DAT_80B32A1C + 4);
        let minus_one = platform::read_u32(W79_DAT_80B32A1C + 8);
        platform::write_u32(W79_BSS_80B797B0 + 0x00, zero);
        platform::write_u32(W79_BSS_80B797B0 + 0x04, one);
        platform::write_u32(W79_BSS_80B797B0 + 0x08, zero);
        platform::write_u32(W79_BSS_80B797B0 + 0x0C, minus_one);
        platform::write_u32(W79_BSS_80B797B0 + 0x10, one);
        platform::write_u32(W79_BSS_80B797B0 + 0x14, zero);
        platform::write_u32(W79_BSS_80B797B0 + 0x18, minus_one);
        platform::write_u32(W79_BSS_80B797B0 + 0x1C, zero);
        platform::write_u8(W79_BSS_80B797A8, 1);
    }
    if platform::read_u8(W79_BSS_80B797D0) == 0 {
        let zero = platform::read_u32(W79_DAT_80B32A1C);
        let one = platform::read_u32(W79_DAT_80B32A1C + 4);
        platform::write_u32(W79_BSS_80B797D8 + 0x00, one);
        platform::write_u32(W79_BSS_80B797D8 + 0x04, zero);
        platform::write_u32(W79_BSS_80B797D8 + 0x08, one);
        platform::write_u32(W79_BSS_80B797D8 + 0x0C, zero);
        platform::write_u32(W79_BSS_80B797D8 + 0x10, zero);
        platform::write_u32(W79_BSS_80B797D8 + 0x14, one);
        platform::write_u32(W79_BSS_80B797D8 + 0x18, zero);
        platform::write_u32(W79_BSS_80B797D8 + 0x1C, one);
        platform::write_u8(W79_BSS_80B797D0, 1);
    }
    if platform::read_u8(W79_BSS_80B797F8) == 0 {
        let zero = platform::read_u32(W79_DAT_80B32A1C);
        let one = platform::read_u32(W79_DAT_80B32A1C + 4);
        platform::write_u32(W79_BSS_80B79800 + 0x00, zero);
        platform::write_u32(W79_BSS_80B79800 + 0x04, one);
        platform::write_u32(W79_BSS_80B79800 + 0x08, zero);
        platform::write_u32(W79_BSS_80B79800 + 0x0C, one);
        platform::write_u32(W79_BSS_80B79800 + 0x10, one);
        platform::write_u32(W79_BSS_80B79800 + 0x14, zero);
        platform::write_u32(W79_BSS_80B79800 + 0x18, one);
        platform::write_u32(W79_BSS_80B79800 + 0x1C, zero);
        platform::write_u8(W79_BSS_80B797F8, 1);
    }

    let offset = platform::read_u32(actor + 0x524) as usize * 8;
    let outer = read_f32(W79_F32_80B32A28);
    let inner = read_f32(W79_F32_80B329D8);

    let first = read_f32(W79_BSS_80B797B0 + offset);
    let first_peer = read_f32(W79_BSS_80B797B4 + offset);
    let second = read_f32(W79_BSS_80B797D8 + offset);
    let second_peer = read_f32(W79_BSS_80B797DC + offset);
    let third = read_f32(W79_BSS_80B79800 + offset);
    let third_peer = read_f32(W79_BSS_80B79804 + offset);

    write_f32(actor + 0x164, outer * first);
    write_f32(actor + 0x168, outer * first_peer);
    write_f32(actor + 0x16C, inner * second + outer * third);
    write_f32(actor + 0x170, inner * second_peer + outer * third_peer);
}

/// Toggles the `+0x148` emitter from the two input-mask flag words.
///
/// When either `+0x35C` or `+0x358` is non-zero the function requires the
/// pair at `0x8042A078` to be set: if both masked tests fail it stops the
/// emitter (`0x8008C330`) and clears `+0x534`, otherwise it starts the emitter
/// (`0x8008C380`), sets `+0x534 = 1` and reports `0`.
///
/// # Original
/// - Ghidra: `FUN_80b24ee0` at `0x80B24EE0` (168 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b24ee0_FUN_80b24ee0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor`: the `0x678`-byte actor.
///
/// # Returns
/// `1` when nothing had to change, `0` when the emitter was started.
///
/// # Side effects
/// Starts or stops the emitter at `+0x148` and writes `+0x534`.
///
/// # Safety
/// `actor` must be live and the global mask pair mapped.
///
/// # Confidence
/// medium - the mask test and both emitter calls are literal; the two flag
/// words are identified only by the shared `0x8042A078` mask pair.
pub unsafe fn fn_80b24ee0(actor: usize) -> u32 {
    let mut result = 1;
    let low_flags = platform::read_u32(actor + 0x358);
    let high_flags = platform::read_u32(actor + 0x35C);
    if high_flags != 0 || low_flags != 0 {
        let low_mask = platform::read_u32(DAT_8042A078);
        let high_mask = platform::read_u32(DAT_8042A078 + 4);
        if (high_flags & high_mask) == 0 && (low_flags & low_mask) == 0 {
            if platform::read_i32(actor + 0x534) != 0 {
                call1(FN_8008C330, (actor + 0x148) as u32);
            }
            platform::write_u32(actor + 0x534, 0);
        } else {
            if platform::read_i32(actor + 0x534) == 0 {
                call1(FN_8008C380, (actor + 0x148) as u32);
            }
            platform::write_u32(actor + 0x534, 1);
            result = 0;
        }
    }
    result
}

