    if first != 0 {
        rhs = first + 1;
    }

    let vtable = platform::read_u32(object) as usize;
    let get_name = platform::read_u32(vtable + 0x20) as usize;
    let lhs = call1(get_name, object as u32) as usize;

    let second = call2(EN83_FN_802E1C40, lhs as u32, 0x3A) as usize;
    // observed: the original adds one even when the search returned null.
    call2(EN83_FN_802E1AB4, (second + 1) as u32, rhs as u32) == 0
