/// Shifts the trail ring one record toward the tail and seeds the head record
/// from the actor's `+0x5C4`/`+0x5C8` position.
///
/// The two pointer walks start at records `count-1` and `count-2` and move
/// backwards one record per step, so record `i` receives record `i-1`. The
/// head record then gets the current X/Y, the three angle halfwords
/// `+0x5D0..+0x5D4`, the segment length from `0x802BE470` and the per-segment
/// angle pair from `0x800708C0`/`0x80070820`. When the side byte `+0x348` is
/// zero the stored halfword angle is negated.
///
/// # Original
/// - Ghidra: `FUN_80a10410` at `0x80A10410` (380 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a10410_FUN_80a10410.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the segmented trail actor (`+0x928` count, `+0x92C` block).
///
/// # Side effects
/// Writes the whole record ring and refreshes the head record's angle fields.
///
/// # Safety
/// `+0x92C` must point at a block of at least `count * 0x1C` bytes and the
/// animation holder at `+0x1EC` must be live.
///
/// # Confidence
/// medium - every field copy, the `sqrt`, the two angle queries and the
/// negation are literal; the record field roles are inferred from the two
/// functions that consume them (`fn_80a10220`, `fn_80a10880`).
pub unsafe fn fn_80a10410(this: usize) {
    let count = platform::read_i32(this + 0x928);
    let ring = platform::read_u32(this + 0x92C) as usize;
    let stride = 0x1Cisize;

    // observed: the two pointers are seeded from `count - 1` and `count - 2`
    // even when the loop body never runs, so the signed arithmetic is kept.
    let mut dst = (ring as isize + (count as isize - 1) * stride) as usize;
    let mut src = (ring as isize + (count as isize - 2) * stride) as usize;
    let mut index = 0i32;
    while index < count - 1 {
        platform::write_u32(dst, platform::read_u32(src));
        platform::write_u32(dst + 4, platform::read_u32(src + 4));
        platform::write_u16(dst + 8, platform::read_u16(src + 8));
        platform::write_u16(dst + 10, platform::read_u16(src + 10));
        platform::write_u16(dst + 12, platform::read_u16(src + 12));
        platform::write_u32(dst + 16, platform::read_u32(src + 16));
        platform::write_u32(dst + 20, platform::read_u32(src + 20));
        platform::write_u16(dst + 24, platform::read_u16(src + 24));
        dst = (dst as isize - stride) as usize;
        src = (src as isize - stride) as usize;
        index += 1;
    }

    let record = ring;
    let y = read_f32(this + 0x5C8);
    // observed: the export subtracts `+0x5CC` from itself, so this term is
    // always zero and is kept only to mirror the distance expression.
    let cancelled = read_f32(this + 0x5CC) - read_f32(this + 0x5CC);
    let previous_x = read_f32(record + 0x1C);
    let previous_y = read_f32(record + 0x20);
    let dx = read_f32(this + 0x5C4) - previous_x;
    let dy = y - previous_y;

    write_f32(record, read_f32(this + 0x5C4));
    write_f32(record + 4, y);
    platform::write_u16(record + 8, platform::read_u16(this + 0x5D0));
    platform::write_u16(record + 10, platform::read_u16(this + 0x5D2));
    platform::write_u16(record + 12, platform::read_u16(this + 0x5D4));

    let length = call1_f64_ret_f32(
        EN85_FN_802BE470,
        (cancelled * cancelled + dx * dx + dy * dy) as f64,
    );
    write_f32(record + 16, length);

    let angle = call2(
        EN85_FN_800708C0,
        (this + 0x1EC) as u32,
        0,
    ) as u16;
    platform::write_u16(record + 24, angle);
    let rate = call2_ret_f32(
        EN85_FN_80070820,
        (this + 0x1EC) as u32,
        platform::read_u8(this + 0x348) as u32,
    );
    write_f32(record + 20, rate);

    // observed: the head record's halfword angle is stored negated on side 0.
    if platform::read_u8(this + 0x348) == 0 {
        let stored = platform::read_u16(record + 24);
        platform::write_u16(record + 24, 0u16.wrapping_sub(stored));
    }
}

/// Binds both collision descriptors and both walk clips on every segment of
/// the trail actor.
