/// Returns the pointer to a player's character-type byte through class slot
/// `+0x6C`.
///
/// Every player object in this REL stores its class vtable at `+0x60`; slot
/// `+0x6C` returns a pointer to the byte that indexes [`W89_PLAYER_MASKS`].
#[inline]
unsafe fn w89_player_kind(player: usize) -> usize {
    let vtable = platform::read_u32(player + 0x60) as usize;
    let f = crate::platform::guest_fn!(platform::read_u32(vtable + 0x6C) as usize, fn(u32) -> usize);
    f(player as u32)
}

/// Calls one one-argument class virtual method at `vtable + slot` and returns
/// the word it leaves in `r3`.
#[inline]
unsafe fn w89_class_slot(actor: usize, slot: usize) -> u32 {
    let vtable = platform::read_u32(actor + 0x60) as usize;
    call1(platform::read_u32(vtable + slot) as usize, actor as u32)
}

