/// Converts an unsigned 32-bit value to `f32` with the `2^52` bias idiom.
///
/// The export writes `CONCAT44(0x43300000, value) - DAT_80b2f6e8`; the two
/// words form the double `2^52 + value`, so the subtraction leaves `value`.
#[inline]
unsafe fn w90_u32_to_f32(value: u32) -> f32 {
    let biased = f64::from_bits(0x4330_0000_0000_0000 | value as u64);
    (biased - read_f64(0x80B2_F6E8)) as f32
}

/// Returns the pointer to a player's character-type byte through class slot
/// `+0x6C`.
#[inline]
unsafe fn w90_player_kind(player: usize) -> u8 {
    let vtable = platform::read_u32(player + 0x60) as usize;
    let f = crate::platform::guest_fn!(platform::read_u32(vtable + 0x6C) as usize, fn(u32) -> usize);
    platform::read_u8(f(player as u32))
}

/// Enters one state record through the class vtable slot `+0xD4`.
#[inline]
unsafe fn w90_set_state(this: usize, state: usize) {
    let vtable = platform::read_u32(this + 0x60) as usize;
    call2(
        platform::read_u32(vtable + 0xD4) as usize,
        this as u32,
        state as u32,
    );
}

/// Calls one one-argument class virtual method at `vtable + slot`.
#[inline]
unsafe fn w90_class_call0(this: usize, slot: usize) {
    let vtable = platform::read_u32(this + 0x60) as usize;
    call1(platform::read_u32(vtable + slot) as usize, this as u32);
}

