    platform::write_u32(this + 0x41C, platform::read_u32(W90_GLOBAL_TRIPLE + 8));
    platform::write_u32(this + 0x420, platform::read_u32(W90_GLOBAL_TRIPLE));
    platform::write_u32(this + 0x424, platform::read_u32(0x80B2_F778));
    platform::write_u32(this + 0x428, combo);
    platform::write_u32(this + 0x42C, platform::read_u32(0x80B2_F780));
