/// - `actor`: `dossun` actor whose variant is read from `+0x5D0`.
///
/// # Side effects
/// Writes seven fields and emits one sound.
///
/// # Safety
/// The actor, its `+0x148` object and the sound manager must be valid.
///
/// # Confidence
/// high - all nine stores, the two sound ids and the variant branch are
/// literal; the constant values were read from the ELF.
pub unsafe fn fn_80a54120(actor: usize) {
    // unknown: 0x800A16A0 is a per-frame bookkeeping call with no visible
    // field writes of its own.
    call1(FN_800A16A0, actor as u32);

    platform::write_u16(actor + 0x100, 0);
    platform::write_u16(actor + 0x102, 0);

    let mut point = [0u32; 4];
    call2(FN_8006A4B0, point.as_mut_ptr() as u32, (actor + 0xAC) as u32);
    let id = if platform::read_u32(actor + 0x5D0) == 0 {
        0x20F
    } else {
        0x210
    };
    call4(
        FN_80197F00,
        platform::read_u32(DAT_80429D5C),
        id,
        point.as_ptr() as u32,
        0,
    );

    call1(FN_8008C380, (actor + 0x148) as u32);

    platform::write_u32(actor + 0xB4, platform::read_u32(W91_DAT_80B2CE0C));
    let speed = if platform::read_u32(actor + 0x5D0) == 1 {
        W91_DAT_80B2CD88
    } else {
        W91_DAT_80B2CE10
    };
    platform::write_u32(actor + 0x114, platform::read_u32(speed));
    platform::write_u32(actor + 0xF8, platform::read_u32(W91_DAT_80B2CD84));
    platform::write_u32(actor + 0xEC, platform::read_u32(W91_DAT_80B2CE14));
    platform::write_u16(actor + 0x500, 0x0D);
}

