pub unsafe fn fn_80a2b6d0(this: usize) {
    let vtable = platform::read_u32(this + 0x60) as usize;
    call2(
        platform::read_u32(vtable + 0xD4) as usize,
        this as u32,
        W92_STATE_80352BB4,
    );
    let upper = platform::read_i32(this + 0x6E0);
    platform::write_i32(this + 0x6E0, upper >> 1);
    let lower = platform::read_i32(this + 0x6DC);
    platform::write_i32(this + 0x6DC, lower >> 1);
}

