/// Fourth copy of the `+0x30` owner-chain walker.
///
/// # Original
/// - Ghidra: `FUN_80a4fa30` at `0x80A4FA30` (224 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a4fa30_FUN_80a4fa30.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `object`: first object of the chain.
///
/// # Returns
/// The last object whose owner still reported zero, or the recursive result.
///
/// # Side effects
/// Invokes the `+0xC` predicate of every owner visited.
///
/// # Safety
/// Every owner and its vtable must be valid until the walk leaves it.
///
/// # Confidence
/// medium - identical to [`fn_80a4d6e0`]; the `+0xC` argument is inferred.
pub unsafe fn fn_80a4fa30(object: usize) -> usize {
    let mut current = object;
    let mut step = 0;
    while step < 5 {
        let owner = platform::read_u32(current + 0x30) as usize;
        let vtable = platform::read_u32(owner) as usize;
        // inferred: the +0xC slot takes the owner in r3 with no printed
        // argument.
        if call1(platform::read_u32(vtable + 0xC) as usize, owner as u32) != 0 {
            return current;
        }
        current = owner;
        step += 1;
    }
    fn_80a4fa30(platform::read_u32(current + 0x30) as usize)
}

/// Fourth copy of the `:`-suffix name predicate.
///
/// # Original
/// - Ghidra: `FUN_80a4fb10` at `0x80A4FB10` (136 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a4fb10_FUN_80a4fb10.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `object`: object whose `+0x20` vtable slot supplies its name.
/// - `name`: candidate `char*`.
///
/// # Returns
/// `true` when the two suffixes compare equal.
///
/// # Side effects
/// One vtable call and two string calls; no writes.
///
/// # Safety
/// Both strings must be NUL-terminated and the object's vtable valid.
///
/// # Confidence
/// medium - identical to [`fn_80a4d7c0`].
pub unsafe fn fn_80a4fb10(object: usize, name: usize) -> bool {
    let mut suffix = name;
    let colon = call2(FN_802E1C40, name as u32, 0x3A);
    if colon != 0 {
        suffix = colon as usize + 1;
    }

    let vtable = platform::read_u32(object) as usize;
    let own = call1(platform::read_u32(vtable + 0x20) as usize, object as u32) as usize;
    let colon = call2(FN_802E1C40, own as u32, 0x3A);

    call2(FN_802E1AB4, colon.wrapping_add(1), suffix as u32) == 0
}

