    platform::write_u32(actor + 0x5E0, platform::read_u32(actor + 0xE8));
    platform::write_u32(actor + 0x5E4, platform::read_u32(actor + 0xEC));
    platform::write_u32(actor + 0x5E8, platform::read_u32(actor + 0xF0));
