    let carried = (platform::read_u32(this + 4) >> 0x15) & 1 != 0;
    let touched = platform::read_u32(this + 0x35C) & platform::read_u32(W95_MASK_8042A07C) != 0
        || platform::read_u32(this + 0x358) & platform::read_u32(W95_MASK_8042A078) != 0;
