// --- Local helpers. ---

/// Invokes a two-argument virtual method of an object whose first word is its
/// vtable.
#[inline]
unsafe fn w96_slot2(object: usize, slot: usize, arg: u32) -> u32 {
    let vtable = platform::read_u32(object) as usize;
    call2(
        platform::read_u32(vtable + slot) as usize,
        object as u32,
        arg,
    )
}

/// Tests whether two floats lie strictly on opposite sides of zero.
#[inline]
unsafe fn w96_opposite(first: usize, second: usize) -> bool {
    let a = read_f32(first);
    let b = read_f32(second);
    (a < 0.0 && 0.0 < b) || (0.0 < a && b < 0.0)
}

/// Clamps a speed magnitude the way the export compares it.
#[inline]
fn w96_abs(value: f32) -> f32 {
    if value < 0.0 {
        -value
    } else {
        value
    }
}

/// Registers the two-slot `+0x544` holder step.
///
/// The export reaches the method through the holder's vtable but leaves `r3`
/// pointing at the actor, so the actor - not the holder - is the argument.
///
/// # Original
/// - Ghidra: `FUN_80b10110` at `0x80B10110` (16 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b10110_FUN_80b10110.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `this` - the trail actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Tail-calls the `+0x544` holder's vtable slot `+0x14`.
///
/// # Safety
/// `this + 0x544` must hold a vtable pointer whose slot `+0x14` is callable.
///
/// # Confidence
/// medium - the loads and the tail call are literal; the argument is the actor
/// only because `r3` is never reloaded before `bctr`.
pub unsafe fn fn_80b10110(this: usize) {
    let holder = platform::read_u32(this + 0x544) as usize;
    let slot = platform::read_u32(holder + 0x14) as usize;
    call1(slot, this as u32);
}

/// Same holder step as [`fn_80b10110`], through `+0x5BC`.
///
/// # Original
/// - Ghidra: `FUN_80b10120` at `0x80B10120` (16 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b10120_FUN_80b10120.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
