    let step_y = read_f32(corner + 4) * 0.03125;
    let mut dst = this + 0x5EC;
    for _ in 0..4 {
        for _ in 0..16 {
            write_f32(dst, x);
            write_f32(dst + 4, y);
            dst += 8;
            x -= step_x;
            y -= step_y;
        }
    }
