    let vtable = platform::read_u32(sub) as usize;
    let current = call1(platform::read_u32(vtable + 0x2C) as usize, sub as u32) as usize;
    if object_has_name(current, W98_STATE_80B6ED58, 0x14) != 0 {
        return;
    }

    let clip = call2(W98_FN_8023A0B0, (this + 0x540) as u32, W98_STR_CLIP_WAIT as u32);
    let mut clip_slot = [clip];
    call4(
        W98_FN_801651F0,
        (this + 0x5CC) as u32,
        (this + 0x54C) as u32,
        clip_slot.as_mut_ptr() as u32,
        0,
    );
    call3_f64(
        W98_FN_80169F80,
        read_f32(W98_DAT_80B2AC64) as f64,
        (this + 0x54C) as u32,
        (this + 0x5CC) as u32,
    );
    call2_f64(
        W98_FN_801680E0,
        read_f32(W98_DAT_80B2AC34) as f64,
        (this + 0x5CC) as u32,
    );

    if platform::read_u32(this + 0x750) == 0 {
        return;
    }
    let eye_clip = call2(W98_FN_8023A0B0, (this + 0x548) as u32, W98_STR_EYE_WAIT as u32);
    let mut eye_clip_slot = [eye_clip];
    call4(
        W98_FN_801651F0,
        (this + 0x6DC) as u32,
        (this + 0x69C) as u32,
        eye_clip_slot.as_mut_ptr() as u32,
        0,
    );
    call3_f64(
        W98_FN_80169F80,
        read_f32(W98_DAT_80B2AC64) as f64,
        (this + 0x69C) as u32,
        (this + 0x6DC) as u32,
    );
    call2_f64(
        W98_FN_801680E0,
        read_f32(W98_DAT_80B2AC34) as f64,
        (this + 0x6DC) as u32,
    );

    let track = call2(W98_FN_8023A200, (this + 0x548) as u32, W98_STR_EYE_WAIT as u32);
    platform::write_u32(this + 0x714, track);
    let mut track_slot = [track];
