/// # Original
/// - Ghidra: `FUN_80a0bef0` at `0x80A0BEF0` (224 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a0bef0_FUN_80a0bef0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this` - `basabasa` actor.
///
/// # Side effects
/// Emits sound `0x1F0`, writes `+0x102` and `+0x118`, drives the eye holder.
///
/// # Safety
/// The eye holder and the sound manager must be valid.
///
/// # Confidence
/// medium - the clip name, the sound id and the two stores are literal; the
/// `-2.0` word is quoted as raw data, its unit is not established.
pub unsafe fn fn_80a0bef0(this: usize) {
    if platform::read_u32(this + 0x750) != 0 {
        let clip = call2(W98_FN_8023A0B0, (this + 0x548) as u32, W98_STR_EYE_FALL as u32);
        let mut clip_slot = [clip];
        call4(
            W98_FN_801651F0,
            (this + 0x6DC) as u32,
            (this + 0x69C) as u32,
            clip_slot.as_mut_ptr() as u32,
            0,
        );
        call3_f64(
            W98_FN_80169F80,
            read_f32(W98_DAT_80B2AC38) as f64,
            (this + 0x69C) as u32,
            (this + 0x6DC) as u32,
        );
        call2_f64(
            W98_FN_801680E0,
            read_f32(W98_DAT_80B2AC34) as f64,
            (this + 0x6DC) as u32,
        );
    }

    let mut position = [0u8; 20];
    call2(
        W98_FN_8006A4B0,
        position.as_mut_ptr() as u32,
        (this + 0xAC) as u32,
    );
    call4(
        W98_FN_80197F00,
        platform::read_u32(W98_DAT_80429D5C),
        0x1F0,
        position.as_mut_ptr() as u32,
        0,
    );

    call2_f64(
        W98_FN_80168FE0,
        read_f32(W98_DAT_80B2AC38) as f64,
        (this + 0x6DC) as u32,
    );
    call2_f64(
        W98_FN_801680E0,
        read_f32(W98_DAT_80B2AC38) as f64,
        (this + 0x6DC) as u32,
    );
    platform::write_u16(this + 0x102, 0x8000);
    platform::write_u32(this + 0x118, platform::read_u32(W98_DAT_80B2AC90));
}

/// Per-frame dive handler: spins the heading, catches players below, and
/// falls back to the ground/state test.
///
/// The eye holder and controller step, the two base frame steps run, and the
/// heading `+0x102` advances by four times the `main.dol` halfword table entry
/// at `0x8042C1A8 + side*2`. A latched player within `40.0` below the actor, or
/// a cleared ground probe at `y - 56.0`, or the actor being at or under the
/// stage bound, all enter state `0x80B6ECD8`.
///
/// # Original
/// - Ghidra: `FUN_80a0bfe0` at `0x80A0BFE0` (384 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a0bfe0_FUN_80a0bfe0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this` - `basabasa` actor in the dive state.
///
/// # Side effects
/// Writes `+0x102`, may change state.
///
/// # Safety
/// The holders and the player objects must be valid.
///
/// # Confidence
/// medium - every branch and the table read are literal; the dropped argument
/// of `0x8005F900` is inferred from [`fn_80a0b770`].
pub unsafe fn fn_80a0bfe0(this: usize) {
    if platform::read_u32(this + 0x750) != 0 {
        invoke_slot(this + 0x69C, 0x1C);
        invoke_slot(this + 0x718, 0x14);
    }
    call1(W98_FN_8006CE70, this as u32);
    call1(W98_FN_8006CD40, this as u32);

    let side = platform::read_u8(this + 0x348) as usize;
    let delta = read_i16(W98_TBL_8042C1A8 + side * 2).wrapping_mul(4);
    platform::write_u16(
        this + 0x102,
        platform::read_u16(this + 0x102).wrapping_add(delta as u16),
    );

    let slot = platform::read_u8(this + 0x74C) as i8;
    if slot >= 0 {
        let target = call1(W98_FN_8005F900, (slot as i32) as u32) as usize;
        if target != 0
            && read_f32(this + 0xB0) - read_f32(target + 0xB0) <= read_f32(W98_DAT_80B2AC94)
        {
            switch_state(this, W98_STATE_80B6ECD8);
            return;
        }
    }

    let ground = call4_f64x2(
        W98_FN_80075270,
        read_f32(this + 0xAC) as f64,
        (read_f32(this + 0xB0) - read_f32(W98_DAT_80B2AC98)) as f64,
        platform::read_u8(this + 0x38F) as u32,
        0,
    );
    if ground == 0 {
        let bound = read_f32(W98_DAT_80B2AC98)
            + (read_f32(W98_DAT_80429E00 + 0x3C) - read_f32(W98_DAT_80429E00 + 0x44));
        if read_f32(this + 0xB0) <= bound {
            switch_state(this, W98_STATE_80B6ECD8);
        }
    } else {
        switch_state(this, W98_STATE_80B6ECD8);
    }
}

/// Entry of the fly state: binds `fly`/`eye_fly`, classifies the side and seeds
/// the motion words.
///
/// The fly holder takes the `fly` clip and the eye holder `eye_fly`. The side
/// byte from [`fn_80a0b770`] then selects the `+0xF4` word (`1.0`/`-1.0`), the
/// heading `+0x102` (`0x1560`/`-0x1560`), and the actor receives `+0x100 =
