/// Allocates `0x600` bytes and builds five holder sub-objects.
///
/// # Safety
/// The heap and the base constructor `0x80094E80` must be usable.
///
/// # Confidence
/// high - the size, vtable and every holder offset are literal; the holder
/// roles are inherited from [`fn_80a19850`] and [`fn_80a1b980`].
pub unsafe fn fn_80a1b560() -> usize {
    let base = call1(FN_801628C0, 0x600) as usize;
    if base != 0 {
        call0(FN_80094E80);
        platform::write_u32(base + 0x60, W100_VT_80B37FC8);
        call1(FN_80069020, (base + 0x524) as u32);
        platform::write_u32(base + 0x540, 0);
        call1(FN_80169CD0, (base + 0x544) as u32);
        call1(FN_80168D10, (base + 0x584) as u32);
        platform::write_u32(base + 0x584, W100_VT_80B330E0);
        platform::write_u32(base + 0x5BC, W100_WORD_803295D8);
        platform::write_u32(base + 0x5C0, 0);
        platform::write_u32(base + 0x5C4, 0);
        call1(FN_8016A5E0, (base + 0x5C8) as u32);
        platform::write_u32(base + 0x5BC, W100_WORD_80329548);
        platform::write_u32(base + 0x5E4, 0);
    }
    base
}

/// Seeds the `+0x584` animation frame from the global frame counter.
///
/// `0x802DCC4C` converts the period at `+0x5AC` to an unsigned integer.
/// `0x8042A200` (the game frame counter) is reduced modulo that period and
/// converted with the `2^52` bias idiom before being written through
/// `0x80168FE0`.
///
/// # Original
/// - Ghidra: `FUN_80a1b910` at `0x80A1B910` (104 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a1b910_FUN_80a1b910.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor`: actor whose animation holder is at `+0x584` and whose period is
///   the `f32` at `+0x5AC`.
///
/// # Side effects
/// One animation-frame write on the holder at `+0x584`.
///
/// # Safety
/// The holder must be valid; the period should be non-zero.
///
/// # Confidence
/// medium - the arithmetic and the call are explicit; the two integer helpers
/// are named only by address, exactly as in [`fn_80a5c210`].
pub unsafe fn fn_80a1b910(actor: usize) {
    let period = call1_f64_ret_u32(FN_802DCC4C, read_f32(actor + 0x5AC) as f64);
    // unknown: the original divides without a zero guard; a zero period would
    // fault, so the model keeps the frame at zero instead.
    let frame = if period == 0 {
        0
    } else {
        platform::read_u32(DAT_8042A200) % period
    };
    let biased = f64::from_bits((0x4330_0000u64 << 32) | frame as u64);
    let value = (biased - read_f64(W100_DAT_80B2B598)) as f32;
    call2_f64(FN_80168FE0, value as f64, (actor + 0x584) as u32);
}

/// Binds the `pakkun_black` model and its `attack` clip to the `0x600` actor.
///
/// The `+0x524` loader is reset with `0x800690C0` (heap word `0x80377C48`,
/// size `0x20`), `g3d/pakkun_black.brres` is opened through `0x800DF180` and
/// stored at `+0x540`. The `pakkun_black` node is looked up with `0x80239E30`
/// and bound to `+0x544` with the holder id from the `0x80B2B5A0` table
/// (`0x20` or `0x23`, selected by `+0x5F4`). The `attack` clip is then bound to
/// `+0x584`, blended at `1.0`, and, for variant `1`, a second animation object
/// is built at `+0x5BC` with the `0x80166830`/`0x80166BD0` pair.
///
/// # Original
/// - Ghidra: `FUN_80a1b980` at `0x80A1B980` (432 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a1b980_FUN_80a1b980.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor`: `0x600`-byte actor with the holder layers built.
///
/// # Side effects
/// Allocates one model and two animation nodes; possibly calls the `+0x544`
/// vtable slot `+0x18`.
///
/// # Safety
/// The loader and holders must be constructed; the archive name must resolve.
///
/// # Confidence
/// high - both asset strings, the holder table, the variant guard and every
/// argument are explicit.
pub unsafe fn fn_80a1b980(actor: usize) {
    call5(
        FN_800690C0,
        (actor + 0x524) as u32,
        0xFFFF_FFFF,
        platform::read_u32(DAT_80377C48),
        0,
        0x20,
    );

    let resource = call3(
        FN_800DF180,
        platform::read_u32(DAT_8042A038) + 4,
        W100_STR_PAKKUN_BLACK as u32,
        W100_STR_G3D_PAKKUN_BLACK as u32,
    );
    platform::write_u32(actor + 0x540, resource);

    let animation = call2(
        FN_80239E30,
        (actor + 0x540) as u32,
        W100_STR_PAKKUN_BLACK as u32,
    );
    let variant = platform::read_u32(actor + 0x5F4) as usize;
    let holder_id = platform::read_u32(W100_TABLE_80B2B5A0 + variant * 4);
    let holder = [animation];
    call6(
        FN_80169D90,
        (actor + 0x544) as u32,
        holder.as_ptr() as u32,
        (actor + 0x524) as u32,
        holder_id,
        1,
        0,
    );
    call1(FN_80064BD0, (actor + 0x544) as u32);

    let mut clip = call2(FN_8023A0B0,
        (actor + 0x540) as u32,
        W100_STR_ATTACK as u32,
    );
    // observed: Ghidra lays the clip word below the animation word
    // (`local_2c`/`local_30`), but 0x801650D0 receives the animation first.
    let pair = [animation, clip];
    call5(
        FN_801650D0,
        (actor + 0x584) as u32,
        pair.as_ptr() as u32,
        (pair.as_ptr() as usize + 4) as u32,
        (actor + 0x524) as u32,
        0,
    );

    let clip_slot = [clip];
    call4(
        FN_801651F0,
        (actor + 0x584) as u32,
        (actor + 0x544) as u32,
        clip_slot.as_ptr() as u32,
        0,
    );
    call3_f64(
        FN_80169F80,
        read_f32(W100_DAT_80B2B590) as f64,
        (actor + 0x544) as u32,
        (actor + 0x584) as u32,
    );

    if platform::read_i32(actor + 0x5F4) == 1 {
        let second = call2(
            FN_8023A200,
            (actor + 0x540) as u32,
            W100_STR_PAKKUN_BLACK as u32,
        );
        let first_pair = [animation];
        let second_pair = [second];
        call6(
            FN_80166830,
            (actor + 0x5BC) as u32,
            first_pair.as_ptr() as u32,
            second_pair.as_ptr() as u32,
            (actor + 0x524) as u32,
            0,
            1,
        );

        let second_slot = [second];
        call5(
            FN_80166BD0,
            (actor + 0x5BC) as u32,
            (actor + 0x544) as u32,
            second_slot.as_ptr() as u32,
            0,
            1,
        );

        let vtable = platform::read_u32(actor + 0x544) as usize;
        let update = platform::read_u32(vtable + 0x18) as usize;
        call2(update, (actor + 0x544) as u32, (actor + 0x5BC) as u32);

        call3_f64(
            FN_80166EF0,
            read_f32(W100_DAT_80B2B590) as f64,
            (actor + 0x5BC) as u32,
            0,
        );
        call3_f64(
            FN_80166F10,
            read_f32(W100_DAT_80B2B58C) as f64,
            (actor + 0x5BC) as u32,
            0,
        );
    }

    call1(FN_800690E0, (actor + 0x524) as u32);
}

/// Emits the stage probe at the actor's `+0x5E8`/`+0x5EC` point.
///
/// `0x80077860` receives the scene object, the quantised `(x - 8.0)` and
/// `-(16.0 + z)` values and the selector `0x94`. The same helper shape is used
/// by the wave-87 effect emitters in this file.
///
/// # Original
/// - Ghidra: `FUN_80a1bb30` at `0x80A1BB30` (116 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a1bb30_FUN_80a1bb30.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor`: `0x600`-byte actor; probe point at `+0x5E8`/`+0x5EC`.
///
/// # Side effects
/// One five-argument scene call.
///
/// # Safety
/// The scene word at `0x80429DD0` must point at a live scene.
///
/// # Confidence
/// medium - the two constants, the mask and the call are literal; the effect
/// meaning of selector `0x94` is not established.
pub unsafe fn fn_80a1bb30(actor: usize) {
    let x = read_f32(actor + 0x5E8) - read_f32(W100_DAT_80B2B5AC);
    let z = read_f32(W100_DAT_80B2B5A8) + read_f32(actor + 0x5EC);
    call5(
        FN_80077860,
        platform::read_u32(DAT_80429DD0),
        ((x as i32) as u32) & 0xFFFF,
        ((-z) as i32 as u32) & 0xFFFF,
        0,
        0x94,
    );
}

/// Per-frame step of the `0x600`-byte actor.
///
/// Walks the player list (`0x801625B0`/`0x801625D0`) and classifies the last
/// node's `+0x554` word as `2` (non-zero) or `1` (zero); an empty list leaves
/// `0`. Classification `2` re-seeds the three `+0xDC..+0xE4` words with `1.0`
/// and, for variant `1`, stops the `+0x5BC` animation. Classification `0`
/// runs the scene cell submit `0x800777B0`, the probe [`fn_80a1bb30`], the
/// frame seed [`fn_80a1b910`] and then switches to the `Move` descriptor
/// `0x80B6F658` through the class vtable slot `+0xD4`.
///
/// # Original
/// - Ghidra: `FUN_80a1bbd0` at `0x80A1BBD0` (272 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a1bbd0_FUN_80a1bbd0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor`: `0x600`-byte actor; `+0x5F4` selects the variant, `+0x5E8`/
///   `+0x5EC` hold the probe point, `+0x38F` the side byte.
///
/// # Side effects
/// Three word writes, a player-list walk, and up to four calls.
///
/// # Safety
/// The player list must be well formed and the class vtable readable.
///
/// # Confidence
/// medium - every operand is literal; the export assigns the classification on
/// every node (so only the last node's word survives), and that shape is kept
/// rather than "fixed".
pub unsafe fn fn_80a1bbd0(actor: usize) {
    let mut classification = 0u32;
    let mut node = call0_ret_u32(FN_801625B0) as usize;
    while node != 0 {
        let flag = platform::read_u32(node + 0x554);
        let sign = ((flag.wrapping_neg() | flag) as i32) >> 31;
        classification = (1 - sign) as u32;
        node = call1(W71_FN_801625D0, node as u32) as usize;
    }

    if classification == 2 {
        let one = read_f32(W100_DAT_80B2B590).to_bits();
        platform::write_u32(actor + 0xDC, one);
        platform::write_u32(actor + 0xE0, one);
        platform::write_u32(actor + 0xE4, one);
        if platform::read_i32(actor + 0x5F4) == 1 {
            call3_f64(
                FN_80166EF0,
                read_f32(W100_DAT_80B2B58C) as f64,
                (actor + 0x5BC) as u32,
                0,
            );
        }
    }

    if classification == 0 {
        call4(
            W76_FN_800777B0,
            platform::read_u32(DAT_80429DD0),
            (read_f32(actor + 0x5E8) as i32 as u32) & 0xFFFF,
            ((-read_f32(actor + 0x5EC)) as i32 as u32) & 0xFFFF,
            platform::read_u8(actor + 0x38F) as u32,
        );
        fn_80a1bb30(actor);
        fn_80a1b910(actor);

        let vtable = platform::read_u32(actor + 0x60) as usize;
        let switch = platform::read_u32(vtable + 0xD4) as usize;
        // inferred: the class vtable slot +0xD4 selects the state descriptor.
        call2(switch, actor as u32, W100_DAT_80B6F658 as u32);
    }
}

/// Destroys one `0x600`-byte actor.
///
/// Tears down the animation object at `+0x5BC`, the animation holder at
/// `+0x584`, the model holder at `+0x544`, the loader at `+0x524` and the base
/// object; when `free` is positive it releases the allocation. Returns the
/// actor pointer.
///
/// # Original
/// - Ghidra: `FUN_80a1bd10` at `0x80A1BD10` (144 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a1bd10_FUN_80a1bd10.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor`: actor to destroy; zero is accepted and returned unchanged.
/// - `free`: when greater than zero, the allocation is released.
///
/// # Returns
/// `actor`, unchanged.
///
/// # Side effects
/// Destroys four sub-objects and possibly frees memory.
///
/// # Safety
/// `actor` must be a constructed actor or zero.
///
/// # Confidence
/// high - the teardown chain is explicit, matching [`fn_80a609a0`].
pub unsafe fn fn_80a1bd10(actor: usize, free: i32) -> usize {
    if actor != 0 {
        call2(FN_80166A70, (actor + 0x5BC) as u32, 0xFFFF_FFFF);
        // observed: the original re-tests `actor + 0x584`; it cannot be null
        // here, so the guard is dropped.
        call2(FN_80168D80, (actor + 0x584) as u32, 0);
        call2(FN_80169D20, (actor + 0x544) as u32, 0xFFFF_FFFF);
        call2(FN_80069060, (actor + 0x524) as u32, 0xFFFF_FFFF);
        call2(FN_80095130, actor as u32, 0);

        if free > 0 {
            call1(FN_80162920, actor as u32);
        }
    }
    actor
}

