/// Calls a function with five `f64` arguments followed by five integers.
///
/// The Ghidra output prints every floating-point parameter as `double`; this
/// adapter keeps them in the PowerPC floating-point register class, which
/// [`platform::call10`] cannot express.
#[inline]
unsafe fn w101_call10_f64x5(
    addr: usize,
    first: f64,
    second: f64,
    third: f64,
    fourth: f64,
    fifth: f64,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
) -> u32 {
    let func = crate::platform::guest_fn!(addr, fn(f64, f64, f64, f64, f64, u32, u32, u32, u32, u32) -> u32);
    func(first, second, third, fourth, fifth, a, b, c, d, e)
}

