    let offset_y = read_f32(actor + 0xD4);
    let offset_z = read_f32(actor + 0xD8);
    let target_x = read_f32(contact + 0xAC) + offset_x;
    let target_y = read_f32(contact + 0xB0) + offset_y;
    let target_z = read_f32(contact + 0xB4) + offset_z;

