/// Probes the ground `16` units to either side of the actor and stores the
/// result in the `+0x164` position/width block.
///
/// The two probe endpoints share the y and z of
/// `0x8006CED0(this)` and differ only in x: the yaw's sign selects the
/// `-8`/`+8` table word and the `0x8042C1A0` sign byte widens the far endpoint
/// by another `Ã‚±16`. On a hit the block becomes
/// `(midpoint - +0xAC, 8, 0, |half width|)`; the `+0x610..+0x61C` copy that
/// precedes the probe is the actor's previous block.
///
/// # Original
/// - Ghidra: `FUN_80a26b30` at `0x80A26B30` (356 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a26b30_FUN_80a26b30.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `this` - `daEnBomhei_c` instance.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x164..+0x170`.
///
/// # Safety
/// The probe callback and the angle tables must be valid.
///
/// # Confidence
/// medium - the endpoint construction and the four stores are literal; the
/// `0x80075FD0` output is read as a single x coordinate, which is the only
/// interpretation consistent with the midpoint arithmetic.
pub unsafe fn fn_80a26b30(this: usize) {
    let sign = (platform::read_u16(this + 0x102) as i16 >> 15) as i32;

    let mut base = [0f32; 3];
    call2(W105_FN_8006CED0, base.as_mut_ptr() as u32, this as u32);
    let mut middle = [0f32; 3];
    call2(W105_FN_8006CED0, middle.as_mut_ptr() as u32, this as u32);
    let mut last = [0f32; 3];
    call2(W105_FN_8006CED0, last.as_mut_ptr() as u32, this as u32);

    // observed: `iVar3 * -4` selects offset 0 for a non-negative yaw and 4 for
    // a negative one, i.e. the -8/+8 pair at 0x80B2B958.

    let lane = if sign == 0 {
        read_f32(W105_TBL_80B2B958)
    } else {
        read_f32(W105_TBL_80B2B958 + 4)
    };
    let step_byte = if sign == 0 {
        platform::read_u8(W105_TBL_8042C1A0) as i8
    } else {
        platform::read_u8(W105_TBL_8042C1A0 + 1) as i8
    };
    let step = step_byte as f32;

    let near = [base[0] + lane, middle[1], last[2]];
    let far = [base[0] + lane + 16.0 * step, middle[1], last[2]];

    platform::write_u32(this + 0x164, platform::read_u32(this + 0x610));
    platform::write_u32(this + 0x168, platform::read_u32(this + 0x614));
    platform::write_u32(this + 0x16C, platform::read_u32(this + 0x618));
    platform::write_u32(this + 0x170, platform::read_u32(this + 0x61C));

    let mut fraction = 0f32;
    let hit = call6(
        W105_FN_80075FD0,
        near.as_ptr() as u32,
        far.as_ptr() as u32,
        (&mut fraction as *mut f32) as u32,
        platform::read_u8(this + 0x38F) as u32,
        1,
        0,
    );
    if hit != 0 {
        platform::write_u32(this + 0x168, 0x4100_0000); // f32 8.0
        platform::write_u32(this + 0x170, 0x4100_0000); // f32 8.0
        write_f32(
            this + 0x164,
            0.5 * (near[0] + fraction) - read_f32(this + 0xAC),
        );
        write_f32(this + 0x16C, (0.5 * (near[0] - fraction)).abs());
    }
}

