/// Reads the character-index object behind a player: calls the `+0x6C` virtual
/// of the player's `+0x060` vtable, which returns a pointer to one byte.
///
/// # Safety
/// `player` must be a live player object with a valid `+0x060` vtable.
#[inline]
unsafe fn w110_player_index(player: usize) -> usize {
    let vtable = platform::read_u32(player + 0x60) as usize;
    let method = platform::read_u32(vtable + 0x6C) as usize;
    call1(method, player as u32) as usize
}

/// Resolves the name object of a target: calls the `+0x28` virtual of the
/// target's `+0x394` holder.
///
/// # Safety
/// `target` must be live and `+0x394` must hold a valid object.
#[inline]
unsafe fn w110_name_object(target: usize) -> usize {
    let holder = target + 0x394;
    let vtable = platform::read_u32(holder) as usize;
    let method = platform::read_u32(vtable + 0x28) as usize;
    call1(method, holder as u32) as usize
}

/// Returns whether a name object compares equal to the string at `text`.
///
/// The `+0x14` virtual returns 0 on a match and the full comparison word
/// otherwise, which is why every call site tests `== 0` (or `!= 0`).
///
/// # Safety
/// `object` must be a live name object and `text` a valid C string.
#[inline]
unsafe fn w110_name_is(object: usize, text: usize) -> bool {
    let vtable = platform::read_u32(object) as usize;
    let method = platform::read_u32(vtable + 0x14) as usize;
    call2(method, object as u32, text as u32) == 0
}

