///
/// # Confidence
/// high - the archive, model, node list, clip binder and every field offset are
/// literal.
pub unsafe fn fn_80b22e00(actor: usize) {
    call5(
        FN_800690C0,
        (actor + 0x524) as u32,
        0xFFFF_FFFF,
        platform::read_u32(0x8037_7C48),
        0,
        0x20,
    );

    let archive = call3(
        FN_800DF180,
        platform::read_u32(0x8042_A038) + 4,
        W110_PAKKUN_MODEL as u32,
        W110_PAKKUN_BRRES as u32,
    );
    platform::write_u32(actor + 0x540, archive);

    let mut node = [0u32; 8];
    node[0] = call2(FN_80239E30, (actor + 0x540) as u32, W110_PAKKUN_MODEL as u32);

    call6(
        FN_80169D90,
        (actor + 0x544) as u32,
        node.as_mut_ptr() as u32,
        (actor + 0x524) as u32,
        0x20,
        1,
        0,
    );
    call1(FN_80064BD0, (actor + 0x544) as u32);

    let motion = call2(FN_8023A0B0, (actor + 0x540) as u32, W110_PAKKUN_CLIP as u32);
    // observed: the export keeps the `0x80239E30` result in `local_24` and the
    // `0x8023A0B0` result in `local_28`, then passes the two addresses in that
    // order.
    let node_value = node[0];
    call5(
        FN_801650D0,
        (actor + 0x584) as u32,
        (&node_value as *const u32) as u32,
        (&motion as *const u32) as u32,
        (actor + 0x524) as u32,
        0,
    );
    call1(FN_800690E0, (actor + 0x524) as u32);
}

/// Spawns the `0x14D` effect above a `Wm_en_pakkun` actor and links it back.
///
/// The effect is created at the actor's x/z and `y + 48.0`, then the actor's
/// first word is stored into the effect at `+0x570`.
///
/// # Original
/// - Ghidra: `FUN_80b23540` at `0x80B23540` (132 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b23540_FUN_80b23540.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - the `Wm_en_pakkun` actor.
///
/// # Returns
/// The effect's first word (`*puVar1`), or 0 when creation failed.
///
/// # Side effects
/// Creates one effect actor and writes its `+0x570`.
///
/// # Safety
/// The actor must be live and the effect manager ready.
///
/// # Confidence
/// high - the position copy, `48.0` lift and the two stores are literal.
pub unsafe fn fn_80b23540(actor: usize) -> u32 {
    let mut position = [
        platform::read_u32(actor + 0xAC),
        platform::read_u32(actor + 0xB0),
        platform::read_u32(actor + 0xB4),
    ];
    position[1] = (read_f32(W110_HEIGHT_OFFSET) + read_f32(actor + 0xB0)).to_bits();

    let effect = call6(0x8006_4680, 0x14D, actor as u32, 0, position.as_ptr() as u32, 0, 0);
    if effect == 0 {
        return 0;
    }

    let effect = effect as usize;
    platform::write_u32(effect + 0x570, platform::read_u32(actor));
    platform::read_u32(effect)
}

/// Places the `Wm_en_pakkun` `foo` effect at the actor's position.
///
/// The effect height is `1.0` unless a target is supplied, in which case it is
/// `0.2 + 0.8 * (target.y - (actor.y + 48.0)) / 96.0`. The effect sub-object at
/// `+0x600` is then given the name `Wm_en_pakkun_foo` and the `+0x5F4` target,
/// positioned with the three-float vector, and refreshed.
///
/// # Original
/// - Ghidra: `FUN_80b23650` at `0x80B23650` (200 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b23650_FUN_80b23650.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - the `Wm_en_pakkun` actor.
/// - `target` - the followed target, or 0 for the default height.
///
/// # Side effects
/// Calls the `+0xA0` and `+0x7C` virtuals of the effect sub-object and the
/// `0x8016CFD0` refresh.
///
/// # Safety
/// `actor` must be live; `target` must be null or a live actor.
///
/// # Confidence
/// high - the blend, the name argument and the three virtual slots are
/// literal.
pub unsafe fn fn_80b23650(actor: usize, target: usize) {
    let mut height = [read_f32(W110_ONE); 3];

    if target != 0 {
        height[1] = read_f32(W110_HEIGHT_LOW)
            + (read_f32(W110_HEIGHT_SCALE)
                * (read_f32(target + 0xB0)
                    - (read_f32(W110_HEIGHT_OFFSET) + read_f32(actor + 0xB0))))
                / read_f32(W110_HEIGHT_SPAN);
    }

    let sub = actor + 0x600;
    let vtable = platform::read_u32(sub) as usize;
    let raise = platform::read_u32(vtable + 0xA0) as usize;
    call6(
        raise,
        sub as u32,
        W110_PAKKUN_FOO as u32,
        0,
        (actor + 0x5F4) as u32,
        0,
        0,
    );

    let vtable = platform::read_u32(sub) as usize;
    let place = platform::read_u32(vtable + 0x7C) as usize;
    call3(place, sub as u32, height.as_ptr() as u32, 0);

    call1(W110_FN_8016CFD0, sub as u32);
}

/// Tests whether the `Wm_en_pakkun` target is in a state that allows contact.
///
/// The four runtime name objects at `0x80357BF4`, `0x8082AAF0`, `0x8082AAB0`
/// and `0x80358004` form two nested tests; when the last one matches, the
/// function returns 0 (no contact), otherwise 1.
///
/// # Original
/// - Ghidra: `FUN_80b23720` at `0x80B23720` (364 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b23720_FUN_80b23720.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - the `Wm_en_pakkun` actor; `+0x5F0` holds the target handle.
///
/// # Returns
/// 0 when the target matches the final name object, 1 otherwise (and 1 when
/// the handle does not resolve).
///
/// # Side effects
/// Resolves the handle through `0x80162D00` and calls the name virtuals of the
/// target's `+0x394` object.
///
/// # Safety
/// The handle must be resolvable and the target's `+0x394` object valid.
///
/// # Confidence
/// medium - the branch structure is literal, but the four compared objects are
/// unnamed `main.dol` BSS values, so their roles are unknown.
pub unsafe fn fn_80b23720(actor: usize) -> u32 {
    let target = call1(FN_80162D00, platform::read_u32(actor + 0x5F0)) as usize;
    if target == 0 {
        return 1;
    }

    // observed: the first call in the export loses its argument; the three
    // sibling calls pass the `+0x394` holder, so the same receiver is used.
    let mut first = true;
    let mut second = true;

    if w110_name_is(w110_name_object(target), 0x8035_7BF4) {
        if w110_name_is(w110_name_object(target), 0x8082_AAF0) {
            first = false;
        }
    }
    if !first {
        if w110_name_is(w110_name_object(target), 0x8082_AAB0) {
            second = false;
        }
    }
    if second {
        return 1;
    }

    if w110_name_is(w110_name_object(target), 0x8035_8004) {
        0
    } else {
        1
    }
}

/// `Wm_en_pakkun` frame handler: wait for the target above the actor, then
/// time out into state `0x80B79678`.
///
/// The contact test runs once, while `+0x5EC` is clear and the target exists:
/// the target must be at or above `actor.y + 88.0` (`40.0 + 48.0`), and the
/// `0x801690E0` query on the animation holder must succeed. The common tail
/// then advances the animation, the sway and the effect, decrements `+0x5C4`
/// and switches state when it reaches zero.
///
/// # Original
/// - Ghidra: `FUN_80b23960` at `0x80B23960` (304 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b23960_FUN_80b23960.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - the `Wm_en_pakkun` actor.
///
/// # Side effects
/// Writes `+0x5EC`, `+0x5C4`; invokes the `+0x544` and `+0x394` frame slots;
/// may call [`fn_80b23610`] and switch state.
///
/// # Safety
/// The actor, its target handle and both holders must be live.
///
/// # Confidence
/// medium - the guard, the height test and the countdown are literal; the
/// state record at `0x80B79678` and the two untranslated helpers are named by
/// address only.
pub unsafe fn fn_80b23960(actor: usize) {
    let target = call1(FN_80162D00, platform::read_u32(actor + 0x5F0)) as usize;

    if platform::read_u32(actor + 0x5EC) == 0 && target != 0 {
        if read_f32(W110_NEAR_BAND) + read_f32(W110_HEIGHT_OFFSET) + read_f32(actor + 0xB0)
            <= read_f32(target + 0xB0)
        {
            if call2_f64(FN_801690E0, 0.0, (actor + 0x584) as u32) != 0 {
                call3_f64(
                    W110_FN_80B23890,
                    W110_STATE_HOLD as f32 as f64,
                    actor as u32,
                    1,
                );
                platform::write_u32(actor + 0x5EC, 1);
            }
        }
    }

    invoke_slot(actor + 0x544, 0x1C);
    call1(FN_8006CD90, actor as u32);
    call1(FN_800955F0, actor as u32);
    call1(W110_FN_80B23480, actor as u32);
    fn_80b23650(actor, target);

    let left = platform::read_i32(actor + 0x5C4) - 1;
    platform::write_i32(actor + 0x5C4, left);
    if left < 1 {
        fn_80b23610(actor);
        w110_switch_state(actor, W110_PAKKUN_STATE_B);
        invoke_slot(actor + 0x394, 0x1C);
    }
}

