/// Switches an actor through the `+0xD4` slot of its class vtable.
///
/// # Safety
/// `actor` must be live and `+0x060` must hold a valid class vtable.
#[inline]
unsafe fn w111_switch_state(actor: usize, state: usize) {
    let vtable = platform::read_u32(actor + 0x60) as usize;
    let switch = platform::read_u32(vtable + 0xD4) as usize;
    call2(switch, actor as u32, state as u32);
}

/// Tests the state record attached to the actor's `+0x394` sub-object.
///
/// The export repeats the same two virtual calls in many of these actors: slot
/// `+0x28` of the `+0x394` object returns a sub-object, and slot `+0x14` of that
/// sub-object compares it against one state word. A non-zero result means the
/// comparison matched.
///
/// # Safety
/// `owner + 0x394` must hold a live object with both virtual slots.
unsafe fn w111_has_state(owner: usize, state: usize) -> bool {
    let sub_vtable = platform::read_u32(owner + 0x394) as usize;
    let get_sub = platform::read_u32(sub_vtable + 0x28) as usize;
    let sub = call1(get_sub, (owner + 0x394) as u32) as usize;
    let test_vtable = platform::read_u32(sub) as usize;
    let test = platform::read_u32(test_vtable + 0x14) as usize;
    call2(test, sub as u32, state as u32) != 0
}

/// Rebuilds both animation holders of the parachute actor.
///
/// The body first runs the shared player-anchored probe [`fn_80a26770`], then -
/// only while `+0x7DC` is set, i.e. while the parachute is deployed - asks
/// [`fn_80adc570`] for the holder position, lifts it by `+0x814`, builds a
/// matrix at `0x801C0BD0`, writes the three angles `+0x7EA`/`+0x7E8`/`+0x7E6`
/// into it and commits it to the `+0x764` holder together with the `+0x818`
/// scale vector.
///
/// # Original
/// - Ghidra: `FUN_80adc440` at `0x80ADC440` (192 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80adc440_FUN_80adc440.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the `0x840`-byte parachute actor.
///
/// # Side effects
/// Writes the `+0x764` holder matrix, scale and commit flag when deployed.
///
/// # Safety
/// The holder at `+0x764` and the scratch matrices must be addressable.
///
/// # Confidence
/// high - the latch, the three angle reads and all six holder calls are literal;
/// the only unnamed part is the callee [`fn_80a26770`], which is translated in
/// this module.
pub unsafe fn fn_80adc440(this: usize) {
    fn_80a26770(this);
    if platform::read_u32(this + 0x7DC) == 0 {
        return;
    }

    let mut position = [0f32; 3];
    fn_80adc570(position.as_mut_ptr() as usize, this);

    let mut matrix = [0u8; 60];
    call4_f64x3(
        FN_801C0BD0,
        f64::from(position[0]),
        f64::from(position[1] - read_f32(this + 0x814)),
        f64::from(position[2]),
        matrix.as_mut_ptr() as u32,
    );

    let roll = platform::read_u16(this + 0x7EA);
    call2(
        FN_8016EEF0,
        matrix.as_mut_ptr() as u32,
        (&roll as *const u16) as u32,
    );
    let pitch = platform::read_u16(this + 0x7E8);
    call2(
        FN_8016EDD0,
        matrix.as_mut_ptr() as u32,
        (&pitch as *const u16) as u32,
    );
    let yaw = platform::read_u16(this + 0x7E6);
    call2(
        FN_8016ECB0,
        matrix.as_mut_ptr() as u32,
        (&yaw as *const u16) as u32,
    );

    call2(
        FN_8016A170,
        (this + 0x764) as u32,
        matrix.as_mut_ptr() as u32,
    );
    call2(FN_8016A150, (this + 0x764) as u32, (this + 0x818) as u32);
    call2(FN_8016A1A0, (this + 0x764) as u32, 0);
}

/// Reads the `root_parachute` node into a caller buffer.
///
/// `0x80168400` returns the model word attached to the `+0x548` record; the
/// model is then searched for the joint name and the node's `+0x0C` word (its
/// index) is passed to `0x80168180`, which copies that node's matrix into
/// `out`.
