    call1(
        platform::read_u32(model_vtable + 0x1C) as usize,
        (this + 0x544) as u32,
    );
    let wing_vtable = platform::read_u32(this + 0x860) as usize;
    call1(
        platform::read_u32(wing_vtable + 0x1C) as usize,
        (this + 0x860) as u32,
    );
    let clip_vtable = platform::read_u32(this + 0x5C0) as usize;
    call1(
        platform::read_u32(clip_vtable + 0x14) as usize,
        (this + 0x5C0) as u32,
    );

    call1(FN_8006CDE0, this as u32);
    call1(FN_800955F0, this as u32);

    if platform::read_u16(this + 0x8D8) != 0 {
        platform::write_u16(this + 0x8D8, platform::read_u16(this + 0x8D8) - 1);
    }

