/// `+0x578` sub-object release.
const EN112_FN_800DAED0: usize = 0x800D_AED0;
/// Effect spawn: `(x, y, manager, kind)`.
const EN112_FN_80078410: usize = 0x8007_8410;
/// Stage effect-manager word handed to `0x80078410`.
const EN112_DAT_80429DD0: usize = 0x8042_9DD0;
