///
/// # Safety
/// `this` must be a live object or null.
///
/// # Confidence
/// high - byte-identical to [`fn_80a00200`].
pub unsafe fn fn_80a00240(this: usize, mode: i32) -> usize {
    if this != 0 && mode > 0 {
        call1(FN_802B9280, this as u32);
    }
    this
}

