/// Adopts the player slot of the first live rider in the `+0x588` list.
///
/// A rider is live while its `+0x38C` byte is `1`. For the first such rider the
/// step copies the low byte of the rider's `+0x1090` word into `+0x567` and the
/// byte returned by the rider's `vtable +0x6C` getter into `+0x38D` (the
/// actor's signed player index).
///
/// # Original
/// - Ghidra: `FUN_80a08dc0` at `0x80A08DC0` (124 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a08dc0_FUN_80a08dc0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - rider actor; `+0x588` is the head of the rider list.
///
/// # Returns
/// `1` when a live rider was found, `0` otherwise.
///
/// # Side effects
/// Writes `+0x567` and `+0x38D`; calls the rider getter.
///
/// # Safety
/// Every list node must belong to this actor and its payload must be live.
///
/// # Confidence
/// medium - the two field roles are inferred from the three steps that read
/// them, and no name in the export identifies the list.
pub unsafe fn fn_80a08dc0(actor: usize) -> u32 {
    let mut node = platform::read_u32(actor + 0x588) as usize;
    while node != 0 {
        let rider = platform::read_u32(node + 0x04) as usize;
        if platform::read_u8(rider + 0x38C) == 1 {
            platform::write_u8(
                actor + 0x567,
                platform::read_u32(rider + 0x1090) as u8,
            );
            let vtable = platform::read_u32(rider + 0x60) as usize;
            let get_player = platform::read_u32(vtable + 0x6C) as usize;
            let player = platform::read_u8(call1(get_player, rider as u32) as usize);
            platform::write_u8(actor + 0x38D, player);
            return 1;
        }
        node = platform::read_u32(node + 0x0C) as usize;
    }
    0
}

/// Builds the four-bit mask of player slots occupied by live riders.
///
/// # Original
/// - Ghidra: `FUN_80a08e40` at `0x80A08E40` (152 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a08e40_FUN_80a08e40.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - rider actor; `+0x588` is the rider list, `+0x568` the mask.
///
/// # Side effects
/// Clears `+0x568`, then sets bit `n` for every live rider whose getter returns
/// `n < 4`.
///
/// # Safety
/// Every list node and rider must be live for the duration of the walk.
///
/// # Confidence
/// high - the shift, the range test and the store are literal.
pub unsafe fn fn_80a08e40(actor: usize) {
    platform::write_u32(actor + 0x568, 0);
    let mut node = platform::read_u32(actor + 0x588) as usize;
    while node != 0 {
        let rider = platform::read_u32(node + 0x04) as usize;
        if platform::read_u8(rider + 0x38C) == 1 {
            let vtable = platform::read_u32(rider + 0x60) as usize;
            let get_player = platform::read_u32(vtable + 0x6C) as usize;
            let player = platform::read_u8(call1(get_player, rider as u32) as usize);
            if (player as u32) < 4 {
                let mask = platform::read_u32(actor + 0x568) | (1u32 << player);
                platform::write_u32(actor + 0x568, mask);
            }
        }
        node = platform::read_u32(node + 0x0C) as usize;
    }
}

/// Ride-down step: snaps the actor to the ride height or falls to it.
///
/// When no rider is live the height word `+0xB0` is copied straight from the
/// ride height `+0x550`. Otherwise a `0x80078410` effect is spawned at the
/// actor's height and the state switches to `0x80B6EA98`.
///
/// # Original
/// - Ghidra: `FUN_80a08ff0` at `0x80A08FF0` (116 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a08ff0_FUN_80a08ff0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - rider actor; `+0xAC`/`+0xB0` are its position, `+0x550` the
///   target ride height.
///
/// # Side effects
/// May write `+0xB0`, spawn a stage effect and switch the state.
///
/// # Safety
/// `actor` must be a live actor with the rider list at `+0x588`.
///
/// # Confidence
/// high - both branches and the switch are literal.
pub unsafe fn fn_80a08ff0(actor: usize) {
    if fn_80a08dc0(actor) == 0 {
        platform::write_u32(actor + 0xB0, platform::read_u32(actor + 0x550));
    } else {
        call4_f64x2(
            EN112_FN_80078410,
            read_f32(actor + 0xAC) as f64,
            read_f32(actor + 0x550) as f64,
            platform::read_u32(EN112_DAT_80429DD0),
            0x16,
        );
        switch_state(actor, EN112_STATE_80B6EA98);
    }
}

/// Entry step that arms the walk timer before handing over to a ride state.
///
/// With no live rider the `+0x560` timer is set to `0x14` and the state goes to
/// `0x80B6EA18`. With a rider, the state also goes to `0x80B6EA18` unless the
/// rider's `+0x567` type is `3`, in which case the probe is repeated and the
/// state only changes when the repeat also fails.
///
/// # Original
/// - Ghidra: `FUN_80a090a0` at `0x80A090A0` (180 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a090a0_FUN_80a090a0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - rider actor; `+0x560` is a frame timer, `+0x567` the rider type.
///
/// # Side effects
/// Writes `+0x560` and may switch the state.
///
/// # Safety
/// `actor` must be a live actor with a valid rider list.
///
/// # Confidence
/// medium - the flow is literal, the timer's unit and the type byte's meaning
/// are inferred from the neighbouring steps.
pub unsafe fn fn_80a090a0(actor: usize) {
    if fn_80a08dc0(actor) == 0 {
        platform::write_u16(actor + 0x560, 0x14);
        switch_state(actor, EN112_STATE_80B6EA18);
    } else if platform::read_u8(actor + 0x567) == 3 {
        if fn_80a08dc0(actor) == 0 {
            switch_state(actor, EN112_STATE_80B6EA18);
        }
    } else {
        switch_state(actor, EN112_STATE_80B6EA18);
    }
}

/// Fall step: applies gravity until the actor reaches the ride height.
///
/// # Original
/// - Ghidra: `FUN_80a091b0` at `0x80A091B0` (248 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a091b0_FUN_80a091b0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - rider actor; `+0xEC` is the vertical offset, `+0x550` the ride
///   height, `+0x558` the per-frame gravity step.
///
/// # Side effects
/// With no live rider: sets one of the two `0x14` timers and switches to
/// `0x80B6EAD8`. With a rider: subtracts the gravity step from `+0xEC` and, once
/// the actor is below `+0x550 - 0x80B2AB5C`, either switches to `0x80B6EAD8`
/// (type `3`) or snaps the height, writes `0x80B2AB4C` into `+0xEC` and switches
/// to `0x80B6EB18`.
///
/// # Safety
/// `actor` must be a live actor with a valid rider list.
///
/// # Confidence
/// medium - the arithmetic is literal; the timer and type roles are inferred.
pub unsafe fn fn_80a091b0(actor: usize) {
    if fn_80a08dc0(actor) == 0 {
        if platform::read_u8(actor + 0x567) == 3 {
            platform::write_u16(actor + 0x560, 0x14);
        } else {
            platform::write_u16(actor + 0x55E, 0x14);
        }
        switch_state(actor, EN112_STATE_80B6EAD8);
    } else {
        let floor = read_f32(actor + 0x550) - read_f32(EN112_DAT_80B2AB5C);
        platform::write_f32(
            actor + 0xEC,
            read_f32(actor + 0xEC) - read_f32(actor + 0x558),
        );
        if read_f32(actor + 0xB0) < floor {
            if platform::read_u8(actor + 0x567) == 3 {
                switch_state(actor, EN112_STATE_80B6EAD8);
            } else {
                platform::write_f32(actor + 0xB0, floor);
                platform::write_u32(actor + 0xEC, EN112_DAT_80B2AB4C as u32);
                switch_state(actor, EN112_STATE_80B6EB18);
            }
        }
    }
}

/// Rise step: pulls the actor up to the ride height and reports arrival.
///
/// # Original
/// - Ghidra: `FUN_80a09310` at `0x80A09310` (288 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a09310_FUN_80a09310.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - rider actor; `+0xEC` offset, `+0x550` ride height, `+0x558` the
///   per-frame rise step, `+0x567` the rider type.
///
/// # Side effects
/// Adds the rise step to `+0xEC`; when the actor passes the ride height it
/// snaps `+0xB0`, arms a `0x14` timer and switches state. A type of `0`..`2`
/// with a live rider switches to `0x80B6EA98` instead.
///
/// # Safety
/// `actor` must be a live actor with a valid rider list.
///
/// # Confidence
/// medium - the three branch tails are literal, the state roles are inferred.
pub unsafe fn fn_80a09310(actor: usize) {
    if fn_80a08dc0(actor) == 0 {
        platform::write_f32(
            actor + 0xEC,
            read_f32(actor + 0xEC) + read_f32(actor + 0x558),
        );
        if read_f32(actor + 0xB0) > read_f32(actor + 0x550) {
            platform::write_f32(actor + 0xB0, read_f32(actor + 0x550));
            if platform::read_u8(actor + 0x567) == 3 {
                platform::write_u16(actor + 0x560, 0x14);
                switch_state(actor, EN112_STATE_80B6EA58);
            } else {
                platform::write_u16(actor + 0x55E, 0x14);
                switch_state(actor, EN112_STATE_80B6EA18);
            }
        }
    } else if platform::read_u8(actor + 0x567) == 3 {
        platform::write_f32(
            actor + 0xEC,
            read_f32(actor + 0xEC) + read_f32(actor + 0x558),
        );
        if read_f32(actor + 0xB0) > read_f32(actor + 0x550) {
            platform::write_f32(actor + 0xB0, read_f32(actor + 0x550));
            switch_state(actor, EN112_STATE_80B6EA58);
        }
    } else {
        switch_state(actor, EN112_STATE_80B6EA98);
    }
}

/// Deceleration step with the rider-impact branch.
///
/// While the vertical offset `+0xEC` is above `0x80B2AB98`, the step subtracts
/// `+0x554` from it. When the actor is at least `0x80B2AB9C` above the ride
/// height, or the `+0x56C` flag is already set, the step checks the remaining
/// offset against `0x80B2AB4C` and either clears the `0x40` bit of `+0x5B4` or
/// sets it, plays an effect on the rider and switches to `0x80B6EB58`.
/// Otherwise it arms `+0x56C` and multiplies `+0xEC` by `0x80B2AB94`.
///
/// # Original
/// - Ghidra: `FUN_80a09460` at `0x80A09460` (348 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a09460_FUN_80a09460.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - rider actor; `+0x38D` is the signed player index, `+0x5B4` a
///   flag word whose bit `0x40` marks the impact.
///
/// # Side effects
/// Writes `+0xEC`, `+0x5B4`, `+0x56C`; may spawn the rider effect through the
/// rider's `vtable +0x3FC` and switch state.
///
/// # Safety
/// `actor + 0x38D` must index a live player object.
///
/// # Confidence
/// medium - the arithmetic and the flag writes are literal; the three constants
/// keep their export names because no text identifies them.
pub unsafe fn fn_80a09460(actor: usize) {
    if fn_80a08dc0(actor) == 0 {
        platform::write_u16(actor + 0x55E, 0x14);
        switch_state(actor, EN112_STATE_80B6EB98);
        return;
    }
    if read_f32(EN112_DAT_80B2AB98) <= read_f32(actor + 0xEC) {
        platform::write_f32(
            actor + 0xEC,
            read_f32(actor + 0xEC) - read_f32(actor + 0x554),
        );
    }
    let within_band = read_f32(actor + 0xB0) <= read_f32(actor + 0x550) - read_f32(EN112_DAT_80B2AB9C);
    if !within_band && platform::read_i32(actor + 0x56C) == 0 {
        platform::write_u32(actor + 0x56C, 1);
        platform::write_f32(
            actor + 0xEC,
            read_f32(actor + 0xEC) * read_f32(EN112_DAT_80B2AB94),
        );
        return;
    }
    if read_f32(actor + 0xEC) < read_f32(EN112_DAT_80B2AB4C) {
        if read_f32(actor + 0xB0) >= read_f32(actor + 0x550) - read_f32(EN112_DAT_80B2ABA0) {
            let flags = platform::read_u32(actor + 0x5B4) & !0x40;
            platform::write_u32(actor + 0x5B4, flags);
        } else {
            let flags = platform::read_u32(actor + 0x5B4) | 0x40;
            platform::write_u32(actor + 0x5B4, flags);
            let player = call1(
                FN_8005F900,
                platform::read_u8(actor + 0x38D) as i8 as u32,
            ) as usize;
            let vtable = platform::read_u32(player + 0x60) as usize;
            call6_f64x2(
                platform::read_u32(vtable + 0x3FC) as usize,
                read_f32(EN112_DAT_80B2AB48) as f64,
                read_f32(player + 0x10C) as f64,
                player as u32,
                1,
                0,
                0,
            );
            switch_state(actor, EN112_STATE_80B6EB58);
        }
    }
}

/// Bounce step: damps the offset and picks the next ride state.
///
