/// Six-button stomp counter of the `kuriboMini` actor.
///
/// The six controller predicates on `player + 0xEA4` build a bit mask (bits
/// `0x08`, `0x04`, `0x02`, `0x01`, `0x10`, `0x20`). A non-zero mask first arms
/// the `+0x608` timer with `0x80B34DCC` when `+0x600` is still clear, then
/// counts the `0x20` press into `+0x5FC` and any change of the mask into
/// `+0x604`. Both counters trip once they pass `0x80B2AD58 + 0x80B34DD4` /
/// `+0x80B34DD0`, which clears the whole block and returns `1`. When the timer
/// reaches `1` the block is cleared without a hit.
///
/// # Original
/// - Ghidra: `FUN_80a0df00` at `0x80A0DF00` (484 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a0df00_FUN_80a0df00.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - `kuriboMini` actor; `+0x5F8`/`+0x5FC`/`+0x600`/`+0x604`/`+0x608`
///   are the counter block.
/// - `player` - player object; its `+0xEA4` input block is queried.
///
/// # Returns
/// `1` when the counter trips, `0` otherwise.
///
/// # Side effects
/// Updates the five counter words and may clear them.
///
/// # Safety
/// `player + 0xEA4` must be a live input block.
///
/// # Confidence
/// medium - the six predicates and the arithmetic are literal; the individual
/// button meanings are not named by the export.
pub unsafe fn fn_80a0df00(actor: usize, player: usize) -> u32 {
    let mut timer = platform::read_i32(actor + 0x608);
    if timer != 0 {
        timer -= 1;
        platform::write_i32(actor + 0x608, timer);
    }

    let mut bits = 0u32;
    if call1(EN112_FN_8005E530, (player + 0xEA4) as u32) != 0 {
        bits = 8;
    }
    if call1(EN112_FN_8005E540, (player + 0xEA4) as u32) != 0 {
        bits |= 4;
    }
    if call1(EN112_FN_8005E550, (player + 0xEA4) as u32) != 0 {
        bits |= 2;
    }
    if call1(EN112_FN_8005E560, (player + 0xEA4) as u32) != 0 {
        bits |= 1;
    }
    if call1(EN112_FN_8005E590, (player + 0xEA4) as u32) != 0 {
        bits |= 0x10;
    }
    if call1(EN112_FN_8005E570, (player + 0xEA4) as u32) != 0 {
        bits |= 0x20;
    }

    if timer == 1 {
        platform::write_u32(actor + 0x5F8, 0);
        platform::write_u32(actor + 0x5FC, 0);
        platform::write_u32(actor + 0x604, 0);
        platform::write_u32(actor + 0x600, 0);
        platform::write_u32(actor + 0x608, 0);
        return 0;
    }
    if bits == 0 {
        return 0;
    }

    let mut fire = false;
    if platform::read_i32(actor + 0x600) == 0 {
        platform::write_i32(actor + 0x608, EN112_DAT_80B34DCC as i32);
    }
    if (bits & 0x20) != 0 {
        platform::write_u32(actor + 0x5F8, bits);
        let count = platform::read_i32(actor + 0x5FC) + 1;
        platform::write_i32(actor + 0x5FC, count);
        if ((read_f32(EN112_DAT_80B2AD58) + read_f32(EN112_DAT_80B34DD4)) as i32) <= count {
            fire = true;
        }
    }
    if (bits & platform::read_u32(actor + 0x600)) == 0 {
        platform::write_u32(actor + 0x600, bits);
        let count = platform::read_i32(actor + 0x604) + 1;
        platform::write_i32(actor + 0x604, count);
        if ((read_f32(EN112_DAT_80B2AD58) + read_f32(EN112_DAT_80B34DD0)) as i32) <= count {
            fire = true;
        }
    }
    if fire {
        platform::write_u32(actor + 0x5FC, 0);
        platform::write_u32(actor + 0x5F8, 0);
        platform::write_u32(actor + 0x604, 0);
        platform::write_u32(actor + 0x600, 0);
        platform::write_u32(actor + 0x608, 0);
        return 1;
    }
    0
}

