        let count = platform::read_i32(actor + 0x664) - 1;
        platform::write_f32(actor + 0xE8, read_f32(EN113_DAT_80B32558));
        platform::write_u32(actor + 0xEC, platform::read_u32(EN113_DAT_80B326A0));
        platform::write_i32(actor + 0x664, count);
