/// Facing step: swings the `+0x102` angle towards the side's limit.
///
/// # Original
/// - Ghidra: `FUN_80b1ef80` at `0x80B1EF80` (176 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b1ef80_FUN_80b1ef80.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor` - head actor; `+0x348` the side byte, `+0x102` the facing angle.
///
/// # Side effects
/// Advances both animation holders and clamps `+0x102` to `+0x4000` (side 0)
/// or `-0x4000` (side 1).
///
/// # Safety
/// `actor` must be live.
///
/// # Confidence
/// high - the two clamps and the increments are literal.
pub unsafe fn fn_80b1ef80(actor: usize) {
    let vtable = platform::read_u32(actor + 0x544) as usize;
    call1(
        platform::read_u32(vtable + 0x1C) as usize,
        (actor + 0x544) as u32,
    );
    let vtable = platform::read_u32(actor + 0x5C0) as usize;
    call1(
        platform::read_u32(vtable + 0x14) as usize,
        (actor + 0x5C0) as u32,
    );
    call1(EN113_FN_8006CDE0, actor as u32);
    call1(EN113_FN_8006CD40, actor as u32);

    if platform::read_u8(actor + 0x348) == 0 {
        let angle = (platform::read_u16(actor + 0x102) as i16).wrapping_add(0x400);
        platform::write_u16(actor + 0x102, angle as u16);
        if angle > 0x4000 {
            platform::write_u16(actor + 0x102, 0x4000);
        }
    } else {
        let angle = (platform::read_u16(actor + 0x102) as i16).wrapping_sub(0x400);
        platform::write_u16(actor + 0x102, angle as u16);
        if angle < -0x4000 {
            platform::write_u16(actor + 0x102, 0xC000);
        }
    }
}

