            call2(FN_801676A0, (this + 0x5F8) as u32, 0xFFFF_FFFF);
            call2(FN_80169D20, (this + 0x5B4) as u32, 0xFFFF_FFFF);
            call2(FN_801676A0, (this + 0x588) as u32, 0xFFFF_FFFF);
