    let mut sound_position = [
        (read_f32(actor + 0xAC) + read_f32(actor + 0xD0)).to_bits(),
        (read_f32(actor + 0xB0) + read_f32(actor + 0xD4)).to_bits(),
        (read_f32(actor + 0xB4) + read_f32(actor + 0xD8)).to_bits(),
    ];
