/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a9ff20_FUN_80a9ff20.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor`: `daEnKanon_c` actor.
///
/// # Returns
/// The flag byte (bit `0` contact, bit `1` animation, bit `2` overlap).
///
/// # Side effects
/// Writes `+0xEC`, or-s `+0x274` and runs the frame tail.
///
/// # Safety
/// The `+0x1EC` block and the `0x8042C1A0` table must be readable.
///
/// # Confidence
/// medium - the flag bits, the table index and the frame tail are literal; the
/// `2^52 + 2^31` magic constant at `0x80B2F338` is modelled as the signed-byte
/// conversion it performs.
pub unsafe fn fn_80a9ff20(actor: usize) -> u8 {
    call1(W118_FN_80096F60, actor as u32);
    let mut flags = if call1(W118_FN_80070CB0, (actor + 0x1EC) as u32) != 0 {
        1u8
    } else {
        0u8
    };
    if flags != 0 {
        platform::write_u32(actor + 0xEC, platform::read_u32(W118_DAT_80B2F2F4));
    }
    if call2(W118_FN_8006EF40, (actor + 0x1EC) as u32, 0) != 0 {
        flags |= 2;
    }

    let side = if read_f32(actor + 0xAC) - read_f32(actor + 0x238)
        < read_f32(W118_DAT_80B2F2F4)
    {
        1usize
    } else {
        0usize
    };

    // observed: `(double)CONCAT44(0x43300000, c ^ 0x80000000) - 0x80B2F338`
    // is the Metrowerks signed-byte-to-double idiom, i.e. the signed byte at
    // `0x8042C1A0 + side` widened to `f32`.
    let mut offset = [(platform::read_u8(DAT_8042C1A0 + side) as i8 as f32).to_bits()];
    let first = call2(
        W118_FN_80072CB0,
        (actor + 0x1EC) as u32,
        offset.as_mut_ptr() as u32,
    );
    if first != 0 {
        flags |= 4;
    }

    let other_side = side ^ 1;
    let mut offset = [(platform::read_u8(DAT_8042C1A0 + other_side) as i8 as f32).to_bits()];
    let second = call2(
        W118_FN_80072CB0,
        (actor + 0x1EC) as u32,
        offset.as_mut_ptr() as u32,
    );

    platform::write_u32(
        actor + 0x274,
        platform::read_u32(actor + 0x274) | first | second,
    );
    call3_f64(
        W118_FN_80AA0080,
        read_f32(W118_DAT_80B2F2E0) as f64,
        actor as u32,
        (actor + 0xAC) as u32,
    );
    flags
}

