        // observed 0x80AFD2A8: `r3` is still the actor when `0x80162590` runs.
        call1(W119_FN_80162590, actor as u32);
        platform::write_u8(actor + 0x348, side);
        let index = platform::read_i32(actor + 0x608) as usize;
        platform::write_u32(
            actor + 0xE8,
            platform::read_u32(W119_DAT_80B77F30 + index * 8),
        );
        platform::write_u32(
            actor + 0xEC,
            platform::read_u32(W119_DAT_80B77F34 + index * 8),
        );
        platform::write_u32(actor + 0xF0, platform::read_u32(W119_DAT_80B317A8));
        if platform::read_i32(actor + 0x604) == 0 {
            platform::write_u32(actor + 0x120, platform::read_u32(actor + 0x120) | 0x10);
        } else {
            platform::write_u32(actor + 0x120, platform::read_u32(actor + 0x120) | 0x20);
        }
        platform::write_u32(actor + 0x5D0, 0);
        switch_state(actor, W119_STATE_80B78144);
