/// Interpolates the actor position toward a sampled matrix point.
///
/// # Original
/// - Ghidra: `FUN_80afd720` at `0x80AFD720` (312 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80afd720_FUN_80afd720.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `actor`: the sanbo actor.
///
/// # Side effects
/// Decrements the two counter pairs (clamped at `0`), samples the object
/// resolved from `+0x368`, and writes the blended `+0xAC..+0xB4` triple.
///
/// # Safety
/// `actor` must be live and the handle at `+0x368` resolvable.
///
/// # Confidence
/// medium - the blend is literal; `0x80152480`/`0x8016F130` are inferred to
/// sample and extract the target point from the way they are paired.
pub unsafe fn fn_80afd720(actor: usize) {
    let handle = platform::read_u32(actor + 0x368);
    let object = call1(W119_FN_80162D00, handle) as usize;
    let mut matrix = [0u8; 0x30];
    call2(
        W119_FN_80152480,
        object as u32,
        matrix.as_mut_ptr() as u32,
    );
    let mut target = [0f32; 3];
    call2(
        W119_FN_8016F130,
        matrix.as_mut_ptr() as u32,
        target.as_mut_ptr() as u32,
    );

    let mut remaining = platform::read_i32(actor + 0x5F0) - 1;
    if remaining < 1 {
        remaining = 0;
    }
    platform::write_i32(actor + 0x5F0, remaining);
    let mut remaining_y = platform::read_i32(actor + 0x5F8) - 1;
    if remaining_y < 1 {
        remaining_y = 0;
    }
    platform::write_i32(actor + 0x5F8, remaining_y);

    let horizontal = remaining as f32 / platform::read_i32(actor + 0x5F4) as f32;
    let horizontal_rest = read_f32(W119_DAT_80B317A4) - horizontal;
    let vertical = remaining_y as f32 / platform::read_i32(actor + 0x5FC) as f32;
    let vertical_rest = read_f32(W119_DAT_80B317A4) - vertical;

    write_f32(
        actor + 0xAC,
        horizontal * read_f32(actor + 0xAC) + horizontal_rest * target[0],
    );
    write_f32(
        actor + 0xB0,
        vertical * read_f32(actor + 0xB0) + vertical_rest * target[1],
    );
    write_f32(
        actor + 0xB4,
        horizontal * read_f32(actor + 0xB4) + horizontal_rest * target[2],
    );
}

