    let drop = read_f32(actor + 0xB4) - read_f32(W121_DAT_80B2DBA8);
    let mut segment = actor + 0x544;
    let mut index = 0i32;
    while index < count {
        write_f32(segment + 0x88, read_f32(segment + 0x88) - drop);
        segment = platform::read_u32(segment + 0x238) as usize;
        index += 1;
    }
