    call4(
        FN_801651F0,
        (actor + 0x584) as u32,
        (actor + 0x544) as u32,
        animation.as_mut_ptr() as u32,
        flag,
    );
    call3_f64(
        FN_80169F80,
        blend,
        (actor + 0x544) as u32,
        (actor + 0x584) as u32,
    );
    call2_f64(
        FN_801680E0,
        read_f32(W121_DAT_80B2DC44) as f64,
        (actor + 0x584) as u32,
    );
