// ---------------------------------------------------------------------------

/// Recomputes the eight placement rows and the node-21 position.
///
/// The body:
///
/// 1. refreshes the model holder `0x80168400(actor + 0x544)`;
/// 2. for both node groups of `0x80B2E068`, reads each of the four node
///    matrices with `0x80168180` and writes its translation into the rows at
///    `+0x628` (stride `0xC`); the fourth node of each group also gets a
///    `0x801C1160` transform with the scale `{5.0, 0.0, 0.0}` into the
///    `+0x688` block (stride `0xC`);
/// 3. reads node `0x15` into `+0x61C` and stores the three deltas
///    `node - actor` at `+0xD0..+0xD8`.
///
/// # Original
/// - Ghidra: `FUN_80a7a170` at `0x80A7A170` (324 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a7a170_FUN_80a7a170.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` - actor with the model holder at `+0x544` and the position at
///   `+0xAC`.
///
/// # Side effects
/// Writes nine three-word records, one extra transform block and `+0xD0..+0xD8`.
///
/// # Safety
/// The holder and every node id must be valid for the model, and the buffers
/// at `+0x61C..+0x6A0` must be writable.
///
/// # Confidence
/// medium - the two nested loops and every offset are literal; the export
/// recovers the actor through the `0x802DCD68` prologue, so the actor is taken
/// as an argument, and the `0x801C1160` scale role is `// inferred:`.
pub unsafe fn fn_80a7a170(actor: usize) {
    call1(W121_FN_80168400, (actor + 0x544) as u32);

    let mut buffer = [0u32; 22];
    let mut row = actor + 0x628;
    let mut extra = actor + 0x688;
    let mut ids = W121_TBL_80B2E068;

    while extra < actor + 0x6A0 {
        let mut slot = 0;
        let mut destination = row;
        let mut cursor = ids;
        while slot < 4 {
            let id = platform::read_u32(cursor);
            cursor += 4;

            call3(
                FN_80168180,
                (actor + 0x544) as u32,
                id,
                buffer.as_mut_ptr() as u32,
            );
            call2(
                FN_8016F130,
                buffer.as_mut_ptr() as u32,
                destination as u32,
            );

            if slot == 3 {
                let scale = [read_f32(W121_DAT_80B2E088), 0.0f32, 0.0f32];
                call3(
                    W121_FN_801C1160,
                    buffer.as_mut_ptr() as u32,
                    scale.as_ptr() as u32,
                    extra as u32,
                );
            }

            slot += 1;
            destination += 0xC;
        }

        extra += 0xC;
        row += 0x30;
        ids += 16;
    }

    call3(
        FN_80168180,
        (actor + 0x544) as u32,
        0x15,
        buffer.as_mut_ptr() as u32,
    );
    call2(FN_8016F130, buffer.as_mut_ptr() as u32, (actor + 0x61C) as u32);

    write_f32(actor + 0xD8, read_f32(actor + 0x624) - read_f32(actor + 0xB4));
    write_f32(actor + 0xD4, read_f32(actor + 0x620) - read_f32(actor + 0xB0));
    write_f32(actor + 0xD0, read_f32(actor + 0x61C) - read_f32(actor + 0xAC));
}

