/// Three-phase throw frame handler of the `daEnIcicle_c` class.
///
/// Phase 1 runs the base updates, resets the clip rate to `0.0` once the clip
/// reaches `12.0`, and moves to phase 2 when the vertical speed `+0xEC` has
/// fallen to `1.0` or below. Phase 2 clamps `+0xEC` to `0.0` and compares the
/// clip frame with the class query `+0x2CC`; a match calls `+0x2F0` and enters
/// phase 3. Phase 3 waits for ground contact, then zeroes `+0xEC` and switches
/// to the `0x80352CB4` descriptor.
///
/// # Original
/// - Ghidra: `FUN_80a7d760` at `0x80A7D760` (400 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a7d760_FUN_80a7d760.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// * `actor` - actor with the holders at `+0x544`/`+0x584`, the phase at
///   `+0x360` and the vertical speed at `+0xEC`.
///
/// # Side effects
/// Two base updates per phase, one rate write, one state switch and up to two
/// class virtuals.
///
/// # Safety
/// The holder vtable, the class vtable and the `+0x60` vtable must be valid.
///
/// # Confidence
/// medium - every call and store is literal; the export drops the `double`
/// argument of the second `0x801680E0` call, which is forwarded from the
/// `0.0` constant used by the adjacent call and marked `// inferred:`, and the
/// `+0x2CC`/`+0x2F0` slot roles are inferred from their position.
pub unsafe fn fn_80a7d760(actor: usize) {
    let holder_vtable = platform::read_u32(actor + 0x544) as usize;
    call1(
        platform::read_u32(holder_vtable + 0x1C) as usize,
        (actor + 0x544) as u32,
    );

    let phase = platform::read_i32(actor + 0x360);
    if phase == 1 {
        call1(FN_8006CDE0, actor as u32);
        call1(FN_800955F0, actor as u32);

        let frame = call1_ret_f32(FN_80168080, (actor + 0x584) as u32);
        if read_f32(W121_DAT_80B2E1CC) <= frame {
            call2_f64(
                FN_801680E0,
                read_f32(DAT_80B2E198) as f64,
                (actor + 0x584) as u32,
            );
        }

        if read_f32(actor + 0xEC) <= read_f32(DAT_80B2E1C4) {
            // inferred: the export prints this call with one argument; the
            // adjacent rate resets pass 0x80B2E198, so it is forwarded here.
            call2_f64(
                FN_801680E0,
                read_f32(DAT_80B2E198) as f64,
                (actor + 0x584) as u32,
            );
            write_f32(actor + 0xEC, read_f32(DAT_80B2E198));
            platform::write_i32(actor + 0x360, 2);
        }
    } else if phase == 2 {
        call1(FN_8006CDE0, actor as u32);
        if read_f32(actor + 0xEC) < read_f32(DAT_80B2E198) {
            write_f32(actor + 0xEC, read_f32(DAT_80B2E198));
        }
        call1(FN_800955F0, actor as u32);

        let class_vtable = platform::read_u32(actor + 0x60) as usize;
        let length = call1_ret_f32(
            platform::read_u32(class_vtable + 0x2CC) as usize,
            actor as u32,
        );
        let frame = call1_ret_f32(FN_80168080, (actor + 0x584) as u32);
        if frame == length {
            call1(
                platform::read_u32(class_vtable + 0x2F0) as usize,
                actor as u32,
            );
            platform::write_i32(actor + 0x360, 3);
        }
    } else if phase == 3 {
        call1(FN_8006CDE0, actor as u32);
        call1(FN_800955F0, actor as u32);
        if call1(FN_80072BC0, (actor + 0x1EC) as u32) != 0 {
            write_f32(actor + 0xEC, read_f32(DAT_80B2E198));
            switch_state(actor, W121_DESC_80352CB4);
        }
    }
}

