/// Shared three-call matrix commit used by [`fn_80a2e450`].
///
/// # Safety
/// `actor` and the holder at `actor + holder` must be live.
#[inline]
unsafe fn rebuild_bubble_matrix(actor: usize, angles: &mut [u16; 3], position: &mut [f32; 3], holder: usize) {
    call3(
        W123_FN_80064AF0,
        position.as_mut_ptr() as u32,
        angles.as_mut_ptr() as u32,
        1,
    );
    let mut matrix = [0u32; 12];
    call4_f64x3(
        W123_FN_801C0BD0,
        position[0] as f64,
        position[1] as f64,
        position[2] as f64,
        matrix.as_mut_ptr() as u32,
    );
    let mut yaw = [angles[1]];
    call2(W123_FN_8016EDD0, matrix.as_mut_ptr() as u32, yaw.as_mut_ptr() as u32);
    let mut roll = [angles[0]];
    call2(W123_FN_8016ECB0, matrix.as_mut_ptr() as u32, roll.as_mut_ptr() as u32);
    let mut pitch = [angles[2]];
    call2(W123_FN_8016EEF0, matrix.as_mut_ptr() as u32, pitch.as_mut_ptr() as u32);
    call2(W123_FN_8016A170, (actor + holder) as u32, matrix.as_mut_ptr() as u32);
    call2(W123_FN_8016A150, (actor + holder) as u32, (actor + 0xDC) as u32);
    call2(W123_FN_8016A1A0, (actor + holder) as u32, 0);
}

/// Reinterprets a stored matrix word as `f32`.
#[inline]
fn float_from_bits(word: u32) -> f32 {
    f32::from_bits(word)
}

/// Rewrites one colour channel of every node of a model holder.
///
/// For each node the payload is resolved through `+0x3C`, offset by `0x20`,
/// its packed colour is read with `0x8023D300`, the high byte is replaced by
/// `patch` (`CONCAT31(colour[0..3], patch)`) and the result is written back
/// with `0x801685E0`. The same helper is called twice per frame by
/// [`fn_80a2e450`] with the two tail fade bytes.
///
/// # Original
/// - Ghidra: `FUN_80a2e710` at `0x80A2E710` (208 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a2e710_FUN_80a2e710.c`
