/// # Original
/// - Ghidra: `FUN_80aad010` at `0x80AAD010` (1140 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80aad010_FUN_80aad010.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
/// - Removed: the modelled `_savegpr_27` prologue call (`0x802DCD74`) and the
///   seven `_restgpr_27` epilogue calls (`0x802DCDC0`), one per exit. The
///   `li r3,0`/`li r3,1` before each epilogue is the return value.
///
/// # Arguments
/// - `actor`: the `daEnKild_c` actor, passed in `r3` (`lhz r0,0x500(r3)`).
///
/// # Returns
/// `1` when the step ran to the effect tail, `0` for every early exit.
///
/// # Side effects
/// Writes a `+0xB44` slot, `+0xE34`, `+0xE1C` and `+0xA0C`; allocates a shot
/// through the two truncated `0x80AAA3E0`/`0x80AAA480` spawners and requests
/// sounds and effects.
///
/// # Safety
/// The state manager, the scene manager, the actor and the spawn helpers must
/// all be valid; the caller must run with the original ABI.
///
/// # Confidence
/// medium - every branch, table index and packed bit is literal; the two
/// `0x80AAA3E0`/`0x80AAA480` callees are truncated in the export and are
/// called by address, and the `2^52` pairs are modelled as the same
/// integer-to-double bias the rest of the file uses.
pub unsafe fn fn_80aad010(actor: usize) -> u32 {
    if platform::read_u16(actor + 0x500) != 0 {
        return 0;
    }
    if platform::read_u8(W125_DAT_80429D48 + 0xBCB) == 1 {
        return 0;
    }

    if platform::read_u32(actor + 0xE1C) != 0 {
        let left = platform::read_u32(actor + 0xE1C) - 1;
        platform::write_u32(actor + 0xE1C, left);
    }
    if platform::read_u32(actor + 0xE1C) != 0 {
        return 0;
    }
    if fn_80aacd50(actor) == 0 {
        return 0;
    }

    let slot = fn_80aace90(actor);
    if slot == -1 {
        return 0;
    }
    let slot = slot as u32;
    let mode = platform::read_u32(actor + 0xE18);

    let mut x = read_f32(actor + 0xAC);
    let mut y = read_f32(actor + 0xB0)
        + read_f32(W125_F32_80B2F8E8 + mode as usize * 4)
        + (read_f32(actor + 0xE04) - read_f32(W125_F32_80B2F89C));
    // observed: the `2^52` pair converts the unsigned slot index to a float.
    let slot_bias = f64::from_bits(0x4330_0000_0000_0000 | ((slot ^ 0x8000_0000) as u64));
    let mut z = -(read_f32(W125_F32_80B2F8A4)
        * (slot_bias - read_f64(W125_F64_80B2F900)) as f32);
    if mode == 1 {
        z = read_f32(actor + 0xB4) - read_f32(W125_F32_80B2F8A4);
    }
    if mode == 1 && platform::read_u32(actor + 0xE20) != 0 {
        let count = platform::read_u32(actor + 0xE20);
        let count_bias = f64::from_bits(0x4330_0000_0000_0000 | count as u64);
        y += read_f32(W125_F32_80B2F8A4)
            * ((count_bias - read_f64(W125_F64_80B2F8E0)) as f32)
            * read_f32(actor + 0xE0);
    }

    // inferred: `+0xE24` selects the shot side; mode 0 asks the player query,
    // modes 1 and 2 hard-code the right and left sides.
    let aim_mode = platform::read_u32(actor + 0xE24);
    let (side_word, side_right) = if aim_mode == 0 {
        let side = call2(W125_FN_80096240, actor as u32, (actor + 0xAC) as u32) as u8;
        (0u32, side != 0)
    } else if aim_mode == 1 {
        (0x12u32, true)
    } else {
        (2u32, false)
    };
    let mut spawn_word =
        side_word | (slot << 8) | (platform::read_u32(actor + 4) & 0x0030_0000);

    if mode == 0 {
        if read_f32(W125_F32_80B2F894) != read_f32(W125_F32_80B2F8B4) {
            let mut seed = read_f32(W125_F32_80B2F894) as u32;
            if seed == 0 {
                seed = 1;
            }
            spawn_word |= seed << 0x1C;
            let seed_bias =
                f64::from_bits(0x4330_0000_0000_0000 | ((seed ^ 0x8000_0000) as u64));
            y += read_f32(W125_F32_80B2F8F4)
                * ((seed_bias - read_f64(W125_F64_80B2F900)) as f32);
        }
        if side_right {
            x -= read_f32(W125_F32_80B2F8F8);
        } else {
            x += read_f32(W125_F32_80B2F8F8);
        }
    }

    let mut vector = [x, y, z];
    if mode == 0 {
        vector[2] = read_f32(actor + 0xB4) - read_f32(W125_F32_80B2F8D8);
        let spawned = if platform::read_u32(actor + 0xE10) == 0 {
            call2(W125_FN_80AAA3E0, vector.as_mut_ptr() as u32, spawn_word)
        } else {
            call2(
                W125_FN_80AAA480,
                vector.as_mut_ptr() as u32,
                spawn_word | (platform::read_u32(actor + 0xE14) << 0xC),
            )
        };
        if spawned != 0 {
            let record = platform::read_u32(spawned as usize);
            platform::write_u32(actor + slot as usize * 4 + 0xB44, record);
            let mut echo = [0u8; 16];
            call2(
                W125_FN_8006A4B0,
                echo.as_mut_ptr() as u32,
                vector.as_ptr() as u32,
            );
            call4(
                W125_FN_80198C30,
                platform::read_u32(W125_SOUND_80429D60),
                0x1C1,
                echo.as_mut_ptr() as u32,
                0,
            );
        }
    } else {
        let mut flag = [0u8; 1];
        let limit = platform::read_u32(actor + 0xE28) & 0xFFFF;
        let spawned = if platform::read_u32(actor + 0xE10) == 0 {
            call4(
                W125_FN_80AAA360,
                vector.as_mut_ptr() as u32,
                spawn_word,
                flag.as_mut_ptr() as u32,
                limit,
            )
        } else {
            call4(
                W125_FN_80AAA400,
                vector.as_mut_ptr() as u32,
                spawn_word | (platform::read_u32(actor + 0xE14) << 0xC),
                flag.as_mut_ptr() as u32,
                limit,
            )
        };
        if spawned == 0 {
            return 0;
        }
        let record = platform::read_u32(spawned as usize);
        platform::write_u32(actor + slot as usize * 4 + 0xB44, record);
        let mut echo = [0u8; 16];
        call2(
            W125_FN_8006A4B0,
            echo.as_mut_ptr() as u32,
            vector.as_ptr() as u32,
        );
        let sound = if platform::read_u32(actor + 0xE10) == 0 {
            0x1BD
        } else {
            0x1C4
        };
        call4(
            W125_FN_80198C30,
            platform::read_u32(W125_SOUND_80429D60),
            sound,
            echo.as_mut_ptr() as u32,
            0,
        );
    }

    vector[2] = read_f32(W125_F32_80B2F8FC);
    if mode == 0 {
        let name = if side_right {
            W125_NAME_80B540E8
        } else {
            W125_NAME_80B54100
        };
        call5(
            W125_FN_8016C890,
            name as u32,
            0,
            (actor + 0xDE0) as u32,
            0,
            0,
        );
    } else {
        let nx = if side_right {
            read_f32(actor + 0xAC) - read_f32(W125_F32_80B2F8B0)
        } else {
            read_f32(W125_F32_80B2F8B0) + read_f32(actor + 0xAC)
        };
        let mut point = vector;
        point[0] = nx;
        call1(W125_FN_80094490, point.as_mut_ptr() as u32);
    }
    platform::write_u16(actor + 0xE34, 1);
    // observed: `0.0` is the timer length handed to the `+0xA0C` slot.
    call2_f64(W125_FN_80168FE0, 0.0, (actor + 0xA0C) as u32);
    1
}

