        platform::write_u32(actor + 0xDC, platform::read_u32(W77_DAT_80B2C54C));
        platform::write_u32(actor + 0xE0, platform::read_u32(W77_DAT_80B2C54C));
        platform::write_u32(actor + 0xE4, platform::read_u32(W77_DAT_80B2C54C));
