/// Per-frame group of the `+0x750` timer actor.
///
/// # Original
/// - Ghidra: `FUN_80b26a10` at `0x80B26A10` (168 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b26a10_FUN_80b26a10.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the controller actor; `+0x750` is its countdown.
///
/// # Side effects
/// Decrements `+0x750`, runs the four sibling steps, and when the countdown
/// reaches zero clears the `+0x738`/`+0x732`/`+0x72F`/`+0x730`/`+0x736`
/// bytes and enters `0x80B7982C`; finally dispatches `+0x72C`.
///
/// # Safety
/// The `+0x60` class vtable and the four sibling steps must be callable.
///
/// # Confidence
/// high - the decrement guard, the four calls, the five byte clears and the
/// final dispatch are literal.
pub unsafe fn fn_80b26a10(this: usize) {
    if platform::read_u32(this + 0x750) != 0 {
        let value = platform::read_u32(this + 0x750).wrapping_sub(1);
        platform::write_u32(this + 0x750, value);
    }
    call1(W129_FN_80B265C0, this as u32);
    call1(W129_FN_80B25E20, this as u32);
    call2(W129_FN_80B263E0, this as u32, 1);
    call1(W129_FN_80B264C0, this as u32);
    if platform::read_u32(this + 0x750) == 0 {
        platform::write_u8(this + 0x738, 0);
        platform::write_u8(this + 0x732, 0);
        platform::write_u8(this + 0x72F, 0);
        platform::write_u8(this + 0x730, 0);
        platform::write_u8(this + 0x736, 0);
        let vtable = platform::read_u32(this + 0x60) as usize;
        let _ = call2(
            platform::read_u32(vtable + 0xD4) as usize,
            this as u32,
            W129_TOKEN_80B7982C,
        );
    }
    call1(W129_FN_80B25D90, this as u32);
}

/// Refreshes the per-player short for each active `+0x8C4` slot.
///
/// # Original
/// - Ghidra: `FUN_80b28310` at `0x80B28310` (96 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b28310_FUN_80b28310.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x8C4` starts a four-byte player mask and `+0x8B4`
///   is the signed short written for each active slot.
///
/// # Side effects
/// For each non-zero mask byte, resolves the player through `0x8005F900(i)`
/// and forwards `(player, +0x8B4)` to `0x801339E0`.
///
/// # Safety
/// The player manager behind `0x8005F900` must be live.
///
/// # Confidence
/// high - the four-iteration loop and both calls are literal.
pub unsafe fn fn_80b28310(this: usize) {
    let mut i: usize = 0;
    loop {
        if platform::read_u8(this + i + 0x8C4) != 0 {
            let value = platform::read_u16(this + 0x8B4) as i16 as i32 as u32;
            let player = call1(W129_FN_8005F900, i as u32);
            call2(W129_FN_801339E0, player, value);
        }
        i += 1;
        if i >= 4 {
            break;
        }
    }
}

