    let extent_z = cell * platform::read_u8(this + 0x4C2D) as i8 as f32;
    call3_f64_f64(W130_FN_80AD5480, extent_x as f64, extent_z as f64, this as u32);
    call1(W130_FN_80AD54A0, this as u32);
    let vtable = platform::read_u32(this + 0x60) as usize;
    let _ = call3_f64_f64(
        platform::read_u32(vtable + 0x280) as usize,
        extent_x as f64,
        extent_z as f64,
        this as u32,
    );
    call3_f64_f64(W130_FN_80AD5570, extent_x as f64, extent_z as f64, this as u32);

    write_f32(this + 0x320, read_f32(W130_DAT_80B30968));
    write_f32(this + 0x324, read_f32(W130_DAT_80B3096C));
    write_f32(this + 0x318, read_f32(W130_DAT_80B30970));
    write_f32(this + 0x31C, read_f32(W130_DAT_80B30970));

    // 0x80AD58C0: 12-byte block copied from the in-REL data word triple.
    platform::write_u32(this + 0x6D0, platform::read_u32(W130_DAT_80B5C22C));
    platform::write_u32(this + 0x6D4, platform::read_u32(W130_DAT_80B5C230));
    platform::write_u32(this + 0x6D8, platform::read_u32(W130_DAT_80B5C234));

