    let mut record = [0u32; 2];
    call2(W130_FN_8006A4B0, record.as_mut_ptr() as u32, (this + 0xAC) as u32);
    call6(
        W130_FN_80198870,
        platform::read_u32(W130_PTR_80429D5C),
        0x1E7,
        id,
        record.as_ptr() as u32,
        1,
        0,
    );

    let vtable = platform::read_u32(this + 0x548) as usize;
    let _ = call1(platform::read_u32(vtable + 0x1C) as usize, (this + 0x548) as u32);
    call1(W130_FN_8006CDE0, this as u32);
    call1(W130_FN_800955F0, this as u32);

    // 0x80ACC5B4: the swing entry selected by the direction byte.
    let x = read_f32(this + 0xAC);
    let index = platform::read_u8(this + 0x348) as usize;
    platform::write_u16(this + 0x102, platform::read_u16(this + 0x5D0 + 2 * index));
    let mut clamped = false;
    if x <= read_f32(W130_DAT_80B30728) {
        write_f32(this + 0xAC, read_f32(W130_DAT_80B30728));
        clamped = true;
    }

    call1(W130_FN_80096F60, this as u32);
    let flag = call1(W130_FN_80070CB0, (this + 0x1EC) as u32);
    call2(W130_FN_80ACAE70, this as u32, flag);
    if flag != 0 {
        let counter = platform::read_u16(this + 0x5D4);
        write_f32(this + 0xEC, read_f32(W130_DAT_80B306B0));
        if counter != 0xFFFF {
            platform::write_u16(this + 0x5D4, counter + 1);
        }
    }
    call2(
        W130_FN_8006EF40,
        (this + 0x1EC) as u32,
        platform::read_u32(this + 0x274),
    );
    call1(W130_FN_80097050, this as u32);
    if clamped {
        write_f32(this + 0xAC, x);
    }

    call1(W130_FN_80ACB200, this as u32);
    call1(W130_FN_80ACB330, this as u32);
    let mut side = [0u32; 1];
    if call2(W130_FN_80ACB280, this as u32, side.as_mut_ptr() as u32) != 0 {
        if platform::read_u8(this + 0x348) as u32 == side[0] {
            w130_state_call(this, W130_TOKEN_80B76178);
        } else {
            w130_state_call(this, W130_TOKEN_80B76138);
        }
    } else if call2(
        W130_FN_80ACB430,
        this as u32,
        platform::read_u8(this + 0x348) as u32,
    ) != 0
    {
        w130_state_call(this, W130_TOKEN_80B760B8);
    }
