/// Ice-slide state aid with an angle ramp.
///
/// # Original
/// - Ghidra: `FUN_80a35170` at `0x80A35170` (464 bytes)
/// - Evidence: `work/ghidra/rel_d_enemiesNP/export/80a35170_FUN_80a35170.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the sliding actor; `+0x5BC` is the rail object, `+0x488` the
///   guard word, `+0x6AC`/`+0x6B0` the current/previous query results,
///   `+0x6B8` the trigger count, `+0x6A8` the "ramping" byte, `+0x6B4` the
///   ramp direction and `+0x104` the ramped angle.
///
/// # Side effects
/// Copies the rail sample into `+0xAC`/`+0xB0`, and when the guard is clear it
/// advances the trigger count and runs the `0x21D`/`0x21E` sound plus the
/// `0x800` step on `+0x104`.
///
/// # Safety
/// The `+0x5BC` rail, the `+0x628` query object and the sound manager must be
/// live.
///
/// # Confidence
/// high - every branch and store is literal. The saved query result lives at
/// `+0x6B0` (word `stw r0,0x6b0(r31)` at `0x80A351C8`), not `+0x6B4`: the
/// specification's `+0x6B4` for that slot is a typo, and `+0x6B4` is the ramp
/// direction written later at `0x80A352B0`.
pub unsafe fn fn_80a35170(this: usize) {
    call1(W130_FN_800C1230, (this + 0x5BC) as u32);
    let mut sample = [0u32; 2];
    call2(W130_FN_800C12B0, sample.as_mut_ptr() as u32, (this + 0x5BC) as u32);
    // 0x80A3519C: two dead stack copies of the sample (no observable effect).
    let px = f32::from_bits(sample[0]);
    let py = f32::from_bits(sample[1]);
    write_f32(this + 0xAC, px);
    write_f32(this + 0xB0, py);

    if (platform::read_u32(this + 0x488) as i32) > 0 {
        return;
    }

    // 0x80A351C0: remember the previous query result, then refresh it.
    platform::write_u32(this + 0x6B0, platform::read_u32(this + 0x6AC));
    let holder = platform::read_u32(this + 0x628) as usize;
    let owner = call1(platform::read_u32(holder + 0x28) as usize, (this + 0x628) as u32) as usize;
    let now = call2(
        platform::read_u32(platform::read_u32(owner) as usize + 0x10) as usize,
        owner as u32,
        W130_TOKEN_EXT_80358E50,
    );
    let previous = platform::read_u32(this + 0x6B0);
    platform::write_u32(this + 0x6AC, now);
    if previous == 0 && now == 1 {
        platform::write_u32(this + 0x6B8, platform::read_u32(this + 0x6B8) + 1);
    }

    // 0x80A35218: the first trigger of a slide picks the ramp direction.
    if (platform::read_u32(this + 0x6B8) as i32) > 0 && platform::read_u8(this + 0x6A8) == 0 {
        platform::write_u8(this + 0x6A8, 1);
        let sound = platform::read_u32(W130_PTR_80429D5C);
        let mut record = [0u32; 4];
        if (platform::read_u32(this + 4) >> 8) & 1 == 0 {
            call2(
                W130_FN_8006A4B0,
                record.as_mut_ptr() as u32,
                (this + 0xAC) as u32,
            );
            call4(W130_FN_80197F00, sound, 0x21D, record.as_ptr() as u32, 0);
        } else {
            call2(
                W130_FN_8006A4B0,
                record.as_mut_ptr() as u32,
                (this + 0xAC) as u32,
            );
            call4(W130_FN_80197F00, sound, 0x21E, record.as_ptr() as u32, 0);
        }

        let speed = read_f32(this + 0x5F4);
        if speed > read_f32(W130_DAT_80B2C094) {
            platform::write_u32(this + 0x6B4, 0);
        } else if speed < read_f32(W130_DAT_80B2C094) {
            platform::write_u32(this + 0x6B4, 1);
        } else {
            platform::write_u32(this + 0x6B4, call1(W130_FN_800B2ED0, 2));
        }
    }

    if platform::read_u8(this + 0x6A8) == 0 {
        return;
    }

    // 0x80A352E8: ramp `+0x104` by 0x800 until it wraps to zero.
    let step: u16 = 0x800;
    let angle = platform::read_u16(this + 0x104);
    if platform::read_u32(this + 0x6B4) == 0 {
        platform::write_u16(this + 0x104, angle.wrapping_sub(step));
    } else {
        platform::write_u16(this + 0x104, angle.wrapping_add(step));
    }
    if platform::read_u16(this + 0x104) != 0 {
        return;
    }
    platform::write_u8(this + 0x6A8, 0);
    platform::write_u32(this + 0x6B8, platform::read_u32(this + 0x6B8) - 1);
}

