    let vtable = platform::read_u32(this + 0x54C) as usize;
    let _ = call1(platform::read_u32(vtable + 0x1C) as usize, (this + 0x54C) as u32);
    if platform::read_u32(this + 0x750) != 0 {
        let vtable = platform::read_u32(this + 0x69C) as usize;
        let _ = call1(platform::read_u32(vtable + 0x1C) as usize, (this + 0x69C) as u32);
        let vtable = platform::read_u32(this + 0x718) as usize;
        let _ = call1(platform::read_u32(vtable + 0x14) as usize, (this + 0x718) as u32);
    }

