///
/// # Confidence
/// high - the null guard, the `> 0` test and the unchanged return are literal.
pub unsafe fn fn_80add0e0(holder: usize, count: i32) -> usize {
    if holder != 0 {
        call2(W130_FN_8015F800, holder as u32, 0);
        if count > 0 {
            call1(W130_FN_802B9280, holder as u32);
        }
    }
    holder
}

/// Frame step that integrates the three offsets into the position block.
///
/// # Original
/// - Ghidra: `FUN_80ade300` at `0x80ADE300` (116 bytes)
/// - Evidence: `work/ghidra/rel_d_enemiesNP/export/80ade300_FUN_80ade300.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x6B8` is the model node, `+0xE8..+0xF0` the three
///   offsets and `+0x888..+0x890` the accumulated position.
///
/// # Side effects
/// Runs the node's `+0x1C` slot, adds the three offsets and forwards to
/// `0x80ADDA40`.
///
/// # Safety
/// The `+0x6B8` node must be live.
///
/// # Confidence
/// high - one vtable call, three adds and one tail helper.
pub unsafe fn fn_80ade300(this: usize) {
    let vtable = platform::read_u32(this + 0x6B8) as usize;
    let _ = call1(platform::read_u32(vtable + 0x1C) as usize, (this + 0x6B8) as u32);
    write_f32(this + 0x888, read_f32(this + 0x888) + read_f32(this + 0xE8));
    write_f32(this + 0x88C, read_f32(this + 0x88C) + read_f32(this + 0xEC));
    write_f32(this + 0x890, read_f32(this + 0x890) + read_f32(this + 0xF0));
    call1(W130_FN_80ADDA40, this as u32);
}

/// Frame step without the offset integration, byte-shorter sibling of
/// [`fn_80ade300`].
///
/// # Original
/// - Ghidra: `FUN_80ade450` at `0x80ADE450` (68 bytes)
/// - Evidence: `work/ghidra/rel_d_enemiesNP/export/80ade450_FUN_80ade450.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
