///
/// # Side effects
/// Runs the node's `+0x1C` slot and forwards to `0x80ADDA40`.
///
/// # Safety
/// The `+0x6B8` node must be live.
///
/// # Confidence
/// high - the whole body is those two calls.
pub unsafe fn fn_80ade450(this: usize) {
    let vtable = platform::read_u32(this + 0x6B8) as usize;
    let _ = call1(platform::read_u32(vtable + 0x1C) as usize, (this + 0x6B8) as u32);
    call1(W130_FN_80ADDA40, this as u32);
}

/// Water-surface state predicate of the `0x854`-state actor.
///
/// # Original
/// - Ghidra: `FUN_80ad4220` at `0x80AD4220` (136 bytes)
/// - Evidence: `work/ghidra/rel_d_enemiesNP/export/80ad4220_FUN_80ad4220.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x854` is its state word and `+0x81C` the queried
///   object.
///
/// # Returns
/// `1` unless the query in state `10` returns a value outside `{2, 3}`.
///
/// # Side effects
/// In state `10`, writes `0x10` when the query returns `3` and `1` when it
/// returns `2`.
///
/// # Safety
/// The manager at `0x8042A0D0` and the `+0x81C` object must be live.
///
/// # Confidence
/// high - the state guard, the two-entry window and both writes are literal.
pub unsafe fn fn_80ad4220(this: usize) -> u32 {
    if platform::read_u32(this + 0x854) != 10 {
        return 1;
    }
    let result = call4(
        W130_FN_800E76A0,
        platform::read_u32(W130_PTR_EXT_8042A0D0),
        (this + 0x81C) as u32,
        0,
        0,
    );
    if result == 2 || result == 3 {
        platform::write_u32(this + 0x854, if result == 3 { 0x10 } else { 1 });
        1
    } else {
        0
    }
}

/// Rail position copy of the `0x4C30` container actor.
///
/// # Original
/// - Ghidra: `FUN_80ad3ce0` at `0x80AD3CE0` (108 bytes)
/// - Evidence: `work/ghidra/rel_d_enemiesNP/export/80ad3ce0_FUN_80ad3ce0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x840` is the rail offset, `+0x728` the rail object
///   and `+0x61C` the ground height.
///
/// # Side effects
/// Sets the rail offset, samples the rail into `+0xAC`/`+0xB0`, and subtracts
/// `5.0` from the height before adding `+0x61C`.
///
/// # Safety
/// The `+0x728` rail must be live.
///
/// # Confidence
/// high - the offset call, the sample and the two stores are literal.
pub unsafe fn fn_80ad3ce0(this: usize) {
    call2_f64(
        W130_FN_800C1510,
        read_f32(this + 0x840) as f64,
        (this + 0x728) as u32,
    );
    call1(W130_FN_800C1230, (this + 0x728) as u32);
    let mut sample = [0u32; 2];
    call2(W130_FN_800C12B0, sample.as_mut_ptr() as u32, (this + 0x728) as u32);
    platform::write_u32(this + 0xAC, sample[0]);
    write_f32(
        this + 0xB0,
        (f32::from_bits(sample[1]) - read_f32(W130_DAT_80B30948)) + read_f32(this + 0x61C),
    );
}

/// Scale/range installer of the `0x4C30` container actor.
///
/// # Original
/// - Ghidra: `FUN_80ad7310` at `0x80AD7310` (148 bytes)
/// - Evidence: `work/ghidra/rel_d_enemiesNP/export/80ad7310_FUN_80ad7310.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x4C30` is the range object and `+0x4C4C..+0x4C58`
///   its four fields.
/// - `scale`: the incoming `f1`, halved by `0x80B309B4`.
///
/// # Side effects
/// Installs the range on `+0x4C30`, writes `(0.5 * scale, 4.0, 0.5 * scale -
/// 1.0, 5.0)`, flushes it, then writes the two `+0x4CD4` fields.
///
/// # Safety
/// The `+0x4C30` range object must be live.
///
/// # Confidence
/// high - the halving multiply, the four stores and the flush are literal.
pub unsafe fn fn_80ad7310(this: usize, scale: f32) {
    let value = scale * read_f32(W130_DAT_80B309B4);
    call3(
        W130_FN_8008C3E0,
        (this + 0x4C30) as u32,
        this as u32,
        W130_DAT_80B30988 as u32,
    );
    write_f32(this + 0x4C4C, value);
    platform::write_u32(this + 0x4C50, platform::read_u32(W130_DAT_80B309CC));
    write_f32(this + 0x4C54, value - read_f32(W130_DAT_80B309E0));
    platform::write_u32(this + 0x4C58, platform::read_u32(W130_DAT_80B309C0));
    call1(W130_FN_8008C330, (this + 0x4C30) as u32);
    write_f32(this + 0x4CD4, value);
    platform::write_u32(this + 0x4CD8, platform::read_u32(W130_DAT_80B309CC));
}

