// --- Section-local adapters -------------------------------------------------

/// Calls one vtable slot of `receiver` with `r3 = receiver` and no other
/// argument.
#[inline]
unsafe fn w131_vt(receiver: usize, slot: usize) {
    let vtable = platform::read_u32(receiver) as usize;
    let _ = call1(platform::read_u32(vtable + slot) as usize, receiver as u32);
}

/// Calls one vtable slot of `receiver` with `r3 = receiver` and one argument.
#[inline]
unsafe fn w131_vt1(receiver: usize, slot: usize, a: u32) {
    let vtable = platform::read_u32(receiver) as usize;
    let _ = call2(platform::read_u32(vtable + slot) as usize, receiver as u32, a);
}

/// Per-frame step of `Wm_en_burst_water`: timer, rate ramp, sound and holder
/// updates.
///
/// # Original
/// - Ghidra: `FUN_80ab2460` at `0x80AB2460` (444 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80ab2460_FUN_80ab2460.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the water-burst actor; `+0x998` is the `u16` frame timer,
///   `+0x8B4/+0x8B8` the two cached displacement floats, `+0x958` the rate,
///   `+0xE8..+0xF0` the velocity, `+0x73C`/`+0x794` the two effect holders,
///   `+0x988` the second-holder gate and `+0xAC` the position.
///
/// # Side effects
/// Decrements the timer, may dispatch the hidden state at `+0x60` slot `+0xD4`,
/// normalises the displacement, ramps the rate down to `1.2`, writes the
/// velocity, runs the base update with `(0, vy, vx)`, and on the active path
/// emits sound cue `0x208`, the two holder slot-`0x14` calls, the angle sweep
/// and the `0x40`-frame countdown.
///
/// # Safety
/// The actor, its `+0x60` vtable, both holders and the sound manager at
/// `0x80429D5C` must be live.
///
/// # Confidence
/// high - every field, constant and call is literal in the export; the `f1`
/// operand of `0x8006CD40` is the literal `0.0` (not `v[2]*rate`).
pub unsafe fn fn_80ab2460(this: usize) {
    // 0x80AB247C: tick the `u16` frame timer.
    if platform::read_u16(this + 0x998) != 0 {
        platform::write_u16(this + 0x998, platform::read_u16(this + 0x998) - 1);
    }

    // 0x80AB2498: the expired timer gates the hidden-state path.
    if platform::read_u16(this + 0x998) == 0 && call1(W131_FN_80AB1CE0, this as u32) == 0 {
        w130_state_call(this, W131_TOKEN_80B750D0);
        return;
    }

    // 0x80AB24CC: three-float direction from the two cached displacements.
    let mut direction = [
        platform::read_u32(this + 0x8B4),
        platform::read_u32(this + 0x8B8),
        platform::read_u32(W131_DAT_80B2FAE4),
    ];
    call1(W131_FN_80170A00, direction.as_mut_ptr() as u32);

    // 0x80AB24F0: decrement the rate and clamp it to the floor.
    let mut rate = read_f32(this + 0x958) - read_f32(W131_DAT_80B54BB0);
    write_f32(this + 0x958, rate);
    if rate <= read_f32(W131_DAT_80B54BA8) {
        rate = read_f32(W131_DAT_80B54BA8);
        write_f32(this + 0x958, rate);
    }

    // 0x80AB251C: scale the unit vector; the z slot is a literal zero.
    let vx = f32::from_bits(direction[0]) * rate;
    let vy = f32::from_bits(direction[1]) * rate;
    write_f32(this + 0xE8, vx);
    write_f32(this + 0xEC, vy);
    write_f32(this + 0xF0, read_f32(W131_DAT_80B2FAE4));

    // 0x80AB255C: note the argument order - `f1` is the zero z slot.
    call4_f64_f64_f64(
        W131_FN_8006CD40,
        read_f32(W131_DAT_80B2FAE4) as f64,
        vy as f64,
        vx as f64,
        this as u32,
    );

    if call1(W131_FN_80AB1EC0, this as u32) != 0 {
        return;
    }

    // 0x80AB2580: height clamp only while the timer still runs.
    if platform::read_u16(this + 0x998) != 0 {
        call1(W131_FN_80AB1CA0, this as u32);
    }

    // 0x80AB2598: sound position record and cue `0x208`.
    let mut position = [0u32; 4];
    call2(
        W131_FN_8006A4B0,
        position.as_mut_ptr() as u32,
        (this + 0xAC) as u32,
    );
    call5(
        W131_FN_80198660,
        platform::read_u32(W131_PTR_80429D5C),
        0x208,
        platform::read_u32(this),
        position.as_ptr() as u32,
        0,
    );

    call1(W131_FN_80AB1FA0, this as u32);

    // 0x80AB25CC: refresh both effect holders.
    w131_vt(this + 0x73C, 0x14);
    if platform::read_u32(this + 0x988) == 1 {
        w131_vt(this + 0x794, 0x14);
    }

    call1(W131_FN_80AB1DF0, this as u32);
    call1(W131_FN_80AB1830, this as u32);
}

/// Builds the 60-byte particle record of the state-selected effect arm.
///
/// # Original
/// - Ghidra: `FUN_80ab0c00` at `0x80AB0C00` (440 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80ab0c00_FUN_80ab0c00.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the emitter; `+0x98C` selects the arm, `+0xAC..+0xB4` is the
///   position and `+0x484` the owning effect slot.
///
/// # Returns
/// The word returned by `0x800B8700` for the committed record.
///
/// # Side effects
/// Writes the 15-word record (type `2`, position, the scale triplet, eight zero
/// words), commits it at `+0x484`, and registers the callback block
/// `0x80A0B5A0` for `0x3C` bytes / one record.
///
/// # Safety
/// The effect slot at `+0x484` must be live.
///
/// # Confidence
/// high - all three state arms are byte-identical (verified word for word), so
/// the empty guard is exact; every store and both calls are literal.
pub unsafe fn fn_80ab0c00(this: usize) -> u32 {
    // 0x80AB0C18: every arm (`+0x98C` 0, 1 or anything else) executes the same
    // 13 stores, so the switch only contributes its read.
    let _state = platform::read_u32(this + 0x98C);

    let mut record = [0u32; 15];
    record[0] = 2; // record type/count
    record[1] = platform::read_u32(this + 0xAC);
    record[2] = (read_f32(this + 0xB0) - read_f32(W131_DAT_80B2FB00)).to_bits();
    record[3] = platform::read_u32(this + 0xB4);
    record[4] = platform::read_u32(W131_DAT_80B2FAF0);
    record[5] = platform::read_u32(W131_DAT_80B2FB04);
    record[6] = platform::read_u32(W131_DAT_80B2FAF0);
    // 0x80AB0D60: the eight trailing words are zeroed in a loop; in the
    // original they are written before the type and position words.
    for word in record.iter_mut().skip(7) {
        *word = platform::read_u32(W131_DAT_80B2FAE4);
    }

    let result = call3(
        W131_FN_800B8700,
        (this + 0x484) as u32,
        record.as_ptr() as u32,
        1,
    );
    call4(
        W131_FN_802DCA98,
        record.as_ptr() as u32,
        W131_DAT_80A0B5A0,
        0x3C,
        1,
    );
    result
}

/// Binds the `pukupuku` model, its `fly` clip pair and its damage animation.
///
/// # Original
/// - Ghidra: `FUN_80b0f5a0` at `0x80B0F5A0` (440 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b0f5a0_FUN_80b0f5a0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x524`/`+0x544` are the model and node holders,
///   `+0x540` the model record, `+0x584` the clip pair and `+0x5BC`/`+0x5C0`
///   the damage handle and holder.
///
/// # Side effects
/// Resets and finishes `+0x524`, loads `g3d/pukupuku.brres`, binds the node and
/// the `fly` clip pair, blends both animations at `1.0`, binds the damage
/// record through the `+0x544` slot `+0x18` and clears both damage rates.
///
/// # Safety
/// The archive manager at `0x8042A038`, the animator argument at `0x80377C48`
/// and every holder must be live.
///
/// # Confidence
/// high - every call argument is literal; the `r1+0x08..0x20` duplicates are
/// reproduced as the exact stack slots the four pointer calls read.
pub unsafe fn fn_80b0f5a0(this: usize) {
    call5(
        W131_FN_800690C0,
        (this + 0x524) as u32,
        0xFFFF_FFFF,
        platform::read_u32(W131_WORD_80377C48),
        0,
        0x20,
    );

    let model_record = call3(
        W131_FN_800DF180,
        platform::read_u32(W131_PTR_8042A038) + 4,
        W131_STR_PUKUPUKU,
        W131_STR_G3D_PUKUPUKU,
    );
    platform::write_u32(this + 0x540, model_record);

    let model = call2(W131_FN_80239E30, (this + 0x540) as u32, W131_STR_PUKUPUKU);
    let mut node = [model];
    call6(
        W131_FN_80169D90,
        (this + 0x544) as u32,
        node.as_ptr() as u32,
        (this + 0x524) as u32,
        0x23,
        1,
        0,
    );
    call1(W131_FN_80064BD0, (this + 0x544) as u32);

    let anim = call2(W131_FN_8023A0B0, (this + 0x540) as u32, W131_STR_FLY);
    let mut model_pair = [model];
    let mut anim_pair = [anim];
    call5(
        W131_FN_801650D0,
        (this + 0x584) as u32,
        model_pair.as_ptr() as u32,
        anim_pair.as_ptr() as u32,
        (this + 0x524) as u32,
        0,
    );
    let mut anim_attach = [anim];
    call4(
        W131_FN_801651F0,
        (this + 0x584) as u32,
        (this + 0x544) as u32,
        anim_attach.as_ptr() as u32,
        0,
    );
    call3_f64(
        W131_FN_80169F80,
        read_f32(W131_DAT_80B31F94) as f64,
        (this + 0x544) as u32,
        (this + 0x584) as u32,
    );
    call2_f64(
        W131_FN_801680E0,
        read_f32(W131_DAT_80B31F94) as f64,
        (this + 0x584) as u32,
    );

    let damage = call2(W131_FN_8023A200, (this + 0x540) as u32, W131_STR_PUKUPUKU);
    platform::write_u32(this + 0x5BC, damage);

    let mut damage_model = [model];
    let mut damage_handle = [damage];
    call6(
        W131_FN_80166830,
        (this + 0x5C0) as u32,
        damage_model.as_ptr() as u32,
        damage_handle.as_ptr() as u32,
        (this + 0x524) as u32,
        0,
        1,
    );
    let mut damage_attach = [platform::read_u32(this + 0x5BC)];
    call5(
        W131_FN_80166BD0,
        (this + 0x5C0) as u32,
        (this + 0x544) as u32,
        damage_attach.as_ptr() as u32,
        0,
        1,
    );

    // 0x80B0F708: the node holder's slot `+0x18` takes the damage holder.
    w131_vt1(this + 0x544, 0x18, (this + 0x5C0) as u32);

    call3_f64(
        W131_FN_80166EF0,
        read_f32(W131_DAT_80B31F80) as f64,
        (this + 0x5C0) as u32,
        0,
    );
    call3_f64(
        W131_FN_80166F10,
        read_f32(W131_DAT_80B31F80) as f64,
        (this + 0x5C0) as u32,
        0,
    );
    call1(W131_FN_800690E0, (this + 0x524) as u32);
}

/// State callback of the `+0x854` machine: rewrites the position z and the
/// four flags, then dispatches one of four state tokens.
