    platform::write_u16(this + 0x6A0, 50);
    platform::write_u32(this + 0x6D0, W131_FN_80021140);
    platform::write_u32(this + 0x6D4, W131_FN_80021150);
    platform::write_u32(this + 0x6D8, W131_FN_80021160);
    platform::write_u32(this + 0x574, W131_FN_80021140);
    platform::write_u32(this + 0x578, W131_FN_80021150);
    platform::write_u32(this + 0x57C, W131_FN_80021160);
