/// - Ghidra: `FUN_80b1e540` at `0x80B1E540` (380 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b1e540_FUN_80b1e540.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x360` is the state word, `+0x10C` the ramp,
///   `+0x614/+0x618` the two speed factors, `+0x500` a `u16` countdown,
///   `+0x694` the state controller and `+0x544`/`+0x5C0` two render holders.
///
/// # Side effects
/// Refreshes both holders, and in state 1 ramps the speed toward `8.0`, runs
/// the base update and leaves the state once the elapsed time reaches
/// `4.0 + t`; in state 2 it re-enters when the countdown reaches zero.
///
/// # Safety
/// The two holders and the `+0x694` controller must be live.
///
/// # Confidence
/// medium - all arithmetic and tokens are literal; the unit of the
/// `0x800E9020` return is not established.
pub unsafe fn fn_80b1e540(this: usize) {
    w131_vt(this + 0x544, 0x1C);
    w131_vt(this + 0x5C0, 0x14);

    match platform::read_u32(this + 0x360) {
        // 0x80B1E590: state 1 ramps the speed and watches the timer.
        1 => {
            let mut ramp = read_f32(this + 0x10C) + read_f32(W131_DAT_80B32640);
            write_f32(this + 0x10C, ramp);
            if ramp > read_f32(W131_DAT_80B32684) {
                ramp = read_f32(W131_DAT_80B32684);
                write_f32(this + 0x10C, ramp);
            }
            write_f32(this + 0xE8, ramp * read_f32(this + 0x614));
            write_f32(this + 0xEC, ramp * read_f32(this + 0x618));

            // observed: no float argument is prepared for this call.
            call1(W131_FN_8006CD40, this as u32);
            call3(W131_FN_8015F4F0, (this + 0x104) as u32, 0, 0x480);

            let elapsed = call1_ret_f32(W131_FN_800E9020, (this + 0x668) as u32);
            let target = read_f32(W131_DAT_80B32690) + elapsed;
            if call1_ret_f32(W131_FN_80B1D680, this as u32) >= target {
                call1(W131_FN_80B1DA40, this as u32);
                w131_vt1(this + 0x694, 0x18, W131_TOKEN_80371B88);
                platform::write_u16(this + 0x500, 120);
                platform::write_u32(this + 0x360, 2);
            }
        }
        // 0x80B1E658: state 2 waits for its countdown.
        2 => {
            if platform::read_u16(this + 0x500) == 0 {
                w131_vt1(this + 0x694, 0x18, W131_TOKEN_80371B48);
                w130_state_call(this, W131_TOKEN_80B79378);
            }
        }
        _ => {}
    }
}

/// Selects one `walk_st_*`/`walk_ed_*` clip pair from the in-REL table.
///
/// # Original
/// - Ghidra: `FUN_80a7bd30` at `0x80A7BD30` (372 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a7bd30_FUN_80a7bd30.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x348` is the side, `+0xEA1..+0xEA3` the three
///   sub-state bytes, `+0x540` the model, `+0x544` the node holder and
///   `+0x584` the animation holder.
///
/// # Side effects
/// Computes the table entry as `0x80B2DE58 + side*0x90 + ea1*0x48 +
/// ea2*0x18 + ea3*8`, stores the `walk_ed_*` word's address in `+0x614`,
/// binds and starts the clip at rate `45.0`, refreshes `+0xE9B`/`+0xE9C`/
/// `+0xEA6`/`+0x618`, and clears the `+0xEA8` bit of the selected index.
///
/// # Safety
/// The model and both holders must be live.
///
/// # Confidence
/// medium - the index arithmetic is literal (`mulli 0x90/0x48/0x18`, `slwi 3`);
/// the field roles come from the sibling `pukupuku` block.
pub unsafe fn fn_80a7bd30(this: usize) {
    let side = platform::read_u8(this + 0x348) as usize;
    let sub1 = platform::read_u8(this + 0xEA1) as usize;
    let sub2 = platform::read_u8(this + 0xEA2) as usize;
    let sub3 = platform::read_u8(this + 0xEA3) as usize;

    let entry = W131_TABLE_80B2DE58 + side * 0x90 + sub1 * 0x48 + sub2 * 0x18 + sub3 * 0x08;
    let clip = platform::read_u32(entry);
    platform::write_u32(this + 0x614, (entry + 4) as u32);

    let anim = call2(W131_FN_8023A0B0, (this + 0x540) as u32, clip);
    let mut attach = [anim];
    call4(
        W131_FN_801651F0,
        (this + 0x584) as u32,
        (this + 0x544) as u32,
        attach.as_ptr() as u32,
        1,
    );
    call3_f64(
        W131_FN_80169F80,
        read_f32(W131_DAT_80B2DE28) as f64,
        (this + 0x544) as u32,
        (this + 0x584) as u32,
    );
    call2_f64(
        W131_FN_801680E0,
        read_f32(W131_DAT_80B2DE28) as f64,
        (this + 0x584) as u32,
    );
    w131_vt(this + 0x544, 0x1C);
    call2_f64(
        W131_FN_80168FE0,
        read_f32(W131_DAT_80B2DE20) as f64,
        (this + 0x584) as u32,
    );

    platform::write_u8(this + 0xE9B, 0);
    platform::write_u8(this + 0xE9C, 0);
    platform::write_u8(this + 0xEA6, platform::read_u8(this + 0xEA5));
    platform::write_u32(this + 0x618, W131_DAT_80B2DE44 as u32);

    let rate = read_f32(W131_DAT_80B2DE40);
    call2_f64(W131_FN_80A7A2C0, rate as f64, this as u32);
    call2_f64(W131_FN_80A7A360, rate as f64, this as u32);

    // 0x80A7BE54: `lbzx` from the per-side index table, then clear that bit.
    let index = platform::read_u8(W131_TABLE_80B2DE38 + side * 2 + sub1);
    platform::write_u8(this + 0xEA8, platform::read_u8(this + 0xEA8) & !(1u8 << index));
    call1(
        W131_FN_8008C380,
        (this + 0xD1C + index as usize * 0xA4) as u32,
    );
    call1(W131_FN_80A7A030, this as u32);
    call1(W131_FN_80A7A170, this as u32);
}

/// Per-frame step with an angle-flip sign test and two effect records.
///
/// # Original
/// - Ghidra: `FUN_80ac9aa0` at `0x80AC9AA0` (372 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80ac9aa0_FUN_80ac9aa0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x544`/`+0x584` the holders, `+0x348` the side byte,
///   `+0x102` the yaw, `+0x1EC` a body object, `+0x878`/`+0x9A0` two effect
///   emitters and `+0x604..+0x618` two three-float positions.
///
/// # Side effects
/// Runs the base steps, zeroes `+0xEC` on body contact, stores the queried side
/// and starts the per-side turn, emits both effect records at z `5500.0`, and
/// when the old/new yaw product is `<= 0` resets the animation and runs
/// `0x80AC9310`.
///
/// # Safety
/// The actor, both holders and both effect emitters must be live.
///
/// # Confidence
/// medium - every call, token and record word is literal; the emitter and
/// position roles are inferred from the call shapes.
pub unsafe fn fn_80ac9aa0(this: usize) {
    w131_vt(this + 0x544, 0x1C);
    call1(W131_FN_8006CDE0, this as u32);
    call1(W131_FN_800955F0, this as u32);

    if call1(W131_FN_80072BC0, (this + 0x1EC) as u32) != 0 {
        write_f32(this + 0xEC, read_f32(W131_DAT_80B30544));
    }

    let previous_yaw = read_i16(this + 0x102);
    let side = (call2(W131_FN_80096240, this as u32, (this + 0xAC) as u32) & 0xFF) as u8;
    platform::write_u8(this + 0x348, side);
    let target = read_i16(W131_TABLE_80B30540 + side as usize * 2);
    call3(
        W131_FN_8015F4F0,
        (this + 0x102) as u32,
        target as i32 as u32,
        0x400,
    );

    // 0x80AC9B50: first effect record, from `+0x610/+0x614`.
    let mut first = [
        platform::read_u32(this + 0x610),
        platform::read_u32(this + 0x614),
        platform::read_u32(W131_DAT_80B305F8),
    ];
    w131_emit_effect(this + 0x878, W131_TOKEN_80B59D08, first.as_mut_ptr() as u32);

    // 0x80AC9B84: second effect record, from `+0x604/+0x608`.
    let mut second = [
        platform::read_u32(this + 0x604),
        platform::read_u32(this + 0x608),
        platform::read_u32(W131_DAT_80B305F8),
    ];
    w131_emit_effect(this + 0x9A0, W131_TOKEN_80B59D18, second.as_mut_ptr() as u32);

    // 0x80AC9BB4 `mullw.` - the product of the old and new yaw.
    let product = (previous_yaw as i32).wrapping_mul(read_i16(this + 0x102) as i32);
    if product <= 0 {
        call1(W131_FN_80168080, (this + 0x584) as u32);
        call1(W131_FN_80AC9310, this as u32);
    }

    if call1(W131_FN_80169020, (this + 0x584) as u32) != 0 {
        w130_state_call(this, W131_TOKEN_80B75E30);
    }
}

/// Emits one effect record through an emitter's slot `+0xA0`.
#[inline]
unsafe fn w131_emit_effect(emitter: usize, token: u32, record: u32) {
    let vtable = platform::read_u32(emitter) as usize;
    let _ = call6(
        platform::read_u32(vtable + 0xA0) as usize,
        emitter as u32,
        token,
        0,
        record,
        0,
        0,
    );
}

