    write_f32(this + 0xE8, speed);
    write_f32(this + 0xEC, b);
    write_f32(this + 0xF0, a);
    write_f32(this + 0xF4, a);
    write_f32(this + 0xF8, c);
    write_f32(this + 0xFC, a);
    write_f32(this + 0x114, d);
