/// Calls `fn(f32, f32, u32) -> u32`: the two probes of `0x80AD0960` take
/// single-precision `f1`/`f2` and the layer byte in `r3`.
#[inline]
unsafe fn w132_call_ffu(addr: usize, first: f32, second: f32, third: u32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f32, f32, u32) -> u32);
    f(first, second, third)
}

/// Calls `fn(f32, u32) -> u32`: the holder scale setter `0x800B6A70` takes the
/// scale in `f1` and the holder in `r3`.
#[inline]
unsafe fn w132_call_fu(addr: usize, first: f32, second: u32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f32, u32) -> u32);
    f(first, second)
}

/// Initialises the four-sample motion trail: four 12-byte position samples, two
/// `u`/`v`/`w` triplets and a four-word copy of the `u` values.
///
/// # Original
/// - Ghidra: `FUN_80ab2840` at `0x80AB2840` (356 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80ab2840_FUN_80ab2840.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the trail owner; `+0xAC..+0xB4` is the current position, `+0x8CC`
///   the four samples, `+0x908`/`+0x968` the `u` copies with `v` at `+0x90C`
///   and `w` at `+0x910`, `+0x93E` the four three-halfword blocks, `+0x95C` the
///   sample rate, `+0x960`/`+0x978` the two ext seeds, `+0x988` the gate for the
///   last helper.
///
/// # Side effects
/// Writes 4 x 12 position bytes, 4 x 3 texture coordinates, 4 x 3 halfwords,
/// the two `+0x968` copies and the six scalar fields at `+0xF8`, `+0xEC`,
/// `+0x114`, `+0x978`, `+0x960` and `+0x95C`, then calls `0x8008C380`,
/// `0x80AB1A00` and, when `+0x988 == 1`, `0x80166340`.
///
/// # Safety
/// The actor and the two holders reached by the calls must be live.
///
/// # Confidence
/// high - the loop body, the four tables, the ext words and all three calls are
/// literal; only the `u`/`v`/`w` field *names* are inferred from the sibling
/// four-sample writers.
pub unsafe fn fn_80ab2840(this: usize) {
    let eight = read_f32(W132_DAT_80B2FAE8);
    let zero = read_f32(W132_DAT_80B2FAE4);

    for k in 0..4 {
        let mut sample = this + 0x8CC + k * 0x0C;
        let x = platform::read_u32(this + 0xAC);
        let y = read_f32(this + 0xB0);
        let z = platform::read_u32(this + 0xB4);

        platform::write_u32(sample, x);
        // observed: the raw y is stored first, then overwritten by `y + 8.0`.
        write_f32(sample + 4, y);
        platform::write_u32(sample + 8, z);
        write_f32(sample + 4, y + eight);

        let u = read_f32(W132_TABLE_80B2FB5C + k * 4);
        let v = read_f32(W132_TABLE_80B2FB74 + k * 4);
        sample = this + 0x908 + k * 0x0C;
        write_f32(sample, u);
        write_f32(this + 0x968 + k * 4, u);
        write_f32(sample + 4, v);
        write_f32(sample + 8, zero);

        platform::write_u16(this + 0x93E + k * 6, 0);
        platform::write_u16(this + 0x93E + k * 6 + 2, 0x4000);
        platform::write_u16(this + 0x93E + k * 6 + 4, 0);
    }

    // 0x80AB2940: the six scalar seeds, in the original store order.
    write_f32(this + 0xF8, read_f32(W132_DAT_8042C1C0));
    write_f32(this + 0xEC, read_f32(W132_DAT_8042C1BC));
    write_f32(this + 0x114, read_f32(W132_DAT_8042C1B8));
    write_f32(this + 0x978, read_f32(W132_DAT_8042C1C0));
    write_f32(this + 0x960, read_f32(W132_DAT_8042C1B8));
    write_f32(this + 0x95C, read_f32(W132_DAT_80B2FB88));

    call1(W132_FN_8008C380, (this + 0x148) as u32);
    call1(W132_FN_80AB1A00, this as u32);
    if platform::read_u32(this + 0x988) == 1 {
        call3(W132_FN_80166340, (this + 0x794) as u32, 3, 0);
    }
}

/// Emits the 60-byte bubble billboard record with the small or large scale arm.
///
/// # Original
/// - Ghidra: `FUN_80a34f80` at `0x80A34F80` (348 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a34f80_FUN_80a34f80.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the emitter; `+0xAC..+0xB4` is the position, bit 8 of the word at
///   `+4` selects the arm and `+0x484` is the owning effect slot.
///
/// # Returns
/// The word returned by `0x800B8700` for the committed record.
///
/// # Side effects
/// Writes the 15-word record (type `0x1003`, position, the scale triplet and
/// eight zero words), commits it and registers the in-REL callback block.
///
/// # Safety
/// The effect slot at `+0x484` must be live.
///
/// # Confidence
/// high - both arms, every constant and both calls are literal; the small arm
/// is `(0.5, -14.0)` and the large arm `(0.9, -25.2)`.
pub unsafe fn fn_80a34f80(this: usize) -> u32 {
    let mut record = [0u32; 15];
    record[0] = 0x1003;
    record[1] = platform::read_u32(this + 0xAC);
    record[3] = platform::read_u32(this + 0xB4);

    let base_scale = read_f32(W132_DAT_80B2C0A4);
    let base_drop = read_f32(W132_DAT_80B2C0A0);
    let (scale, drop) = if (platform::read_u32(this + 4) >> 8) & 1 == 0 {
        (base_scale, base_drop)
    } else {
        let grow = read_f32(W132_DAT_80B2C08C);
        (base_scale * grow, base_drop * grow)
    };
    let y = read_f32(this + 0xB0) - drop;
    record[2] = y.to_bits();
    record[4] = scale.to_bits();
    record[5] = scale.to_bits();
    record[6] = scale.to_bits();
    let fill = platform::read_u32(W132_DAT_80B2C094);
    for slot in record.iter_mut().skip(7) {
        *slot = fill;
    }

    let result = call3(
        W132_FN_800B8700,
        (this + 0x484) as u32,
        record.as_ptr() as u32,
        1,
    );
    call4(
        W132_FN_802DCA98,
        record.as_ptr() as u32,
        W132_DAT_80A0B5A0,
        0x3C,
        1,
    );
    result
}

/// Binds the `env_underwater` / `wmy_ef_bubble` model pair and seeds the
/// emitter state block.
///
/// # Original
/// - Ghidra: `FUN_80a2fd40` at `0x80A2FD40` (340 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a2fd40_FUN_80a2fd40.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x524` the model holder, `+0x540` the loaded model,
///   `+0x544` the model record, `+0x6910` the twelve-word emitter block and
///   `+0x6940`/`+0x6944` the two node slots.
///
/// # Returns
/// `1` on the normal path.
///
/// # Side effects
/// Resets and fills the model holder, writes the 12 `-999999.0` sentinels,
/// releases the holder and dispatches the `+0x60` slot `+0x20`.
///
/// # Safety
/// The archive manager at `0x8042A038` and the actor's class vtable must be
/// live.
///
/// # Confidence
/// high - every string, offset, argument and the `off != 0` self-relative arm
/// are literal in the export.
pub unsafe fn fn_80a2fd40(this: usize) -> u32 {
    call1(W132_FN_8005F900, 0);

    call5(
        W132_FN_800690C0,
        (this + 0x524) as u32,
        0xFFFF_FFFF,
        platform::read_u32(W132_WORD_80377C48),
        0,
        0x20,
    );

    let model = call3(
        W132_FN_800DF180,
        platform::read_u32(W132_PTR_8042A038) + 4,
        W132_STR_ENV_UNDERWATER,
        W132_STR_G3D_ENV_UNDERWATER,
    );
    platform::write_u32(this + 0x540, model);

    let handle = call2(W132_FN_80239F20, (this + 0x540) as u32, W132_STR_WMY_EF_BUBBLE);
    call5(
        W132_FN_800099D0,
        (this + 0x544) as u32,
        (&handle as *const u32) as u32,
        0xFFFF_FFFF,
        0x84,
        (this + 0x524) as u32,
    );

    let mut node = call2(W132_FN_80239E30, (this + 0x540) as u32, W132_STR_EF_BUBBLE);
    let accessor = call2(
        W132_FN_8023B800,
        (&mut node as *mut u32) as u32,
        0,
    );
    // 0x80A2FDF0: the `+0x3C` word is a self-relative offset, not a null test.
    let offset = platform::read_u32(accessor as usize + 0x3C);
    let base = if offset != 0 {
        accessor.wrapping_add(offset)
    } else {
        0
    };
    let mut slot = base + 0x20;
    call3(
        W132_FN_8023D300,
        (&slot as *const u32) as u32,
        1,
        (this + 0x6940) as u32,
    );
    call3(
        W132_FN_8023D300,
        (&slot as *const u32) as u32,
        2,
        (this + 0x6944) as u32,
    );

    let sentinel = read_f32(W132_DAT_80B2BD54);
    for index in 0..12 {
        write_f32(this + 0x6910 + index * 4, sentinel);
    }

    call1(W132_FN_800690E0, (this + 0x524) as u32);
    w131_vt(this, 0x20);
    1
}

/// `lift` spawn initialiser: fills the extents, the state-4 scale block and the
/// two per-side callback words.
///
/// # Original
/// - Ghidra: `FUN_80a77a50` at `0x80A77A50` (340 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a77a50_FUN_80a77a50.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the spawned lift; `+0x88C` the state word, `+0x874` the side
///   index, `+0x744..+0x750` the four scale words, `+0x738`/`+0x73C` the two
///   callback words and `+0x754` the released holder.
///
/// # Side effects
/// Writes the orientation extents, the state-selected scale block, its
/// `+0x164..+0x170` copy and the two callback words, then calls `0x8008C3E0`,
/// `0x80A778F0` and `0x8007F900`.
///
/// # Safety
/// The actor and its `+0x148` slot must be live.
///
/// # Confidence
/// medium - every store and table index is literal; the two callback roles and
/// the `+0x738`/`+0x73C` pairing are inferred from the state entry that uses
/// them.
pub unsafe fn fn_80a77a50(this: usize) {
    let one = read_f32(W132_DAT_80B2DD80);
    write_f32(this + 0xDC, one);
    write_f32(this + 0xE0, one);
    write_f32(this + 0xE4, one);
    write_f32(this + 0xD0, read_f32(W132_DAT_80B2DD70));
    write_f32(this + 0xD4, read_f32(W132_DAT_80B2DD74));
    write_f32(this + 0xD8, read_f32(W132_DAT_80B2DD70));

    call3(
        W132_FN_8008C3E0,
        (this + 0x148) as u32,
        this as u32,
        W132_DAT_80B2DD4C as u32,
    );

    let state = platform::read_u32(this + 0x88C);
    if state == 4 {
        write_f32(this + 0x744, read_f32(W132_DAT_80B2DCFC));
        write_f32(this + 0x748, read_f32(W132_DAT_80B2DD78));
        write_f32(this + 0x74C, read_f32(W132_DAT_80B2DDB0));
        write_f32(this + 0x750, read_f32(W132_DAT_80B2DD78));
    } else {
        let small = read_f32(W132_DAT_80B2DD74);
        write_f32(this + 0x744, read_f32(W132_DAT_80B2DCEC));
        write_f32(this + 0x748, small);
        write_f32(this + 0x74C, small);
        write_f32(this + 0x750, small);
    }

    // 0x80A77AF8: the four-word scratch copy of the `+0x744` block.
    for index in 0..4 {
        let value = platform::read_u32(this + 0x744 + index * 4);
        platform::write_u32(this + 0x164 + index * 4, value);
    }

    write_f32(this + 0x838, one);
    write_f32(this + 0x83C, one);
    write_f32(this + 0x840, one);

    // 0x80A77B34: the side index is scaled by four and the state is re-read.
    let index = platform::read_u32(this + 0x874) as usize * 4;
    let (low_table, high_table) = if platform::read_u32(this + 0x88C) == 4 {
        (W132_TABLE_80B2DD30, W132_TABLE_80B2DD38)
    } else {
        (W132_TABLE_80B2DD20, W132_TABLE_80B2DD28)
    };
    platform::write_u32(this + 0x738, platform::read_u32(low_table + index));
    platform::write_u32(this + 0x73C, platform::read_u32(high_table + index));
    platform::write_u32(this + 0x740, 0);

    call1(W132_FN_80A778F0, this as u32);
    call1(W132_FN_8007F900, (this + 0x754) as u32);
}

/// Rebuilds the render matrix with `+12`/`-12` z translates around the Y, X
/// and Z rotations.
///
/// # Original
/// - Ghidra: `FUN_80b1d090` at `0x80B1D090` (328 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b1d090_FUN_80b1d090.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
