/// # Original
/// - Ghidra: `FUN_80a06480` at `0x80A06480` (40 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a06480_FUN_80a06480.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x115C` is the `s16` timer.
///
/// # Side effects
/// Returns when the timer is already negative; otherwise decrements it and
/// clamps to `0` once it passes `-1`.
///
/// # Safety
/// `this` must point at a writable actor.
///
/// # Confidence
/// high - the `s16` load, the two early returns and the clamp are literal.
pub unsafe fn fn_80a06480(this: usize) {
    let value = platform::read_u16(this + 0x115C) as i16;
    if value < 0 {
        return;
    }
    let left = value.wrapping_sub(1);
    platform::write_u16(this + 0x115C, left as u16);
    if left >= 0 {
        return;
    }
    platform::write_u16(this + 0x115C, 0);
}

/// Walks the `+0x30` owner chain until the owner's vtable slot 3 answers
/// non-zero, and returns the node that owns it.
///
/// # Original
/// - Ghidra: `FUN_80a07080` at `0x80A07080` (224 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a07080_FUN_80a07080.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the first node; each node stores the next owner word at `+0x30`.
///
/// # Returns
/// The node whose `+0x30` owner answered non-zero, or whatever the chain ends
/// on.
///
/// # Side effects
/// One vtable slot-`+0x0C` call per node; no local writes.
///
/// # Safety
/// Every `+0x30` word and its vtable must be readable and callable.
///
/// # Confidence
/// medium - the five unrolled tests and the tail recursion are literal; the
/// receiver is confirmed to be the `+0x30` object, but the slot-3 role is
/// inferred.
pub unsafe fn fn_80a07080(this: usize) -> usize {
    let mut node = this;
    loop {
        let owner = platform::read_u32(node + 0x30) as usize;
        let vtable = platform::read_u32(owner) as usize;
        if call1(platform::read_u32(vtable + 0x0C) as usize, owner as u32) != 0 {
            return node;
        }
        // 0x80A070B0: the recursion argument is the next `+0x30` word.
        node = platform::read_u32(node + 0x30) as usize;
    }
}

/// Compares the `:`-suffixed tail of a name against the object's own
/// `:`-suffixed name.
///
/// # Original
/// - Ghidra: `FUN_80a07160` at `0x80A07160` (136 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a07160_FUN_80a07160.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the object; its vtable slot `+0x20` returns a name string.
/// - `name`: the candidate string.
///
/// # Returns
/// `true` when both strings have the same tail after the first `:`.
///
/// # Side effects
/// Two `0x802E1C40` searches and one `0x802E1AB4` comparison.
///
/// # Safety
/// Both strings must be NUL-terminated and readable.
///
/// # Confidence
/// medium - every search, offset and comparison is literal; the string helpers'
/// exact names are inferred from the `':'` operand and the `== 0` result test.
pub unsafe fn fn_80a07160(this: usize, name: usize) -> bool {
    let mut suffix = name;
    let found = call2(W132_FN_802E1C40, name as u32, 0x3A);
    if found != 0 {
        suffix = (found as usize).wrapping_add(1);
    }

    let vtable = platform::read_u32(this) as usize;
    let own_name = call1(platform::read_u32(vtable + 0x20) as usize, this as u32);
    let own_tail = call2(W132_FN_802E1C40, own_name, 0x3A);
    // observed: the original advances the result without a null test.
    call2(
        W132_FN_802E1AB4,
        own_tail.wrapping_add(1),
        suffix as u32,
    ) == 0
}

/// Runs the `+0x24` vtable step over the `+0x544` holder chain.
///
/// # Original
/// - Ghidra: `FUN_80a0ffd0` at `0x80A0FFD0` (112 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a0ffd0_FUN_80a0ffd0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the chain owner; `+0x540` is the last holder index and `+0x544`
///   the first holder. Each holder links the next at `+0x238`.
///
/// # Side effects
/// Calls slot `+0x24` once per holder; nothing local is written.
///
/// # Safety
/// Every linked holder and its vtable must be live.
///
/// # Confidence
/// medium - the loop bound `+0x540 + 1`, the link word and the slot are
/// literal; the slot's role is inferred.
pub unsafe fn fn_80a0ffd0(this: usize) {
    let count = platform::read_u32(this + 0x540) as i32 + 1;
    let mut holder = this + 0x544;
    for _ in 0..count {
        let vtable = platform::read_u32(holder) as usize;
        call1(platform::read_u32(vtable + 0x24) as usize, holder as u32);
        holder = platform::read_u32(holder + 0x238) as usize;
    }
}

/// Applies the five per-holder scales to the `+0x544` holder chain.
///
/// # Original
/// - Ghidra: `FUN_80a0f8b0` at `0x80A0F8B0` (192 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a0f8b0_FUN_80a0f8b0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the chain owner; `+0x540` is the last holder index, `+0x544` the
///   first holder and `+0x524` the shared model owner.
///
/// # Side effects
/// Calls slot `+0x0C` and the scale setter `0x800B6A70` once per holder.
///
/// # Safety
/// Every linked holder and its vtable must be live.
///
/// # Confidence
/// medium - the five constant scales, the slot call, the `f1` scale store and
/// the `+0x238` link are literal; the chain slot roles are inferred.
pub unsafe fn fn_80a0f8b0(this: usize) {
    // observed: five stack floats; the loop indexes past them when the chain is
    // longer, exactly as the original does.
    let scales = [
        read_f32(W132_DAT_80B2ADA0),
        read_f32(W132_DAT_80B2ADA4),
        read_f32(W132_DAT_80B2ADA8),
        read_f32(W132_DAT_80B2ADAC),
        read_f32(W132_DAT_80B2ADB0),
    ];
    let count = platform::read_u32(this + 0x540) as i32 + 1;
    let mut holder = this + 0x544;
    for index in 0..count {
        let vtable = platform::read_u32(holder) as usize;
        call2(
            platform::read_u32(vtable + 0x0C) as usize,
            holder as u32,
            (this + 0x524) as u32,
        );
        let scale = *scales.as_ptr().offset(index as isize);
        w132_call_fu(W132_FN_800B6A70, scale, holder as u32);
        holder = platform::read_u32(holder + 0x238) as usize;
    }
}

/// Selects the low or high speed from bit 0 of `+4` and publishes it to the two
/// in-REL globals before the spawn step.
///
/// # Original
/// - Ghidra: `FUN_80a0f970` at `0x80A0F970` (156 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a0f970_FUN_80a0f970.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; bit 0 of the word at `+4` selects `1.5` over `1.0`, and
///   `+0x394` is the owner object dispatched through slot `+0x10`.
///
/// # Side effects
/// Writes `0x80B35230` and its negation to `0x80B35234`, dispatches the owner's
/// slot `+0x10`, calls `0x80A10630` and `0x80064F50(this, 0)`.
///
/// # Safety
/// The `+0x394` object and its vtable must be live.
///
/// # Confidence
/// medium - the selector, both constants, both global stores and all three
/// calls are literal; the globals' consumers are outside this body.
pub unsafe fn fn_80a0f970(this: usize) -> u32 {
    let selected = if platform::read_u32(this + 4) & 1 != 0 {
        read_f32(W132_DAT_80B2AD98)
    } else {
        read_f32(W132_DAT_80B2AD94)
    };
    write_f32(W132_DAT_80B35230, selected);
    write_f32(W132_DAT_80B35234, -selected);

    w131_vt(this + 0x394, 0x10);
    call1(W132_FN_80A10630, this as u32);
    call2(W132_FN_80064F50, this as u32, 0);
    1
}

/// Resets the `0x8016A960` holder, runs the three binders and finishes the
/// holder.
///
/// # Original
/// - Ghidra: `FUN_80a0f5a0` at `0x80A0F5A0` (104 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a0f5a0_FUN_80a0f5a0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x524` is the holder reset and finished here.
///
/// # Side effects
/// Calls `0x8016A960(this+0x524, -1, *(0x80377C48), 0, 0x20, 0)`, then
/// `0x80A0F610`, `0x80A0F8B0`, `0x80A10170` and `0x8016A9B0`.
///
/// # Safety
/// The holder and all four callees must be live.
///
/// # Confidence
/// high - the six push registers, the three binder calls and the holder finish
/// are literal.
pub unsafe fn fn_80a0f5a0(this: usize) {
    call6(
        W132_FN_8016A960,
        (this + 0x524) as u32,
        0xFFFF_FFFF,
        platform::read_u32(W132_WORD_80377C48),
        0,
        0x20,
        0,
    );
    call1(W132_FN_80A0F610, this as u32);
    call1(W132_FN_80A0F8B0, this as u32);
    call1(W132_FN_80A10170, this as u32);
    call1(W132_FN_8016A9B0, (this + 0x524) as u32);
}

/// Spawn-time store block of the `0x80A0F490` actor: extents, scale pairs and
/// the state token dispatch.
///
/// # Original
/// - Ghidra: `FUN_80a0f490` at `0x80A0F490` (264 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a0f490_FUN_80a0f490.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x4FC` the flag word, `+0x114`/`+0xF8` the two scalar
///   fields, `+0x318..+0x324` and `+0x338..+0x344` the two four-float blocks,
///   `+0xD0..+0xD8` the extent triple and `+0x348`/`+0x540` the two state words.
///
/// # Side effects
/// Writes the whole block, ORs `0x01000000` into `+0x4FC`, runs `0x80A0F5A0`,
/// `0x80A10590` and `0x80A10220`, and dispatches the `+0xD4` class slot with
/// `0x80B6EF18`.
///
/// # Safety
/// The actor and its `+0x60` vtable must be live.
///
/// # Confidence
/// high - every constant, addend and store order is literal; the two `main.dol`
/// float addends are read at run time.
pub unsafe fn fn_80a0f490(this: usize) -> u32 {
    let page = W132_DAT_80B2AD90;
    let first_z = read_f32(page + 0x94) + read_f32(W132_DAT_8042BB0C);
    let second_z = read_f32(page + 0x98) + read_f32(W132_DAT_8042BB08);

    platform::write_u8(this + 0x348, 1);
    platform::write_u32(this + 0x540, 4);
    write_f32(this + 0x114, read_f32(W132_DAT_80B2AE1C));
    write_f32(this + 0xF8, read_f32(W132_DAT_80B2AE20));
    // 0x80A0F4EC `oris r0,r0,0x100` -> bit 24.
    platform::write_u32(this + 0x4FC, platform::read_u32(this + 0x4FC) | 0x0100_0000);
    write_f32(this + 0x320, read_f32(page));
    write_f32(this + 0x324, read_f32(W132_DAT_80B2AE2C));
    write_f32(this + 0x318, read_f32(W132_DAT_80B2AE30));
    write_f32(this + 0x31C, read_f32(W132_DAT_80B2AE30));
    write_f32(this + 0x338, first_z);
    write_f32(this + 0x33C, first_z);
    write_f32(this + 0x340, second_z);
    write_f32(this + 0x344, second_z);

    call1(W132_FN_80A0F5A0, this as u32);
    call1(W132_FN_80A10590, this as u32);
    call1(W132_FN_80A10220, this as u32);

    write_f32(this + 0xD0, read_f32(page));
    write_f32(this + 0xD4, read_f32(W132_DAT_80B2AE2C));
    write_f32(this + 0xD8, read_f32(page));
    w130_state_call(this, W132_TOKEN_80B6EF18);
    1
}

/// Binds the `3` entry clip and seeds the `+0x115C` state block of the
/// `0x80A06760` actor.
///
/// # Original
/// - Ghidra: `FUN_80a06b00` at `0x80A06B00` (124 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a06b00_FUN_80a06b00.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x5AC` is converted to the `+0x115E` halfword and
///   `+0x115C`/`+0x1162`/`+0x1154`/`+0x1158` are the state words.
///
/// # Side effects
/// Calls `0x80A61A80(0.0, 1.0, this, 3, 1)` and writes five fields.
///
/// # Safety
/// The actor must be a live `0x80A61A80` receiver.
///
/// # Confidence
/// high - the `fctiwz` + `slwi 8` conversion, the `0xFFFF` store and the four
/// constants are literal.
pub unsafe fn fn_80a06b00(this: usize) {
    fn_80a61a80(
        read_f32(W132_DAT_80B2D384) as f64,
        read_f32(W132_DAT_80B2D380) as f64,
        this,
        3,
        1,
    );

    platform::write_u16(this + 0x115C, 0xFFFF);
    platform::write_u8(this + 0x1162, 0);
    // 0x80A06B40 `fctiwz` then `slwi r0,r3,8`.
    let shifted = (read_f32(this + 0x5AC) as i32) << 8;
    platform::write_u16(this + 0x115E, shifted as u16);
    write_f32(this + 0x1154, read_f32(W132_DAT_80B2AAA8));
    write_f32(this + 0x1158, read_f32(W132_DAT_80B2AAA8));
}

/// Dispatches the `+0xD4` class slot of every live occupant of the four
/// `+0x738` slots.
///
/// # Original
/// - Ghidra: `FUN_80a06760` at `0x80A06760` (160 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a06760_FUN_80a06760.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the owner; `+0x738 + i*4` holds four occupant words and `+0x1160`
///   the byte cleared at the end.
///
/// # Side effects
/// For each non-zero occupant that `0x80162D00` resolves and whose `+0x5BC`
/// byte is set, dispatches its `+0xD4` slot with `0x80B72490`; clears `+0x1160`.
///
/// # Safety
/// Every resolved occupant and its vtable must be live.
///
/// # Confidence
/// high - the loop bound, the occupant load, the `+0x5BC` gate, the dispatch
/// and the trailing byte clear are literal (the receiver is the slot word).
pub unsafe fn fn_80a06760(this: usize) {
    for index in 0..4 {
        let occupant = platform::read_u32(this + 0x738 + index * 4);
        if occupant == 0 {
            continue;
        }
        let object = call1(W132_FN_80162D00, occupant);
        if object == 0 {
            continue;
        }
        let object = object as usize;
        if platform::read_u8(object + 0x5BC) == 0 {
            continue;
        }
        w130_state_call(object, W132_TOKEN_80B72490);
    }
    platform::write_u8(this + 0x1160, 0);
}

/// Releases every live occupant of the four `+0x738` slots.
///
/// # Original
/// - Ghidra: `FUN_80a06800` at `0x80A06800` (132 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a06800_FUN_80a06800.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
