// --- Section-local adapters -------------------------------------------------

/// Calls one vtable slot of the object whose *vtable word is stored at*
/// `receiver` (so the pattern is `(*(u32 *)receiver)->slot`), with `r3 =
/// receiver`, and returns the word result.
#[inline]
unsafe fn w133_vt0_ret(receiver: usize, slot: usize) -> u32 {
    let vtable = platform::read_u32(receiver) as usize;
    call1(platform::read_u32(vtable + slot) as usize, receiver as u32)
}

/// Calls one vtable slot of the object whose vtable word is stored at
/// `receiver`, with `r3 = receiver` and one argument, returning the word
/// result.
#[inline]
unsafe fn w133_vt1_ret(receiver: usize, slot: usize, a: u32) -> u32 {
    let vtable = platform::read_u32(receiver) as usize;
    call2(platform::read_u32(vtable + slot) as usize, receiver as u32, a)
}

/// Initialises the short or long `lift_trampoline` variant and installs its
/// layer animator.
///
/// # Original
/// - Ghidra: `FUN_80ab9af0` at `0x80AB9AF0` (284 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80ab9af0_FUN_80ab9af0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the lift actor; bit 12 of the flag word at `+4` selects the
///   `lift_trampoline` or `lift_trampoline_long` record, the nibble at bits
///   8-11 seeds the `+0x53C` reciprocal.
///
/// # Returns
/// `1` on every path.
///
/// # Side effects
/// Clears `+0xB4`, binds the 12-byte record through `0x80AB9C10`, writes the
/// `+0x318..+0x324` quad, the six `+0xD0..+0xE4` extent words and `+0x53C`,
/// then installs and releases the `+0x458` layer block.
///
/// # Safety
/// The actor, its `+0x458` layer slot and the record selected by `+4` must be
/// live; `0x80AB9C10` dereferences the record strings.
///
/// # Confidence
/// high - every store, the bit-12/bit-8 extraction, the `1/240`-style
/// reciprocal and all three calls are literal in the export and in the raw
/// words (the four `0x8007FA40` floats are `lfs` loads).
pub unsafe fn fn_80ab9af0(this: usize) -> u32 {
    write_f32(this + 0xB4, read_f32(W133_DAT_80B2FF50));

    // observed: `rlwinm r0,r0,20,31,31` extracts bit 12 of the flag word.
    let entry = W133_TABLE_80B2FF20 + ((platform::read_u32(this + 4) >> 12) & 1) as usize * 0x0C;
    call2(W133_FN_80AB9C10, this as u32, entry as u32);

    let scale = read_f32(entry + 8); // 64.0 or 128.0
    let zero = read_f32(W133_DAT_80B2FF50);
    let one = read_f32(W133_DAT_80B2FF64);

    // observed: the store order is +0x320, +0x324, +0x318, +0x31C.
    platform::write_u32(this + 0x320, platform::read_u32(W133_DAT_80B2FF58));
    write_f32(this + 0x324, zero);
    platform::write_u32(this + 0x318, platform::read_u32(W133_DAT_80B2FF5C));
    platform::write_u32(this + 0x31C, platform::read_u32(W133_DAT_80B2FF60));
    write_f32(this + 0xD0, read_f32(W133_DAT_80B2FF54) * scale);
    write_f32(this + 0xD4, zero);
    write_f32(this + 0xD8, zero);
    write_f32(this + 0xDC, one);
    write_f32(this + 0xE0, one);
    write_f32(this + 0xE4, one);

    // observed: `rlwinm. r3,r0,24,28,31` is `(flag >> 8) & 0xF`.
    let nibble = (platform::read_u32(this + 4) >> 8) & 0xF;
    if nibble == 0 {
        write_f32(this + 0x53C, read_f32(W133_DAT_80B2FF54));
    } else {
        write_f32(this + 0x53C, one / (nibble as f32));
    }

    call12_f64x4(
        W133_FN_8007FA40,
        read_f32(W133_DAT_80B2FF50) as f64,
        read_f32(W133_DAT_80B2FF68) as f64,
        scale as f64,
        read_f32(W133_DAT_80B2FF6C) as f64,
        (this + 0x458) as u32,
        this as u32,
        0,
        0,
        0,
        3,
        0,
        0,
    );
    call1(W132_FN_8007F900, (this + 0x458) as u32);
    1
}

