        write_f32(W133_BSS_80B71E98 + 4, read_f32(W133_DAT_80B2D27C));
        write_f32(W133_BSS_80B71E98 + 8, read_f32(W133_DAT_80B2D280));
        write_f32(W133_BSS_80B71E98 + 12, read_f32(W133_DAT_80B2D27C));
