    let mut clip = [0u32; 1];
    clip[0] = call2(W132_FN_8023A0B0, (this + 0x540) as u32, W133_STR_RUN);

    call4(
        W132_FN_801651F0,
        (this + 0x584) as u32,
        (this + 0x544) as u32,
        clip.as_mut_ptr() as u32,
        0,
    );
    call2_f64(
        W132_FN_801680E0,
        read_f32(W133_DAT_80B2C090) as f64,
        (this + 0x584) as u32,
    );
    call3_f64(
        W132_FN_80169F80,
        read_f32(W133_DAT_80B2C090) as f64,
        (this + 0x544) as u32,
        (this + 0x584) as u32,
    );

    let jitter = call1(W133_FN_800B2ED0, 10);
    // observed: `fctiwz` of `+0x5AC`, then the signed divide-by-ten magic
    // (`mulhw 0x66666667` / `srawi 2` / sign fix) which truncates toward zero.
    let frames = read_f32(this + 0x5AC) as i32;
    let quotient = frames / 10;
