    record[1] = platform::read_u32(this + 0xB0);
    record[2] = platform::read_u32(this + 0xB4);
    record[3] = ((platform::read_u8(this + 0x694) as u32) << 24) | (state >> 8);
    record[4] = (state & 0xFF) << 24;
