    if mode == 0 {
        return;
    }

    if mode == 1 {
        w130_state_call(this, W133_WORD_80352AF4 as u32);
        platform::write_u8(this + 0x68A, 2);
        platform::write_u8(this + 0x689, 0);
    } else {
        w130_state_call(this, W133_WORD_80352B34 as u32);
        platform::write_u8(this + 0x68A, 1);
        platform::write_u8(this + 0x689, 1);
    }

    call5(
        W132_FN_8016C890,
        W133_STR_WM_EN_BLOCKCLOUD,
        0,
        (this + 0x794) as u32,
        0,
        0,
    );

    let mut sound = [0u32; 3];
    call2(W132_FN_8006A4B0, sound.as_mut_ptr() as u32, (this + 0xAC) as u32);
    call4(
        W133_FN_80198C30,
        platform::read_u32(W133_PTR_80429D60),
        0x27A,
        sound.as_mut_ptr() as u32,
        0,
    );

    let player_byte =
        platform::read_u8(platform::read_u32(W133_PTR_8042A1C8) as usize + 0x120E) as u32;
    call5(
        W133_FN_800D0470,
        platform::read_u32(W133_PTR_80429FC8),
        (this + 0x788) as u32,
        player_byte,
        0,
        platform::read_u32(this + 0x7A8),
    );
    platform::write_u32(this + 0x7AC, 4);

    let mut position = [0f32; 3];
