        platform::write_u8(this + 0x391, other ^ 1);
        write_f32(this + 0xB4, z);
        platform::write_u8(this + 0x1E7, platform::read_u8(W134_TABLE_8042BB18 + (other ^ 1) as usize));
        platform::write_u8(this + 0x2D1, platform::read_u8(W134_TABLE_8042BB18 + (other ^ 1) as usize));
