/// Probes the body, then either retires the actor or decrements `+0x6C0` and
/// runs the `0x80A2D460` state tail. Updates the path when `+0x6C4 != 0`, runs
/// the post-step and clears `+0x366`.
///
/// # Safety
/// The actor, its body object and the path helpers must be live.
///
/// # Confidence
/// high - the `lhz`/`sth` reload-decrement, both guards, the five calls and the
/// final byte store are literal.
pub unsafe fn fn_80a2d660(this: usize) -> u32 {
    let _ = call2(W136_FN_8006EF40, (this + 0x1EC) as u32, 0);

    let count = platform::read_u16(this + 0x6C0);
    if count == 0 {
        let _ = call1(W136_FN_80162510, this as u32);
    } else {
        platform::write_u16(this + 0x6C0, count.wrapping_sub(1));
        let _ = call1(W136_FN_80A2D460, this as u32);
    }

    if platform::read_u16(this + 0x6C4) != 0 {
        let _ = call1(W136_FN_8007FDA0, (this + 0x534) as u32);
    }

    let _ = call1(W136_FN_800217B0, this as u32);
    platform::write_u8(this + 0x366, 0);
    1
}

