/// middle band ends in a `void` tail call, so its return value is the callee's
/// leftover `r3`; the port takes the specification's `return 2;` reading.
pub unsafe fn fn_80a6efb0(this: usize) -> i32 {
    let delta = read_f32(this + 0xB0) - read_f32(this + 0x850);
    if delta < read_f32(W137_DAT_80B2DA60) {
        platform::write_u32(this + 0x860, 0);
        return 1;
    }
    if delta >= read_f32(W137_DAT_80B2DA60) && delta < read_f32(W137_DAT_80B2DA64) {
        platform::write_u32(this + 0x860, 1);
        let _ = call1(W137_FN_800B2EE0, 2);
        return 2;
    }
    platform::write_u32(this + 0x860, 2);
    0
}

/// Converts the `s16` angle at `+0x102` into the two speed fields.
///
/// # Original
/// - Ghidra: `FUN_80ab1890` at `0x80AB1890` (104 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80ab1890_FUN_80ab1890.c`
