    // observed: `rlwinm r22,r4,1,0,30` scales the variation into a byte offset.
    let tile_offset = (((variation as u32) << 1) & 0x7FFF_FFFE) as usize;
    let tile = platform::read_u32(W137_TABLE_80B32C58 + tile_offset);
    let scene = platform::read_u32(W137_PTR_80429DD0);

    let mut row = 0;
