///
/// # Returns
/// The callee's arrival flag: `1` when `+0x102` reached the target, else `0`.
///
/// # Side effects
/// Tail-branches to `0x8015F4F0(this + 0x102, target, 0x400)` on both paths.
///
/// # Safety
/// The actor must be live. The index is not bounds-checked; rows `>= 2` land
/// in the following float block, exactly as the original reads them.
///
/// # Confidence
/// medium - all seventeen words and both literals are decoded from the ELF and
/// the tail target is the import addend `0x8015F4F0`; the meaning of `+0x634`
/// (row index versus a count) is inferred from the `rlwinm r6,r4,2,0,29`
/// scaling and the two populated rows.
pub unsafe fn fn_80a5d9d0(this: usize) -> u32 {
    let index = platform::read_u32(this + 0x634);
    if index == 0 {
        // observed: `li r4,0` / `li r5,0x400` / `addi r3,r3,0x102`.
        return call3(W140_FN_8015F4F0, (this + 0x102) as u32, 0, 0x400);
    }
    let side = platform::read_u8(this + 0x348) as usize;
    let target =
        read_i16(W140_TABLE_80B2D190 + index as usize * 4 + side * 2) as i32;
    call3(
        W140_FN_8015F4F0,
        (this + 0x102) as u32,
        target as u32,
        0x400,
    )
}

