/// Chases 16-byte waypoint records with a cached offset vector.
///
/// The record is `rec_base + 16 * (waypoint_count + +0x3D4)`, where `rec_base`
/// comes from the active player's 944-byte record. The x/y delta to the
/// waypoint is cached at `+0x3F8..+0x400` whenever either component leaves the
/// `Ã‚±0.01` band; inside the band the cached vector is reused. The vector is
/// normalised, turned into a smoothed pitch/yaw pair and then into a step of
/// `+0xE8` along `(cos(pitch)*sin(yaw), sin(pitch))`, with the raw waypoint
/// coordinate snapping the position back inside `Ã‚±0.1`.
///
/// # Original
/// - Ghidra: `FUN_80aedd40` at `0x80AEDD40` (1208 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80aedd40_FUN_80aedd40.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x04` is the flag bitfield (`>>20 & 0xF` actor index,
///   `>>19 & 1` instant-angle, `>>16 & 3` arrival variant, `>>8 & 0xF` restart
///   index), `+0xAC..+0xB4` the position, `+0xE8` the speed, `+0x3D0` the
///   per-frame waypoint advance, `+0x3D4` the waypoint index, `+0x3D8` the last
///   arrival word, `+0x3E0` the "arrived once" latch, `+0x3E4`/`+0x3E6` the two
///   smoothed angles and `+0x394` the vtable receiver.
///
/// # Side effects
/// Writes the position, the smoothed angles, the cache vector, and on arrival
/// the latch, the waypoint index and an event through vtable `+0x18` with one of
/// the `0x80B77650`/`0x80B776D0`/`0x80B77710` payloads. Calls the ledgered
/// `0x8015F140`, `0x8015F200`, `0x80170980`, `0x802BE470` and `0x801611C0`.
///
/// # Safety
/// The actor, the active player record and the waypoint table must be mapped;
/// `+0x394` must hold a valid vtable while the actor runs.
///
/// # Confidence
/// high - all 301 instructions were decoded from the ELF and agree with the
/// export line for line. The export's `in_f31`/`unaff_GQR*` names are the
/// prologue spill and the pinned `GQR3`.
pub unsafe fn fn_80aedd40(this: usize) {
    let flags = platform::read_u32(this + 4);
    let obj = w141_object_by_index((flags >> 20) & 0xF);

    // observed: 944-byte (`0x3B0`) per-player record; a zero `+0x2C` word
    // zeroes the table pointer, after which the shipped code reads `0x3C`.
    let player_table = platform::read_u32(W141_PTR_8043A1C8);
    let pindex = platform::read_u8(player_table as usize + 0x120E) as u32;
    let rec_tbl = platform::read_u32(W141_PTR_80439E98).wrapping_add(944u32.wrapping_mul(pindex));
    let rec_tbl = if platform::read_u32(rec_tbl as usize + 0x2C) == 0 {
        0usize
    } else {
        rec_tbl as usize
    };
    let count = platform::read_u16(obj + 2) as u32;
    let index = platform::read_u32(this + 0x3D4);
    let rec = platform::read_u32(rec_tbl + 0x3C)
        .wrapping_add(16u32.wrapping_mul(count.wrapping_add(index))) as usize;

    // observed: `lhax` + the `2^52 + 2^31` bias -> the signed halfword as `f32`;
    // the second halfword is negated before the conversion.
    let way_x = read_i16(rec) as f32;
    let way_y = -(read_i16(rec + 2) as f32);

    let dx = way_x - read_f32(this + 0xAC);
    let dy = way_y - read_f32(this + 0xB0);

    let mut v = [dx, dy, 0.0f32];
    // observed: the four `fcmpo` guards - write the cache unless |dx| and |dy|
    // are both below 0.01 (`0x80B3121C` / `0x80B31220`).
    if dx <= -0.01 || dx >= 0.01 || dy <= -0.01 || dy >= 0.01 {
        write_f32(this + 0x3F8, dx);
        write_f32(this + 0x3FC, dy);
        write_f32(this + 0x400, 0.0);
    } else {
        v[0] = read_f32(this + 0x3F8);
        v[1] = read_f32(this + 0x3FC);
        v[2] = read_f32(this + 0x400);
    }
    w141_normalize3(v.as_mut_ptr());

    let horizontal = w141_sqrtf(v[0] * v[0] + v[2] * v[2]);
    let pitch = w141_angle16(v[1] as f64, horizontal as f64);
    let yaw = w141_angle16(v[0] as f64, v[2] as f64);

    if (flags >> 19) & 1 == 1 {
        platform::write_u16(this + 0x3E4, pitch as u16);
        platform::write_u16(this + 0x3E6, yaw as u16);
        platform::write_u16(this + 0x3E8, 0);
    } else {
        let _ = w141_step_angle((this + 0x3E4) as u32, pitch as i32, 1, 100, 100);
        let _ = w141_step_angle((this + 0x3E6) as u32, yaw as i32, 1, 100, 100);
    }

    // observed: the sinusoidal step is rebuilt from the smoothed angles; the
    // 1/256 (`0x80B31224`) scale is applied before each `sin`/`cos`.
    let cos_pitch = w141_cos16(read_i16(this + 0x3E4) as u16 as f32 * (1.0 / 256.0));
    let sin_yaw = w141_sin16(read_i16(this + 0x3E6) as u16 as f32 * (1.0 / 256.0));
    let sin_pitch = w141_sin16(read_i16(this + 0x3E4) as u16 as f32 * (1.0 / 256.0));

    // observed: `0x8015F140(this+0xE8, rec+4, 1.0, rec+8, 1.0e-4)`.
    let speed_target = read_f32(rec + 4);
    let speed_deadband = read_f32(rec + 8);
    let _ = w141_step_f32(
        (this + 0xE8) as u32,
        speed_target,
        1.0,
        speed_deadband,
        1.0e-4,
    );

    let speed = read_f32(this + 0xE8);
    let px = read_f32(this + 0xAC) + cos_pitch * sin_yaw * speed;
    let py = read_f32(this + 0xB0) + sin_pitch * speed;
    write_f32(this + 0xAC, px);
    write_f32(this + 0xB0, py);
    write_f32(this + 0xB4, 0.0);

    // observed: `0x80B3122C` = 0.1 margin on both raw waypoint coordinates.
    if px < way_x + 0.1 && way_x - 0.1 < px {
        write_f32(this + 0xAC, way_x);
    }
    if py < way_y + 0.1 && way_y - 0.1 < py {
        write_f32(this + 0xB0, way_y);
    }

    // observed: the arrival test is `(d >= 0 && way <= pos) || (d <= 0 && pos <= way)`
    // on both axes, built from `fcmpu` + `cror 2,1,2` / `cror 2,0,2`.
    let cx = read_f32(this + 0xAC);
    let cy = read_f32(this + 0xB0);
    let inside_x = (v[0] >= 0.0 && way_x <= cx) || (v[0] <= 0.0 && cx <= way_x);
    let inside_y = (v[1] >= 0.0 && way_y <= cy) || (v[1] <= 0.0 && cy <= way_y);
    if inside_x && inside_y {
        if platform::read_u32(this + 0x3E0) != 0 {
            let word = read_i16(rec + 0xC);
            platform::write_u16(this + 0x3D8, word as u16);
            if word != 0 {
                w141_vcall((this + 0x394) as u32, 0x18, W141_MSG_80B77650);
            }
        }
        platform::write_u32(this + 0x3E0, 1);

        let mut next = platform::read_u32(this + 0x3D4)
            .wrapping_add(platform::read_u32(this + 0x3D0));
        if platform::read_u16(obj + 4) as u32 <= next {
            // observed: `rlwinm r0,0x04,16,30,31` keeps `(flags >> 16) & 3`.
            match (flags >> 16) & 3 {
                0 => w141_vcall((this + 0x394) as u32, 0x18, W141_MSG_80B776D0),
                1 => next = (flags >> 8) & 0xF,
                2 => w141_vcall((this + 0x394) as u32, 0x18, W141_MSG_80B77710),
                _ => {}
            }
        }
        platform::write_u32(this + 0x3D4, next);
    }
}

/// Rank-3 sibling of [`fn_80aedd40`]: the same waypoint chase over the `+0x670`
/// state block.
///
/// The differences from rank 2 are exact and all recorded at the call sites:
/// the index is `+0x670`, the advance `+0x66C`, the smoothed angles
/// `+0x674`/`+0x676` (with `+0x678` zeroed on the instant path), the cache
/// `+0x688..+0x690`, the `+0x38F` byte forces `+0xB4 = 0.0`, the vtable is
/// `this + 0x60` with slot `+0xD4`, and there is **no** `+0x3E0` arrival latch
/// and no `rec + 0xC` test - the `0x80B77790` payload belongs to the variant-`0`
/// arrival branch instead.
///
/// # Original
/// - Ghidra: `FUN_80aef130` at `0x80AEF130` (1180 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80aef130_FUN_80aef130.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; the flag layout is identical to [`fn_80aedd40`].
///
/// # Side effects
/// Writes the position and angles, the `+0x688` cache vector and, on arrival,
/// the waypoint index plus a vtable `+0xD4` event with payload
/// `0x80B77790` or `0x80B777D0`.
///
/// # Safety
/// Same requirements as [`fn_80aedd40`]; `+0x60` must hold a valid vtable.
///
/// # Confidence
/// high - the body decodes end-to-end and every delta from rank 2 is confirmed
/// in the words (the arrival compares use `fcmpo`, the position test does not).
pub unsafe fn fn_80aef130(this: usize) {
    let flags = platform::read_u32(this + 4);
    let obj = w141_object_by_index((flags >> 20) & 0xF);

    let player_table = platform::read_u32(W141_PTR_8043A1C8);
    let pindex = platform::read_u8(player_table as usize + 0x120E) as u32;
    let rec_tbl = platform::read_u32(W141_PTR_80439E98).wrapping_add(944u32.wrapping_mul(pindex));
    let rec_tbl = if platform::read_u32(rec_tbl as usize + 0x2C) == 0 {
        0usize
    } else {
        rec_tbl as usize
    };
    let count = platform::read_u16(obj + 2) as u32;
    let index = platform::read_u32(this + 0x670);
    let rec = platform::read_u32(rec_tbl + 0x3C)
        .wrapping_add(16u32.wrapping_mul(count.wrapping_add(index))) as usize;

    let way_x = read_i16(rec) as f32;
    let way_y = -(read_i16(rec + 2) as f32);

    let dx = way_x - read_f32(this + 0xAC);
    let dy = way_y - read_f32(this + 0xB0);

    // observed: `0x80B31258` is a `0.0` slot used as the third component.
    let mut v = [dx, dy, 0.0f32];
    if dx <= -0.01 || dx >= 0.01 || dy <= -0.01 || dy >= 0.01 {
        write_f32(this + 0x688, dx);
        write_f32(this + 0x68C, dy);
        write_f32(this + 0x690, 0.0);
    } else {
        v[0] = read_f32(this + 0x688);
        v[1] = read_f32(this + 0x68C);
        v[2] = read_f32(this + 0x690);
    }
    w141_normalize3(v.as_mut_ptr());

    let horizontal = w141_sqrtf(v[0] * v[0] + v[2] * v[2]);
    let pitch = w141_angle16(v[1] as f64, horizontal as f64);
    let yaw = w141_angle16(v[0] as f64, v[2] as f64);

    if (flags >> 19) & 1 == 1 {
        platform::write_u16(this + 0x674, pitch as u16);
        platform::write_u16(this + 0x676, yaw as u16);
        platform::write_u16(this + 0x678, 0);
    } else {
        let _ = w141_step_angle((this + 0x674) as u32, pitch as i32, 1, 100, 100);
        let _ = w141_step_angle((this + 0x676) as u32, yaw as i32, 1, 100, 100);
    }

    let cos_pitch = w141_cos16(read_i16(this + 0x674) as u16 as f32 * (1.0 / 256.0));
    let sin_yaw = w141_sin16(read_i16(this + 0x676) as u16 as f32 * (1.0 / 256.0));
    let sin_pitch = w141_sin16(read_i16(this + 0x674) as u16 as f32 * (1.0 / 256.0));

    let speed_target = read_f32(rec + 4);
    let speed_deadband = read_f32(rec + 8);
    let _ = w141_step_f32(
        (this + 0xE8) as u32,
        speed_target,
        1.0,
        speed_deadband,
        1.0e-4,
    );

    let speed = read_f32(this + 0xE8);
    let px = read_f32(this + 0xAC) + cos_pitch * sin_yaw * speed;
    let py = read_f32(this + 0xB0) + sin_pitch * speed;
    write_f32(this + 0xAC, px);
    write_f32(this + 0xB0, py);
    if platform::read_u8(this + 0x38F) == 0 {
        write_f32(this + 0xB4, 0.0);
    }

    if px < way_x + 0.1 && way_x - 0.1 < px {
        write_f32(this + 0xAC, way_x);
    }
    if py < way_y + 0.1 && way_y - 0.1 < py {
        write_f32(this + 0xB0, way_y);
    }

    let cx = read_f32(this + 0xAC);
    let cy = read_f32(this + 0xB0);
    let inside_x = (v[0] >= 0.0 && way_x <= cx) || (v[0] <= 0.0 && cx <= way_x);
    let inside_y = (v[1] >= 0.0 && way_y <= cy) || (v[1] <= 0.0 && cy <= way_y);
    if inside_x && inside_y {
        let mut next = platform::read_u32(this + 0x670)
            .wrapping_add(platform::read_u32(this + 0x66C));
        if platform::read_u16(obj + 4) as u32 <= next {
            // observed: unlike rank 2 there is no `+0x3E0` latch and no
            // `rec + 0xC` test; the `0x80B77790` payload belongs to variant 0.
            match (flags >> 16) & 3 {
                0 => w141_vcall((this + 0x60) as u32, 0xD4, W141_MSG_80B77790),
                1 => next = (flags >> 8) & 0xF,
                2 => w141_vcall((this + 0x60) as u32, 0xD4, W141_MSG_80B777D0),
                _ => {}
            }
        }
        platform::write_u32(this + 0x670, next);
    }
}

/// Side-flip steering with the `+0x348` facing latch.
///
/// While `+0x9C0` counts down the actor steers through the `+0x9A0` vector.
/// When it reaches zero the octant returned by `0x80096240` is compared with the
/// `+0x348` side byte: equal means "facing the target", so `0x80AA9350`
/// re-aims the direction and the velocity pair `+0xE8`/`+0xEC` is rebuilt as
/// `(Ã‚±cos, -sin)`; different means the side byte is rewritten and the
/// "facing changed" marker `+0x9BC` is set.
///
/// # Original
/// - Ghidra: `FUN_80aa93f0` at `0x80AA93F0` (496 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80aa93f0_FUN_80aa93f0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x348` is the side byte, `+0xAC` the position,
///   `+0x9C0` the retarget countdown, `+0x9A0` the last direction, `+0xE8`/
///   `+0xEC`/`+0xF0` the velocity and `+0xD0`/`+0xD4`/`+0xD8` the position bias.
///
/// # Returns
/// `1` when the facing changed this frame (the side byte was rewritten), else
/// `0`.
///
/// # Side effects
/// Updates the position bias-relative delta vector, the velocity pair and the
/// `+0x9A0` shadow copy; re-arms `+0x9C0` to `0x28` (40 frames) inside the
/// unit-radius neighbourhood.
///
/// # Safety
/// The actor must be live; `+0x394`-style vtables are not touched, but the two
/// in-module callees ([`fn_80aa9350`]) must be valid.
///
/// # Confidence
/// high - the words and the export agree. Note that the specification's prose
/// (`docs/SPEC_WAVE140_ENEMIES.md` rank 4) names a `+0xA4E` write and a first
/// `sin`/`cos` pair that the shipped body does **not** contain; this port
/// follows the words, which write no `+0xA4E` and negate the `sin` term of
/// `+0xEC`.
pub unsafe fn fn_80aa93f0(this: usize) -> u32 {
    // observed: `0x80064740(this, r1+0x10)`; only the return value is used.
    let mut probe = [0.0f32; 8];
    let target = call2(
        W141_FN_80064740,
        this as u32,
        probe.as_mut_ptr() as u32,
    );
    if target == 0 {
        let _ = call1(W141_FN_8006CD40, this as u32);
        return 0;
    }
    let target = target as usize;

    // observed: the delta is taken against the *biased* target
    // `(target + this->bias) - this->pos`; the third component is a literal 0.0
    // (`0x80B2F6A0`).
    let delta = [
        (read_f32(target + 0xAC) + read_f32(this + 0xD0)) - read_f32(this + 0xAC),
        (read_f32(target + 0xB0) + read_f32(this + 0xD4)) - read_f32(this + 0xB0),
        0.0f32,
    ];

    let facing = {
        let f = crate::platform::guest_fn!(W141_FN_80096240, fn(u32, u32) -> u32);
        (f(this as u32, (this + 0xAC) as u32) & 0xFF) as u8
    };
    let dist_sq = w141_len_sq(delta.as_ptr());

    if platform::read_u32(this + 0x9C0) != 0 {
        platform::write_u32(this + 0x9C0, platform::read_u32(this + 0x9C0) - 1);
    }

    let mut result = 0u32;
    if platform::read_u32(this + 0x9C0) == 0 {
        if platform::read_u8(this + 0x348) == facing {
            let angle = fn_80aa9350(this, delta.as_ptr() as usize, 0xE0) as i16;
            // observed: `0x80B2F848` is the per-actor 1/256 angle scale.
            let cos = w141_cos16(angle as u16 as f32 * (1.0 / 256.0));
            let sin = w141_sin16(angle as u16 as f32 * (1.0 / 256.0));
            let vx = if platform::read_u8(this + 0x348) != 0 {
                -cos
            } else {
                cos
            };
            write_f32(this + 0xE8, vx);
            write_f32(this + 0xEC, -sin);
            write_f32(this + 0xF0, 0.0);
            write_f32(this + 0x9A0, vx);
            write_f32(this + 0x9A4, -sin);
            write_f32(this + 0x9A8, 0.0);
        } else {
            platform::write_u8(this + 0x348, facing);
            platform::write_u32(this + 0x9BC, 1);
            result = 1;
        }
    } else {
        let _ = fn_80aa9350(this, this + 0x9A0, 0xE0);
    }

    let _ = call1(W141_FN_8006CD40, this as u32);
    // observed: `fcmpo` against `0x80B2F6A4` (`1.0`).
    if dist_sq < 1.0 && platform::read_u32(this + 0x9C0) == 0 {
        platform::write_u32(this + 0x9C0, 0x28);
    }
    result
}

/// Vertical seek toward `player.y + 8 + 16 * +0x608`, with an arrival event.
///
/// The x position is stepped toward the player's x by `0.5` per frame. While
/// the actor is *below* the y target it fires the `0x1B5` event once and snaps
/// `+0xB0` to the target; while it is at or above the target it banks the model
