    platform::write_u16(this + 0xA4E, angle as u16);

    // observed: the first `0x80237BD0` result is kept in `f31` (sin), the second
    // `0x80237C40` result in `f1` (cos).
    let sin = w141_sin16(angle as u16 as f32 * (1.0 / 256.0));
    let cos = w141_cos16(angle as u16 as f32 * (1.0 / 256.0));

    // observed: `0x80B2F500` = 0.03125, clamped to `0x80B2F538`/`0x80B2F53C`.
    let vx = read_f32(this + 0xE8) + 0.03125 * cos;
