    write_f32(this + 0xAC, read_f32(this + 0xAC) + delta);
    let _ = call1(W141_FN_8006CDE0, this as u32);
    let _ = call1(W141_FN_800955F0, this as u32);

    let offset = platform::read_u32(this + 0x608) as i32 as f32;
    let y_target = 8.0 + read_f32(player + 0xB0) + 16.0 * offset;
