// --- Section-local ABI adapters ---------------------------------------------

/// Virtual call `slot` with `r3 = obj` and the `f32` payload in `f1`.
#[inline]
unsafe fn w143_vcall_f32(obj: u32, slot: u32, arg: f32) -> u32 {
    let vtable = platform::read_u32(obj as usize);
    let entry = platform::read_u32(vtable as usize + slot as usize) as usize;
    let f = crate::platform::guest_fn!(entry, fn(u32, f32) -> u32);
    f(obj, arg)
}

/// `0x80166EE0`: reads the `+0x5C4` sub-object's value (one output float).
#[inline]
unsafe fn w143_get_f32(obj: u32) -> f32 {
    let f = crate::platform::guest_fn!(W143_FN_80166EE0, fn(u32, u32) -> f64);
    f(obj, 0) as f32
}

/// `0x80166EF0`: writes the `+0x5C4` sub-object's value.
#[inline]
unsafe fn w143_set_f32(value: f32, obj: u32) {
    let f = crate::platform::guest_fn!(FN_80166EF0, fn(f64, u32, u32));
    f(value as f64, obj, 0);
}

/// `0x80075270`: ground probe with the two float arguments first.
#[inline]
unsafe fn w143_ground_probe(x: f32, y: f32, side: u32, out: u32) -> u32 {
    let f = crate::platform::guest_fn!(W143_FN_80075270, fn(f32, f32, u32, u32) -> u32);
    f(x, y, side, out)
}

/// `0x80078410`: stage effect with the two float arguments first.
#[inline]
unsafe fn w143_stage_effect(x: f32, y: f32, manager: u32, kind: u32) {
    let f = crate::platform::guest_fn!(W143_FN_80078410, fn(f32, f32, u32, u32) -> u32);
    let _ = f(x, y, manager, kind);
}

// --- 125a. `0x80AD8900` orbit offset around a resolved sub-actor -------------

/// Places the actor on an orbit around the sub-actor named by `+0x6FC`.
///
/// The sub-actor's heading is cached in `+0x6F6`, the actor's own heading
/// follows it by `+0x704`, and the orbit angle is the same heading plus
/// `+0x706`. The orbit point is `sub_actor.pos + +0x700 * (cos, sin)`, z copied
/// straight from the sub-actor, then the `+0xD0..+0xD8` pivot bias is removed
/// and the per-axis `+0x618..+0x620` bias added.
///
/// # Original
/// - Ghidra: `FUN_80ad8900` at `0x80AD8900` (308 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80ad8900_FUN_80ad8900.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the orbiting actor; `+0x6FC` the sub-actor id, `+0x700` the orbit
///   radius, `+0x704` the heading delta, `+0x706` the orbit phase delta.
///
/// # Side effects
/// Writes `+0x6F6`, `+0x104` and the position `+0xAC/0x0B0/0x0B4`; calls the
/// id resolver `0x80162D00` and the two trig helpers.
///
/// # Safety
/// The id resolver may return `0`, which the retail body dereferences without a
/// test, so the sub-actor must be live.
///
/// # Confidence
/// high - the three bias chains and both `qr3` u16 widenings are literal in the
/// export; the two trig calls are `0x80237C40` (x) and `0x80237BD0` (y).
pub unsafe fn fn_80ad8900(this: usize) {
    let sub = call1(W141_FN_80162D00, platform::read_u32(this + 0x6FC)) as usize;
    let sub_x = read_f32(sub + 0xAC);
    let sub_y = read_f32(sub + 0xB0);
    let sub_z = read_f32(sub + 0xB4);
    let base = read_i16(sub + 0x104);

    platform::write_u16(this + 0x6F6, base as u16);
    platform::write_u16(
        this + 0x104,
        base.wrapping_add(read_i16(this + 0x704)) as u16,
    );

    let phase = base.wrapping_add(read_i16(this + 0x706));
    let radius = read_f32(this + 0x700);
    let angle = (phase as u16) as f32 * read_f32(W143_F32_80B309FC);
    let x = sub_x + radius * w141_cos16(angle);
    let y = sub_y + radius * w141_sin16(angle);

    write_f32(
        this + 0xAC,
        (x - read_f32(this + 0xD0)) + read_f32(this + 0x618),
    );
    write_f32(
        this + 0xB0,
        (y - read_f32(this + 0xD4)) + read_f32(this + 0x61C),
    );
    write_f32(
        this + 0xB4,
        (sub_z - read_f32(this + 0xD8)) + read_f32(this + 0x620),
    );
}

// --- 125b. `0x80AFDD50` sanbo lean/pitch step --------------------------------

/// Runs the `daEnSanboEl_c` height lerp, lean table and spin-driven pitch.
///
/// The child's y plus `8.0` and `16.0 * (f32)(s32)+0x608` sets the actor's y.
/// The lean target comes from a four-entry table for `+0x604 == 0`, or from one
/// of four two-entry rows selected by `(mode - 1) & 3`, indexed by the child's
/// `+0x52C`. `0x8015F4F0` steps `+0x5CC` toward it by `0x100`. The spin phase
/// `+0x5CA` advances by `0x800` and `1536.0 * sin` displaces the lean into the
/// `s16` pitch `+0x102`.
///
/// # Original
/// - Ghidra: `FUN_80afdd50` at `0x80AFDD50` (300 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80afdd50_FUN_80afdd50.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the `daEnSanboEl_c` actor; `+0x010` the child node, `+0x604` the
///   lean mode, `+0x608` the height input, `+0x5CA` the spin, `+0x5CC` the lean.
///
/// # Returns
/// Nothing; the arrival flag of `0x8015F4F0` is ignored.
///
/// # Side effects
/// Writes `+0x0B0`, `+0x5CA`, `+0x5CC` (through the stepper) and `+0x102`.
///
/// # Safety
/// The child node must resolve; the two lean tables are file-backed words.
///
/// # Confidence
/// high - the table selector, the `0x100` step, the `0x800` spin and the
/// `1536.0` amplitude are literal; the `qr3` load is the pinned u16 widen.
pub unsafe fn fn_80afdd50(this: usize) {
    let child = call1(W143_FN_80162590, this as u32) as usize;
    let height = read_f32(W143_F32_80B317CC)
        + read_f32(child + 0xB0)
        + read_f32(W143_F32_80B317F0)
            * (platform::read_u32(this + 0x608) as i32 as f32);
    write_f32(this + 0xB0, height);

    let index = platform::read_u32(child + 0x52C) as usize;
    let mode = platform::read_u32(this + 0x604);
    let target = if mode == 0 {
        read_i16(W141_TABLE_80B31750 + index * 2) as i32
    } else {
        let row = ((mode.wrapping_sub(1) * 4) & 0xC) as usize;
        read_i16(W141_TABLE_80B31758 + row + index * 2) as i32
    };
    let _ = call3(W141_FN_8015F4F0, (this + 0x5CC) as u32, target as u32, 0x100);

    let spin = read_i16(this + 0x5CA).wrapping_add(0x800);
    platform::write_u16(this + 0x5CA, spin as u16);
    let angle = (spin as u16) as f32 * read_f32(W143_F32_80B317C8);
    let pitch = (read_i16(this + 0x5CC) as f32)
        + read_f32(W143_F32_80B317F4) * w141_sin16(angle);
    platform::write_u16(this + 0x102, pitch as i32 as u16);
}

// --- 125c. `0x80AB1900` mirrored direction pair ------------------------------

/// Publishes the `-4` and `+12` direction pairs from one mirrored base angle.
///
/// The angle is the `s16` heading `+0x100` minus a quarter turn, negated when
/// the `+0x348` side byte is set. Both pairs use `(sin, cos)` of that one angle;
/// the `-4` pair is the backwards fast direction (`+0x164`/`+0x168`) and the
/// `+12` pair the slow one (`+0x7DC`/`+0x7E0`).
///
/// # Original
/// - Ghidra: `FUN_80ab1900` at `0x80AB1900` (256 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80ab1900_FUN_80ab1900.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x100` the `s16` heading, `+0x348` the side byte.
///
/// # Side effects
/// Writes `+0x164`, `+0x168`, `+0x7DC` and `+0x7E0`.
///
/// # Safety
/// None beyond the `this` pointer: the body reads and writes only its own
/// fields and calls the two global trig helpers.
///
/// # Confidence
/// high - the `-0x4000` and the `-4.0`/`12.0` amplitudes are literal, and the
/// export's four `qr3` loads all widen the same re-staged halfword.
pub unsafe fn fn_80ab1900(this: usize) {
    let mut angle16 = read_i16(this + 0x100).wrapping_sub(0x4000);
    if platform::read_u8(this + 0x348) != 0 {
        angle16 = angle16.wrapping_neg();
    }

    let angle = (angle16 as u16) as f32 * read_f32(W143_F32_80B2FB48);
    let sin = w141_sin16(angle);
    let cos = w141_cos16(angle);

    write_f32(this + 0x164, read_f32(W143_F32_80B2FAE0) * sin);
    write_f32(this + 0x168, read_f32(W143_F32_80B2FAE0) * cos);
    write_f32(this + 0x7DC, read_f32(W143_F32_80B2FAEC) * sin);
    write_f32(this + 0x7E0, read_f32(W143_F32_80B2FAEC) * cos);
}

// --- 125d. `0x80A43810` follow a sub-actor at a fixed radius -----------------

/// Places the actor behind a sub-actor at the `+0x904` radius.
///
/// The sub-actor id `+0x900` is resolved; a miss runs `0x80064D10(this, 0)`
/// (the detach/hide path) and returns. Otherwise the angle is the sub-actor's
/// heading plus a quarter turn minus `+0x910`, the position is the sub-actor's
/// `+0x4B8/+0x4BC` anchor plus the radius times `(cos, sin)`, z is copied, and
/// the actor's own heading becomes that angle minus the same quarter turn.
///
/// # Original
/// - Ghidra: `FUN_80a43810` at `0x80A43810` (252 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a43810_FUN_80a43810.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the follower; `+0x900` the sub-actor id, `+0x904` the radius,
///   `+0x910` the heading offset.
///
/// # Side effects
/// Writes the position and `+0x104`; on a missed id it calls `0x80064D10`.
///
/// # Safety
/// A resolved sub-actor must stay live for the duration of the call.
///
/// # Confidence
/// high - the id test, the `+0x4000` arithmetic and both trig calls are literal
/// in the export; the z copy is a raw 32-bit store.
pub unsafe fn fn_80a43810(this: usize) {
    let sub = call1(W141_FN_80162D00, platform::read_u32(this + 0x900)) as usize;
    if sub == 0 {
        let _ = call2(W140_FN_80064D10, this as u32, 0);
        return;
    }

    let angle16 = read_i16(sub + 0x104)
        .wrapping_add(0x4000)
        .wrapping_sub(read_i16(this + 0x910));
    let radius = read_f32(this + 0x904);
    let angle = (angle16 as u16) as f32 * read_f32(W143_F32_80B2C718);

    write_f32(
        this + 0xAC,
        read_f32(sub + 0x4B8) + radius * w141_cos16(angle),
    );
    write_f32(
        this + 0xB0,
        read_f32(sub + 0x4BC) + radius * w141_sin16(angle),
    );
    write_f32(this + 0xB4, read_f32(sub + 0x4C0));
    platform::write_u16(this + 0x104, angle16.wrapping_sub(0x4000) as u16);
}

// --- 125e. `0x80AA37E0` 32-point trail generator -----------------------------

/// Refills the 32-point trail from a mirrored source heading.
///
/// The source heading `+0xA4E` is folded to `|angle| - 0x8000`, one angle feeds
/// a `(cos, sin)` pair, and the loop adds that pair to a stack accumulator
/// seeded from `+0xAC`/`+0xB0`. Point *n* is therefore
/// `(this.x + (n+1)*cos, this.y + (n+1)*sin)` for `n = 0..31`.
///
/// # Original
/// - Ghidra: `FUN_80aa37e0` at `0x80AA37E0` (240 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80aa37e0_FUN_80aa37e0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the trail owner; `+0xA4E` the `s16` source heading,
///   `+0x0AC`/`+0x0B0` the seed point.
///
/// # Side effects
/// Writes the 32 eight-byte `(x, y)` records at `+0x814..+0x913`.
///
/// # Safety
/// None beyond `this`: the record range is wholly inside the `0x914`-byte
/// object, and both trig calls are global helpers.
///
/// # Confidence
/// high - the mirror formula and the `+0x814`/`+0x914` loop bounds are literal;
/// the two `qr3` loads widen the same staged halfword.
pub unsafe fn fn_80aa37e0(this: usize) {
    let mut angle16 = read_i16(this + 0xA4E);
    if angle16 < 0 {
        angle16 = angle16.wrapping_neg();
    }
    // observed: `|a| - 0x8000` is evaluated modulo 2^16, so the i32 form
    // truncates back into the `s16` angle lane.
    let mirror = (angle16 as i32 - 0x8000) as i16;
    let angle = (mirror as u16) as f32 * read_f32(W143_F32_80B2F534);
    let cos = w141_cos16(angle);
    let sin = w141_sin16(angle);

    let mut x = read_f32(this + 0xAC);
    let mut y = read_f32(this + 0xB0);
    let mut cursor = this + 0x814;
    while cursor < this + 0x914 {
        x += cos;
        y += sin;
        write_f32(cursor, x);
        write_f32(cursor + 4, y);
        cursor += 8;
    }
}

// --- 125f. `0x80A79630` two-state sine envelope ------------------------------

/// Advances the rising or falling half of a two-state sine envelope.
///
/// State 1 (rising) writes `A * sin(phase)`; state 2 (falling) writes
/// `1 + A - sin(phase)`, so the two halves meet at the switch. Both states
/// advance `+0x08` by the config's `+0x04` phase delta, and state 1 flips to 2
/// once the new phase reaches a quarter turn.
///
/// # Original
/// - Ghidra: `FUN_80a79630` at `0x80A79630` (236 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a79630_FUN_80a79630.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: a 12-byte helper record; `+0x00` the config pointer
///   (`+0x00` amplitude, `+0x04` `s16` phase delta), `+0x04` the output,
///   `+0x08` the `s16` phase and `+0x0A` the state byte.
///
/// # Side effects
/// Writes `+0x04`, `+0x08` and (on the switch) `+0x0A`.
///
/// # Safety
/// `+0x00` must point at a readable config record.
///
/// # Confidence
/// high - both branches and the `0x4000` threshold are literal; the two `qr3`
/// loads are the pinned u16 widen of `+0x08`.
pub unsafe fn fn_80a79630(this: usize) {
    let state = platform::read_u8(this + 0x0A);
    if state == 1 {
        let config = platform::read_u32(this) as usize;
        let phase = read_i16(this + 0x08);
        let angle = (phase as u16) as f32 * read_f32(W143_F32_80B2DE24);
        write_f32(this + 0x04, w141_sin16(angle) * read_f32(config));
        let next = phase.wrapping_add(read_i16(config + 4));
        platform::write_u16(this + 0x08, next as u16);
        if next >= 0x4000 {
            platform::write_u8(this + 0x0A, 2);
        }
    } else if state == 2 {
        let config = platform::read_u32(this) as usize;
        let phase = read_i16(this + 0x08);
        let angle = (phase as u16) as f32 * read_f32(W143_F32_80B2DE24);
        write_f32(
            this + 0x04,
            (read_f32(W143_F32_80B2DE28) + read_f32(config)) - w141_sin16(angle),
        );
        platform::write_u16(
            this + 0x08,
            phase.wrapping_add(read_i16(config + 4)) as u16,
        );
    }
}

// --- 125g. `0x80ABAB50` lift-orbit and direction publish ---------------------

/// Orbits a child actor and publishes the local direction pair.
///
/// The child is resolved from `+0x5F0`, its position cached in
/// `+0x5E4/0x5E8/0x5EC` and its heading in `+0x5FE`. The actor's heading is
/// that plus `+0x5FC`; x/y are the cached child point plus `+0x5F8 * (cos, sin)`.
/// `0x80ABA950` republishes the same pair into `+0x5D0/+0x5D4`, `+0x5C4` mirrors
/// the heading by a quarter turn, and the sub-object at `+0x584` receives virtual
/// slot `0x0C` with the same `r * sin` still live in `f1`.
///
/// # Original
/// - Ghidra: `FUN_80abab50` at `0x80ABAB50` (236 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80abab50_FUN_80abab50.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the rotating lift half; `+0x5F0` the child id, `+0x5F8` the radius,
///   `+0x5FC` the heading delta, `+0x584` the receiving half-node.
///
/// # Side effects
/// Writes the position, `+0x5E4..+0x5EC`, `+0x104`, `+0x5FE`, `+0x5D0/0x5D4`
/// (through `0x80ABA950`), `+0x5C4`, then dispatches one virtual call.
///
/// # Safety
/// The child id must resolve and the `+0x584` vtable must be live. `0x80ABA950`
/// is untranslated and is called by its analysis address.
///
/// # Confidence
/// high - every store, both trig calls and the vtable slot are literal; the
/// untranslated helper is documented by `docs/SPEC_WAVE142_ENEMIES.md` and its
/// result is carried into `f1` exactly as the raw stream leaves it.
pub unsafe fn fn_80abab50(this: usize) {
    let child = call1(W141_FN_80162D00, platform::read_u32(this + 0x5F0)) as usize;
    write_f32(this + 0x5E4, read_f32(child + 0xAC));
    write_f32(this + 0x5E8, read_f32(child + 0xB0));
    write_f32(this + 0x5EC, read_f32(child + 0xB4));

    let child_heading = read_i16(child + 0x104);
    platform::write_u16(this + 0x5FE, child_heading as u16);
    let heading = child_heading.wrapping_add(read_i16(this + 0x5FC));
    platform::write_u16(this + 0x104, heading as u16);

    let radius = read_f32(this + 0x5F8);
    let angle = (heading as u16) as f32 * read_f32(W143_F32_80B2FFA0);
    let cos = w141_cos16(angle);
    let sin = w141_sin16(angle);
    write_f32(this + 0xAC, read_f32(this + 0x5E4) + radius * cos);
    write_f32(this + 0xB0, read_f32(this + 0x5E8) + radius * sin);

    let _ = call1(W143_FN_80ABA950, this as u32);
    platform::write_u16(this + 0x5C4, heading.wrapping_add(0x4000) as u16);
    let _ = w143_vcall_f32((this + 0x584) as u32, 0x0C, radius * sin);
}

// --- 125h. `0x80A40290` coin bounce direction and probe point ----------------

/// Builds the `daEnCoin_c` bounce direction and the probe point.
///
/// The `+0xA95` byte indexes the four-entry angle table; `0.5 * cos` sets
/// `+0x0E8` and `-0.5 * sin` sets `+0x0EC`. The x component is negated on the
/// mirrored side only, while the y component is always negative. The probe
/// point is the actor position with `-8` on x and `+16` on y.
///
/// # Original
/// - Ghidra: `FUN_80a40290` at `0x80A40290` (232 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a40290_FUN_80a40290.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the coin actor; `+0xA95` the bounce-table index, `+0x348` the side
///   byte, `+0x0AC/0x0B0/0x0B4` the position.
///
/// # Side effects
/// Writes `+0x0E8`, `+0x0EC` and the probe point `+0x6E8/0x6EC/0x6F0`.
///
/// # Safety
/// `+0xA95` is expected to be a small enum; the raw `lhax` has no bounds test.
///
/// # Confidence
/// high - the table values, the `0.5` amplitude, the two offsets and the
/// conditional negation are literal in the export.
pub unsafe fn fn_80a40290(this: usize) {
    let index = platform::read_u8(this + 0xA95) as usize;
    let angle16 = read_i16(W143_TABLE_80B2C604 + index * 2);
    let angle = (angle16 as u16) as f32 * read_f32(W143_F32_80B2C60C);
    let amplitude = read_f32(W143_F32_80B2C5FC);

    write_f32(this + 0xE8, amplitude * w141_cos16(angle));
    write_f32(this + 0xEC, -amplitude * w141_sin16(angle));
    if platform::read_u8(this + 0x348) != 0 {
        write_f32(this + 0xE8, -read_f32(this + 0xE8));
    }

    write_f32(
        this + 0x6E8,
        read_f32(this + 0xAC) - read_f32(W143_F32_80B2C540),
    );
    write_f32(
        this + 0x6EC,
        read_f32(this + 0xB0) + read_f32(W143_F32_80B2C568),
    );
    write_f32(this + 0x6F0, read_f32(this + 0xB4));
}

// --- 125i. `0x80A20810` radius vs 2-vector length predicate ------------------

/// Returns whether `radius` is longer than the two-component `vec`.
///
/// Both the radius and `vec` are pushed through the module's trig/sqrt pair:
/// `sqrt((r*cos)^2 + (r*sin)^2)` is `|radius|` and
/// `sqrt(x*x + y*y)` is `|vec|`; the result is the GT bit of their compare.
///
/// # Original
/// - Ghidra: `FUN_80a20810` at `0x80A20810` (228 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a20810_FUN_80a20810.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `radius`: the incoming `f1`.
/// - `vec`: the incoming `r4`, two `f32` components.
/// - `angle`: the incoming `r5` low halfword, in 16-bit turn units.
///
/// # Returns
/// `true` when `|radius| > |vec|`, otherwise `false`.
///
/// # Side effects
/// None: no stores, only the four helper calls.
///
/// # Safety
/// `vec` must point at two readable `f32` values. `r3` is dead on entry, so the
/// published Ghidra prototype mis-assigns the arguments; the raw `f1`/`r4`/`r5`
/// staging is used here.
///
/// # Confidence
/// high - both sqrt calls, the `1/256` pre-scale and the CR0.GT return idiom
/// are literal in the export.
pub unsafe fn fn_80a20810(radius: f32, vec: *const f32, angle: i16) -> bool {
    let angle_units = (angle as u16) as f32 * read_f32(W143_F32_80B2B764);
    let cos = w141_cos16(angle_units);
    let sin = w141_sin16(angle_units);
    let u = radius * cos;
    let v = radius * sin;
    let radius_length = w141_sqrtf(u * u + v * v);

    let x = *vec;
    let y = *vec.add(1);
    let vector_length = w141_sqrtf(x * x + y * y);

    radius_length.abs() > vector_length.abs()
}

// --- 125j. `0x80A7ADA0` squash/stretch pair ----------------------------------

/// Publishes the antiphase `+0xE84..+0xE8C` squash triple.
///
/// `+0xE84` is `2 * sin(heading)`; the second angle is the doubled heading minus
/// a quarter turn, and its sine drives a pair that always sums to `2.0` and
/// stays in `[1.0, 1.5]` / `[0.5, 1.0]`.
///
/// # Original
/// - Ghidra: `FUN_80a7ada0` at `0x80A7ADA0` (220 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a7ada0_FUN_80a7ada0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0xE90` the `s16` source heading.
///
/// # Side effects
/// Writes `+0xE84`, `+0xE88` and `+0xE8C`.
///
/// # Safety
/// None beyond `this`: the body only reads a heading and calls `0x80237BD0`.
///
/// # Confidence
/// high - both angles, the `2.0` gain and the `0.25`/`-0.25` quarter terms are
/// literal; the quarter terms are `(1.5 - 1.0) * 0.5` and `(0.5 - 1.0) * 0.5`.
pub unsafe fn fn_80a7ada0(this: usize) {
    let heading = read_i16(this + 0xE90);
    let angle = (heading as u16) as f32 * read_f32(W143_F32_80B2DE24);
    write_f32(
        this + 0xE84,
        read_f32(W143_F32_80B2DDFC) * w141_sin16(angle),
    );

    let doubled = heading.wrapping_mul(2).wrapping_sub(0x4000);
    let second = (doubled as u16) as f32 * read_f32(W143_F32_80B2DE24);
    let sin = w141_sin16(second);

    let upper = (read_f32(W143_F32_80B2DE00) - read_f32(W143_F32_80B2DE28))
        * read_f32(W143_F32_80B2E10C);
    let lower = (read_f32(W143_F32_80B2DE04) - read_f32(W143_F32_80B2DE28)) * 0.5;
    write_f32(
        this + 0xE88,
        read_f32(W143_F32_80B2DE28) + (upper + upper * sin),
    );
    write_f32(
        this + 0xE8C,
        read_f32(W143_F32_80B2DE28) + (lower + lower * sin),
    );
}

// --- 125k. `0x80A6EA20` 72/32 unit platform offsets --------------------------

/// Publishes the horizontal platform offsets around the actor heading.
///
/// `+0x164/+0x168` is the heading direction at radius `72` with a `-3` bias on
/// the second component only; `+0x5BC/+0x5C0` is the outer point and
/// `+0x5C8/+0x5CC` the inner point at radius `32`. Nothing writes z.
///
/// # Original
/// - Ghidra: `FUN_80a6ea20` at `0x80A6EA20` (212 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a6ea20_FUN_80a6ea20.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the platform actor; `+0x104` the `s16` heading, `+0x0AC/0x0B0` the
///   position.
///
/// # Side effects
/// Writes the four offset words and the four point words.
///
/// # Safety
/// None beyond `this`: the body only reads its own fields.
///
/// # Confidence
/// high - the `72`/`32` radii and the `-3` bias are literal; the `f31` park is
/// cosmetic and is folded into one `cos`/`sin` pair here.
pub unsafe fn fn_80a6ea20(this: usize) {
    let heading = read_i16(this + 0x104);
    let angle = (heading as u16) as f32 * read_f32(W143_F32_80B2DA20);
    let cos = w141_cos16(angle);
    let sin = w141_sin16(angle);

    let outer = read_f32(W143_F32_80B2DA24);
    write_f32(this + 0x164, outer * cos);
    write_f32(this + 0x168, outer * sin - read_f32(W143_F32_80B2DA28));
    write_f32(this + 0x5BC, read_f32(this + 0xAC) + outer * cos);
    write_f32(this + 0x5C0, read_f32(this + 0xB0) + outer * sin);

    let inner = read_f32(W143_F32_80B2DA2C);
    write_f32(this + 0x5C8, read_f32(this + 0xAC) + inner * cos);
    write_f32(this + 0x5CC, read_f32(this + 0xB0) + inner * sin);
}

// --- 125l. `0x80A1D530` mirrored 32-unit offset ------------------------------

/// Offsets the actor 32 units from its cached base point with a mirrored angle.
///
/// On side 0 the working angle is `-0x8000 - src` (a half-turn mirror) and the
/// published `+0x816` keeps `src`; on the other side the working angle is `src`
/// and `+0x816` is `-src`. Only the working angle `+0x818` feeds the trig pair,
/// and the result is added to the cached base `+0x7EC/+0x7F0`.
///
/// # Original
/// - Ghidra: `FUN_80a1d530` at `0x80A1D530` (208 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a1d530_FUN_80a1d530.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x81A` the source angle, `+0x348` the side byte,
///   `+0x7EC/0x7F0` the base point.
///
/// # Side effects
/// Writes `+0x816`, `+0x818` and the position `+0x0AC/0x0B0`.
///
/// # Safety
/// None beyond `this`: the base point is read, never recomputed here.
///
/// # Confidence
/// high - the `-0x8000 - src` / `-src` split and the `32.0` radius are literal
/// in the export.
pub unsafe fn fn_80a1d530(this: usize) {
    let source = read_i16(this + 0x81A);
    let working;
    if platform::read_u8(this + 0x348) == 0 {
        platform::write_u16(this + 0x816, source as u16);
        // observed: `subfic r0,r0,-32768` is an exact `s16` half-turn mirror.
        working = (-0x8000i32 - source as i32) as i16;
        platform::write_u16(this + 0x818, working as u16);
    } else {
        working = source;
        platform::write_u16(this + 0x818, working as u16);
        platform::write_u16(this + 0x816, source.wrapping_neg() as u16);
    }

    let angle = (working as u16) as f32 * read_f32(W143_F32_80B2B6A4);
    let radius = read_f32(W143_F32_80B2B6A8);
    write_f32(
        this + 0xAC,
        read_f32(this + 0x7EC) + radius * w141_cos16(angle),
    );
    write_f32(
        this + 0xB0,
        read_f32(this + 0x7F0) + radius * w141_sin16(angle),
    );
}

// --- 125m. `0x80B12470` side-dependent sidestep and frame tail ----------------

/// Steps the `+0x5CC` sidestep toward the actor's open side and runs the frame.
///
/// The sign of the step is chosen by comparing the `+0x348` side byte with the
/// `+0x459` state byte: equal sides add the `main.dol` word `0x8042C2DC`
/// (`s16 0x0C00`), different sides subtract it. The two base frame calls run
/// next, then `+0x102` is stepped by the `s16` table at `0x80B32094` indexed by
/// `+0x459`, and `0x80097170(1.0, this, this+0xAC)` applies the frame.
///
/// # Original
/// - Ghidra: `FUN_80b12470` at `0x80B12470` (168 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b12470_FUN_80b12470.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x348` the side byte, `+0x459` the state/side index,
///   `+0x5CC` the `s16` sidestep and `+0x102` the `s16` pitch.
///
/// # Side effects
/// Writes `+0x5CC` and `+0x102`; calls `0x8006CDE0`, `0x800955F0` and
/// `0x80097170`.
///
/// # Safety
/// The actor must be live for the two frame calls and the placement call.
///
/// # Confidence
/// medium - the side test, both `lha`/`sth` pairs and the table displacement
/// are literal in the raw stream, but the `+0x459` role (side/state index) is
/// inferred from its two uses; `0x8042C2DC` reads `0x0C00` and the table's two
/// used entries are `0x0100`/`0xFF00`.
pub unsafe fn fn_80b12470(this: usize) {
    if platform::read_u8(this + 0x348) == platform::read_u8(this + 0x459) {
        let next = read_i16(this + 0x5CC).wrapping_add(read_i16(W143_I16_8042C2DC));
        platform::write_u16(this + 0x5CC, next as u16);
    } else {
        let next = read_i16(this + 0x5CC).wrapping_sub(read_i16(W143_I16_8042C2DC));
        platform::write_u16(this + 0x5CC, next as u16);
    }

    let _ = call1(W141_FN_8006CDE0, this as u32);
    let _ = call1(W141_FN_800955F0, this as u32);

    let index = platform::read_u8(this + 0x459) as usize;
    let step = read_i16(W143_TABLE_80B32094 + index * 2);
    platform::write_u16(
        this + 0x102,
        read_i16(this + 0x102).wrapping_add(step) as u16,
    );
    let _ = call3_f64(
        FN_80097170,
        read_f32(W143_F32_80B32004) as f64,
        this as u32,
        (this + 0xAC) as u32,
    );
}

// --- 125n. `0x80B174F0` five-step vertical ramp ------------------------------

/// Ramps `+0xDC` between `1.5` and `2.0` in `0.25` steps and mirrors it.
///
/// The body returns `0` immediately when the `+0x638` gate is clear. Otherwise
/// the parity of `+0x63C` selects the rising (`+` `0.25`, clamp at `2.0`) or
/// falling (`-` `0.25`, clamp at `1.5`) half; the clamped value is copied to
/// `+0xE0`/`+0xE4`. Once `+0x63C` exceeds `5` the gate is cleared and the body
/// returns `0`.
///
/// # Original
/// - Ghidra: `FUN_80b174f0` at `0x80B174F0` (180 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b174f0_FUN_80b174f0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x638` the ramp gate, `+0x63C` the step counter and
///   `+0xDC` the ramped value.
///
/// # Returns
/// `1` while the ramp continues, `0` when the gate is clear or the counter
/// passes `5`.
///
/// # Side effects
/// Writes `+0xDC`, `+0xE0`, `+0xE4`, `+0x63C` and (on retirement) `+0x638`.
///
/// # Safety
/// None beyond `this`: the body only touches its own words and the shared
/// float block.
///
/// # Confidence
/// high - the two clamps, the parity test, the `6` comparison and all four
/// constants (`0.25`, `1.5`, `2.0`, `+0x638`) are literal.
pub unsafe fn fn_80b174f0(this: usize) -> u32 {
    let base = W143_TABLE_80B32230;
    if platform::read_u32(this + 0x638) == 0 {
        return 0;
    }

    let step = platform::read_u32(this + 0x63C);
    if step & 1 == 0 {
        let next = read_f32(this + 0xDC) + read_f32(base + 0xB0);
        write_f32(this + 0xDC, next);
        if next >= read_f32(base + 0xE8) {
            write_f32(this + 0xDC, read_f32(base + 0xE8));
            platform::write_u32(this + 0x63C, step.wrapping_add(1));
        }
    } else {
        let next = read_f32(this + 0xDC) - read_f32(base + 0xB0);
        write_f32(this + 0xDC, next);
        if next <= read_f32(base + 0xD8) {
            write_f32(this + 0xDC, read_f32(base + 0xD8));
            platform::write_u32(this + 0x63C, step.wrapping_add(1));
        }
    }

    let value = read_f32(this + 0xDC);
    write_f32(this + 0xE0, value);
    write_f32(this + 0xE4, value);
    if platform::read_u32(this + 0x63C) > 5 {
        platform::write_u32(this + 0x638, 0);
        return 0;
    }
    1
}

// --- 125o. `0x80B1DA40` lerp toward a cached point ----------------------------

/// Places the actor on the line from `+0x61C/+0x620` toward `+0x628/+0x62C`.
///
/// The scale is `(4.0 + 14.0 + contact_query(+0x668)) / length`, where the
/// length is the distance between the two cached points; x and y are the base
/// point plus the scaled delta. No z is written.
///
/// # Original
/// - Ghidra: `FUN_80b1da40` at `0x80B1DA40` (180 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b1da40_FUN_80b1da40.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x61C/+0x620` the base point, `+0x628/+0x62C` the
///   target point and `+0x668` the sub-object read by `0x800E9020`.
///
/// # Side effects
/// Writes `+0x0AC` and `+0x0B0`; calls `0x800E9020` and `0x802BE470`.
///
/// # Safety
/// The `+0x668` sub-object must be readable; the two points must not coincide
/// (the raw `fdivs` has no zero test).
///
/// # Confidence
/// high - the two radii, the four field reads and the sqrt call are literal.
pub unsafe fn fn_80b1da40(this: usize) {
    let lift = call1_ret_f32(W141_FN_800E9020, (this + 0x668) as u32);
    let dx = read_f32(this + 0x628) - read_f32(this + 0x61C);
    let dy = read_f32(this + 0x62C) - read_f32(this + 0x620);
    let radius = read_f32(W143_F32_80B32690) + (read_f32(W143_F32_80B3267C) + lift);
    let scale = radius / w141_sqrtf(dx * dx + dy * dy);

    write_f32(this + 0xAC, read_f32(this + 0x61C) + scale * dx);
    write_f32(this + 0xB0, read_f32(this + 0x620) + scale * dy);
}

// --- 125p. `0x80B178B0` actor state initialiser ------------------------------

/// Re-seeds the ramp words and the three timers of the `0x80B1xxxx` actor.
///
/// `+0x114`/`+0x11C` and the `+0xE8..+0xFC` block are seeded from the shared
/// float block, the `+0x5C4` sub-object is clamped into `[63.0, 70.0]`, and
/// `0x8006D090` receives the zero record `0x80B3231C` for the `+0x1EC` holder.
/// The tail arms `+0x644 = 8`, `+0x648 = 0`, the `+0x66B` RNG byte, the two
/// `0x60`/`0x80`-biased angles at `+0x664`/`+0x666`, the `0xB4` timer `+0x658`
/// and clears `+0x61E`/`+0x620`.
///
/// # Original
/// - Ghidra: `FUN_80b178b0` at `0x80B178B0` (268 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b178b0_FUN_80b178b0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x5C4` the clamped sub-object, `+0x1EC` the holder
///   that receives the record.
///
/// # Side effects
/// Writes the whole seed block and four timer words; calls `0x80166EE0`,
/// `0x80166EF0`, `0x8006D090` and four `0x800B2EE0` draws.
///
/// # Safety
/// The `+0x5C4` sub-object and the `+0x1EC` holder must be live.
///
/// # Confidence
/// high - every store and both clamp bounds are literal; the two draws use the
/// same `0x800B2EE0(0x21)` shape as the neighbouring initialisers.
pub unsafe fn fn_80b178b0(this: usize) {
    let base = W143_TABLE_80B32230;
    platform::write_u32(this + 0x640, 0);
    write_f32(this + 0x114, read_f32(base + 0xF8));
    write_f32(this + 0x11C, read_f32(base + 0xAC));
    write_f32(this + 0xE8, read_f32(base + 0xAC));
    write_f32(this + 0xEC, read_f32(base + 0xAC));
    write_f32(this + 0xF0, read_f32(base + 0xAC));
    write_f32(this + 0xF4, read_f32(base + 0xAC));
    write_f32(this + 0xF8, read_f32(base + 0xFC));
    write_f32(this + 0xFC, read_f32(base + 0xAC));

    let value = w143_get_f32((this + 0x5C4) as u32);
    let low = read_f32(base + 0x100);
    let high = read_f32(base + 0x104);
    if value < low || value > high {
        w143_set_f32(low, (this + 0x5C4) as u32);
    }

    let _ = call5(
        FN_8006D090,
        (this + 0x1EC) as u32,
        this as u32,
        (base + 0xEC) as u32,
        0,
        0,
    );
    platform::write_u32(this + 0x644, 8);
    platform::write_u32(this + 0x648, 0);
    platform::write_u8(this + 0x66B, call1(FN_800B2EE0, 2) as u8);
    let first = call1(FN_800B2EE0, 0x21) as i32 as i16;
    platform::write_u16(this + 0x664, first.wrapping_add(0x60) as u16);
    let second = call1(FN_800B2EE0, 0x21) as i32 as i16;
    platform::write_u16(this + 0x666, second.wrapping_add(0x80) as u16);
    platform::write_u32(this + 0x658, 0xB4);
    platform::write_u16(this + 0x61E, 0);
    platform::write_u16(this + 0x620, 0);
}

// --- 125q. `0x80B173B0` side-clamped vertical ramp ---------------------------

/// Clamps and steps a vertical value against the `+0x604`/`+0x608` band.
///
/// The value supplies its own step: below or at `+0x60C` it moves toward
/// `+0x608`, above it toward `+0x604`, scaled by `0.0625` and biased by
/// `0.125`, with the magnitude capped at `0.5`. The step is negated on side 0.
/// Crossing the top resets `+0x348` to 0 and, in mode 1, runs a ground probe
/// `10.0` below the actor and a stage effect at the probed height; crossing the
/// bottom sets `+0x348` to 1.
///
/// # Original
/// - Ghidra: `FUN_80b173b0` at `0x80B173B0` (320 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b173b0_FUN_80b173b0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x604`/`+0x608` the band, `+0x60C` the direction
///   split, `+0x348` the side byte and `+0x628` the mode.
/// - `value`: the incoming `f1` (`r3` holds `this`; Ghidra swaps the two).
///
/// # Returns
/// The stepped value, `f1`.
///
/// # Side effects
/// Writes `+0x348`; in mode 1 it may run `0x80075270` and `0x80078410`.
///
/// # Safety
/// The scene manager `0x80429DD0` and the ground probe must be valid whenever
/// the top clamp fires in mode 1.
///
/// # Confidence
/// high - the band arithmetic, the `0.0625`/`0.125`/`0.5` constants and both
/// clamps are literal; the double-precision staging in the export only widens
/// the intermediate values.
pub unsafe fn fn_80b173b0(this: usize, value: f32) -> f32 {
    let base = W143_TABLE_80B32230;
    let at_or_below = value <= read_f32(this + 0x60C);
    let mut step = if at_or_below {
        value - read_f32(this + 0x604)
    } else {
        read_f32(this + 0x608) - value
    };
    step = step * read_f32(base + 0xDC) + read_f32(base + 0xE0);
    if step >= read_f32(base + 0x9C) {
        step = read_f32(base + 0x9C);
    }
    if platform::read_u8(this + 0x348) == 0 {
        step = -step;
    }
    let mut out = value + step;

    if at_or_below {
        let bottom = read_f32(this + 0x604);
        if out <= bottom {
            platform::write_u8(this + 0x348, 1);
            out = bottom;
        }
    } else {
        let top = read_f32(this + 0x608);
        if out >= top {
            out = top;
            platform::write_u8(this + 0x348, 0);
            if platform::read_u32(this + 0x628) == 1 {
                let mut probe = 0.0f32;
                let _ = w143_ground_probe(
                    read_f32(this + 0xAC),
                    read_f32(this + 0xB0) - read_f32(base + 0xE4),
                    platform::read_u8(this + 0x38F) as u32,
                    &mut probe as *mut f32 as u32,
                );
                w143_stage_effect(
                    read_f32(this + 0xAC),
                    probe,
                    platform::read_u32(DAT_80429DD0),
                    4,
                );
            }
        }
    }

    out
}

// --- 125r. `0x80B171B0` timer, effect and hover step -------------------------

/// Runs the actor's two countdowns, the periodic stage effect and hover ramp.
///
/// [`fn_80b17340`] runs first. The `+0x624` counter reloads to `0x40` and emits
/// a stage effect (`kind` 1, or 3 in mode 1, count 1). The `+0x64C`/`+0x654`
/// pair counts down and emits a second effect with count 10, clearing both
/// words at the last frame. When `+0x650` is set in mode 1, `+0x614` ramps
/// toward `1.5` in `0.05` steps and back to `1.0`, flipping `+0x668`.
///
/// # Original
/// - Ghidra: `FUN_80b171b0` at `0x80B171B0` (388 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b171b0_FUN_80b171b0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x624` the effect timer, `+0x64C`/`+0x654` the second
///   timer pair, `+0x650`/`+0x668` the hover gate and its flip, `+0x628` the
///   mode, `+0x5F8`/`+0x5FC` the effect position.
///
/// # Side effects
/// Writes the four timer/flip words and `+0x614`; runs [`fn_80b17340`] and up to
/// two `0x80078470` stage effects.
///
/// # Safety
/// The scene manager `0x80429DD0` and the actor must be live.
///
/// # Confidence
/// medium - both timer machines, the `0x40` reload and the `0.05`/`1.5`/`1.0`
/// ramp are literal; `0x80078470` is an unnamed stage helper, so its effect
/// role is inferred from the same call shape in the neighbouring bodies.
pub unsafe fn fn_80b171b0(this: usize) {
    fn_80b17340(this);

    if platform::read_u32(this + 0x624) != 0 {
        platform::write_u32(
            this + 0x624,
            platform::read_u32(this + 0x624).wrapping_sub(1),
        );
    }
    if platform::read_u32(this + 0x624) == 0 {
        platform::write_u32(this + 0x624, 0x40);
        let kind = if platform::read_u32(this + 0x628) == 1 {
            3
        } else {
            1
        };
        let _ = call5_f64x2(
            FN_80078470,
            read_f32(this + 0x5F8) as f64,
            read_f32(this + 0x5FC) as f64,
            platform::read_u32(DAT_80429DD0),
            kind,
            1,
        );
    }

    if platform::read_u32(this + 0x64C) != 0 {
        if platform::read_u32(this + 0x654) != 0 {
            platform::write_u32(
                this + 0x654,
                platform::read_u32(this + 0x654).wrapping_sub(1),
            );
        }
        if platform::read_u32(this + 0x654) != 0 {
            let kind = if platform::read_u32(this + 0x628) == 1 {
                3
            } else {
                1
            };
            let _ = call5_f64x2(
                FN_80078470,
                read_f32(this + 0x5F8) as f64,
                read_f32(this + 0x5FC) as f64,
                platform::read_u32(DAT_80429DD0),
                kind,
                10,
            );
            if platform::read_u32(this + 0x654) == 1 {
                platform::write_u32(this + 0x64C, 0);
                platform::write_u32(this + 0x654, 0);
            }
        }
    }

    let base = W143_TABLE_80B32230;
    if platform::read_u32(this + 0x650) != 0 && platform::read_u32(this + 0x628) == 1 {
        if platform::read_u8(this + 0x668) == 0 {
            let next = read_f32(this + 0x614) + read_f32(base + 0xD4);
            write_f32(this + 0x614, next);
            if next >= read_f32(base + 0xD8) {
                write_f32(this + 0x614, read_f32(base + 0xD8));
                platform::write_u8(this + 0x668, 1);
            }
        } else {
            let next = read_f32(this + 0x614) - read_f32(base + 0xD4);
            write_f32(this + 0x614, next);
            if next <= read_f32(base + 0x84) {
                write_f32(this + 0x614, read_f32(base + 0x84));
                platform::write_u32(this + 0x650, 0);
                platform::write_u8(this + 0x668, 0);
            }
        }
    }
}

// ===========================================================================
// 126. Wave 144: the twelve `docs/SPEC_WAVE143_ENEMIES.md` class-D bodies and
//      five `0x80A00000` planner-bucket rows
// ===========================================================================
//
// Every body in this section was decoded from `work/rels/elf/d_enemiesNP.elf`
// with the `+0x1000` segment shift of `docs/REL_ELF_MAPPING.md`
// (`file_offset = address - 0x80A00000 + 0x1000`) and cross-checked against the
// Ghidra export named in its `# Original` block and the `size` column of
// `work/ghidra/rel-d_enemiesNP/export/functions.tsv`.
//
// **The `qr3` loads.** Ten of the specification rows read a halfword through
// `psq_l fD,0(rA),1,qr3`. `GQR3 = 0x00050005` is an unsigned 16-bit type at
// scale 0 (`docs/REL_ELF_MAPPING.md`), so each site is `(f32)(u16)field`: the
// `sth` staging slot two instructions earlier is the same halfword the body
// just wrote. No paired-single traffic is needed in the port. The
// `psq_st/psq_l ...,qr0` pairs are plain `f64` spills of `f31`/`f30`.
//
// **The bucket rows.** `0x80A03C90`, `0x80A04BF0`, `0x80A05F40`, `0x80A073B0`
// and `0x80A073C0` are five of the sixteen still-open `0x80A00000` planner
// rows. They were chosen because their instruction streams decode end to end
// without a recovered receiver or an unmodelled save helper.

// --- Callees cited by analysis address --------------------------------------

/// `0x8023D170`: paired with `0x8023D120` at both call sites of the two
/// table-walk twins below; `(r3 descriptor word *, r4 -1)`.
// unknown: the sibling of the ledgered `res_texcoord_set_index`; the export
// shows no field access, so its effect is not established.
const W144_FN_8023D170: usize = 0x8023_D170;

/// `0x8023DC10`: hands an 8-byte `{value, tag}` descriptor to the resource
/// layer as `(r3 &value, r4 0, r5 &tag)`.
// unknown: the callee is above the REL image and is not in the ledger.
const W144_FN_8023DC10: usize = 0x8023_DC10;

/// `0x802F8FF0`: `main.dol` functor word. The twins below copy the *address*
/// into a stack slot and pass the slot, so the callee receives `&0x802F8FF0`.
const W144_FUNCTOR_802F8FF0: usize = 0x802F_8FF0;

/// `0x80B74FD0`: `main.dol` record passed as the second argument of the
/// `daEnKopone_c` contact message (**ext**, above the REL image end).
const W144_DAT_80B74FD0: usize = 0x80B7_4FD0;

// --- Data-section constants -------------------------------------------------

/// `0x80B2E060` = `2.0`: gain of the push amount.
const W144_F32_80B2E060: usize = 0x80B2_E060;

/// `0x80B2F554` = `4.0`: horizontal offset radius of the published point.
const W144_F32_80B2F554: usize = 0x80B2_F554;

/// `0x80B2F558` = `32.0`: fixed height added to the published point.
const W144_F32_80B2F558: usize = 0x80B2_F558;

/// `0x80B2E160` = `0.125`: sway amplitude of the `daEnIbaramushi_c` pair.
const W144_F32_80B2E160: usize = 0x80B2_E160;

/// `0x80B3290C` = `1/256`: the water-pakkun turn pre-scale.
const W144_F32_80B3290C: usize = 0x80B3_290C;

/// `0x80B328F4` = `3.0`: sink below the authored rest height.
const W144_F32_80B328F4: usize = 0x80B3_28F4;

/// `0x80B32910` = `16384.0`: pitch centre (`0x4000` in turn units).
const W144_F32_80B32910: usize = 0x80B3_2910;

/// `0x80B32914` = `4096.0`: pitch amplitude (`0x1000` in turn units).
const W144_F32_80B32914: usize = 0x80B3_2914;

/// `0x80B54BA0` = `0.3`: `daEnKopone_c` yaw-speed gain.
const W144_F32_80B54BA0: usize = 0x80B5_4BA0;

/// `0x80B31778` = `s16[4] {0xFC00, 0x0800, 0xFA00, 0x0400}` =
/// `{-1024, 2048, -1536, 1024}`: heading steps selected by `+0x604`.
const W144_TABLE_80B31778: usize = 0x80B3_1778;

/// `0x80B317C0` = `0.7`: sine amplitude for `+0x608 == 0`.
const W144_F32_80B317C0: usize = 0x80B3_17C0;

/// `0x80B317C4` = `1.34`: sine amplitude for `+0x608 != 0`.
const W144_F32_80B317C4: usize = 0x80B3_17C4;

/// `0x80B30B50` = `1/256`: the `block_pata` spring pre-scale.
const W144_F32_80B30B50: usize = 0x80B3_0B50;

/// `0x80B30B54` = `36.0`: `block_pata` height-spring amplitude.
const W144_F32_80B30B54: usize = 0x80B3_0B54;

/// `0x80B2A994` = `0.0`: the neutral third component of the `+0x670` vector.
const W144_F32_80B2A994: usize = 0x80B2_A994;

/// `0x80B2A998` = `16.0`: amplitude of the two `+0x5D8` half-extents.
const W144_F32_80B2A998: usize = 0x80B2_A998;

/// `0x80B2A9B0` = `1/256`: the `0x80A03C90` turn pre-scale.
const W144_F32_80B2A9B0: usize = 0x80B2_A9B0;

/// `0x80377A04`: `main.dol` address returned verbatim by `0x80A073B0` and
/// `0x80A073C0`.
// unknown: the word is 4-byte aligned inside `main.dol` but its object is not
// identified; both bodies only materialise it.
const W144_DAT_80377A04: u32 = 0x8037_7A04;

// --- Section-local ABI adapters ---------------------------------------------

/// Actor vtable dispatch with the vtable pointer at `+0x60`:
/// `(*(fn**)(u32[x+0x60] + slot))(x)`, one register argument.
#[inline]
unsafe fn w144_actor_vcall(obj: u32, slot: u32) -> u32 {
    let vtable = platform::read_u32(obj as usize + 0x60);
    let entry = platform::read_u32(vtable as usize + slot as usize) as usize;
    let f = crate::platform::guest_fn!(entry, fn(u32) -> u32);
    f(obj)
}

/// Actor vtable dispatch with the vtable pointer at `+0x60` and one payload
/// word: `(*(fn**)(u32[x+0x60] + slot))(x, payload)`.
#[inline]
unsafe fn w144_actor_vcall1(obj: u32, slot: u32, payload: u32) -> u32 {
    let vtable = platform::read_u32(obj as usize + 0x60);
    let entry = platform::read_u32(vtable as usize + slot as usize) as usize;
    let f = crate::platform::guest_fn!(entry, fn(u32, u32) -> u32);
    f(obj, payload)
}

// --- 126a. `0x80A00000` planner-bucket rows ---------------------------------

// --- 126a.1 `0x80A03C90` heading/pitch half-extent pair ----------------------

/// Publishes `16*cos(+0x100) * sin(+0x102)` and `-(16*sin(+0x100))`.
///
/// The three trig reads are the actor's two `s16` angles: `+0x100` feeds both
/// the cosine and the sine term, `+0x102` only the third read. The first two
/// results carry a `16.0` amplitude, the third is a bare sine, so the two
/// stores are not a rotation of one vector.
///
/// # Original
/// - Ghidra: `FUN_80a03c90` at `0x80A03C90` (212 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a03c90_FUN_80a03c90.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x100` `s16` heading, `+0x102` `s16` pitch.
///
/// # Side effects
/// Writes `+0x5D8` and `+0x5DC`; calls `0x80237C40` (cos) once and
/// `0x80237BD0` (sin) twice.
///
/// # Safety
/// None beyond the `this` pointer: the body touches only its own fields and the
/// two global trig helpers.
///
/// # Confidence
/// medium - the three `qr3` widenings, the `16.0` amplitude, the `fneg` and both
/// store offsets are literal; the roles of `+0x5D8`/`+0x5DC` are not
/// established, so the pair is described by its arithmetic only.
pub unsafe fn fn_80a03c90(this: usize) {
    let pre_scale = read_f32(W144_F32_80B2A9B0);
    let heading = (read_i16(this + 0x100) as u16) as f32 * pre_scale;
    let cos_term = read_f32(W144_F32_80B2A998) * w141_cos16(heading);
    let sin_term = read_f32(W144_F32_80B2A998) * w141_sin16(heading);
    let pitch = (read_i16(this + 0x102) as u16) as f32 * pre_scale;

    // observed: the third sine is *not* scaled by `16.0` before the product.
    write_f32(this + 0x5D8, cos_term * w141_sin16(pitch));
    write_f32(this + 0x5DC, -sin_term);
}

// --- 126a.2 `0x80A04BF0` direction rescale ----------------------------------

/// Turns the `+0x670` planar pair by the actor's heading, normalises it and
/// rescales it by `weight` into `+0xE8/+0xEC/+0xF0`.
///
/// `fn_80a04940(this, &v, 0x200)` writes the shared direction vector,
/// `0x80170A00(&v)` normalises it in place, and each component is multiplied by
/// the `f32` in `f1`. The scaled x and y reach `+0xE8`/`+0xEC`; `+0xF0` is
/// written from the `0.0` constant, not from the scaled z. `0x8006CD40(this)`
/// then runs the shared actor update.
///
/// # Original
/// - Ghidra: `FUN_80a04bf0` at `0x80A04BF0` (176 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a04bf0_FUN_80a04bf0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x670`/`+0x674` the source pair.
/// - `weight`: `f1`, the scalar applied to all three components.
///
/// # Side effects
/// Writes the three direction words, `+0xE8`, `+0xEC`, `+0xF0`, then runs
/// `0x8006CD40`.
///
/// # Safety
/// The actor and its `+0x670` block must be live; `0x8006CD40` walks the same
/// object.
///
/// # Confidence
/// medium - the turn, the in-place normalise, the three multiplies and the two
/// stores are literal; the roles of `+0x670` (source pair) and `+0xE8..0xF0`
/// (scaled direction) are inferred from their use as a vector triple.
pub unsafe fn fn_80a04bf0(this: usize, weight: f32) {
    let mut direction = [
        read_f32(this + 0x670),
        read_f32(this + 0x674),
        read_f32(W144_F32_80B2A994),
    ];
    fn_80a04940(this, direction.as_mut_ptr() as usize, 0x200);
    call1(0x8017_0A00, direction.as_mut_ptr() as u32);

    write_f32(this + 0xE8, direction[0] * weight);
    write_f32(this + 0xEC, direction[1] * weight);
    // observed: `+0xF0` reloads the `0.0` word instead of using the scaled z.
    write_f32(this + 0xF0, read_f32(W144_F32_80B2A994));
    call1(FN_8006CD40, this as u32);
}

// --- 126a.3 `0x80A05F40` free-with-count helper -----------------------------

/// Frees `ptr` through the archive heap when a positive count is supplied.
///
/// The body is the usual "delete array" shape: a null pointer or a
/// non-positive count skips the call, and the original pointer is returned so
/// the caller can keep assigning it.
///
/// # Original
/// - Ghidra: `FUN_80a05f40` at `0x80A05F40` (64 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a05f40_FUN_80a05f40.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `ptr`: `r3`, the block to release.
/// - `count`: `r4`, the element count; zero or negative keeps the block.
///
/// # Returns
/// `ptr`, unchanged, in both paths.
///
/// # Side effects
/// Calls the ledgered `arc_heap_free_object` at `0x802B9280`.
///
/// # Safety
/// `ptr` must be a heap block returned by the archive allocator, or null.
///
/// # Confidence
/// high - the two guards, the single call and the `r3` return are literal; the
/// callee is the ledgered `arc_heap_free_object`, which reads only `r3`.
pub unsafe fn fn_80a05f40(ptr: usize, count: i32) -> usize {
    if ptr != 0 && count > 0 {
        // observed: `r4` still holds `count` at the `bl`, but the callee takes
        // the block in `r3` only.
        let _ = call2(0x802B_9280, ptr as u32, count as u32);
    }
    ptr
}

