    write_f32(this + 0x5F4, read_f32(source + 0x04));
    write_f32(this + 0x5F8, read_f32(source + 0x08));
    write_f32(this + 0x5FC, read_f32(source + 0x0C));
    platform::write_u8(this + 0x600, platform::read_u8(source + 0x10));
    platform::write_u8(this + 0x601, platform::read_u8(source + 0x11));
    platform::write_u32(this + 0x604, platform::read_u32(source + 0x14));
    platform::write_u32(this + 0x608, platform::read_u32(source + 0x18));
    platform::write_u16(this + 0x60C, platform::read_u16(source + 0x1C));
    platform::write_u32(this + 0x610, platform::read_u32(source + 0x20));
