                        call1(FN_8013E630, player as u32);
                        platform::write_u16(this + index * 2 + 0x6BC, 1);
                        platform::write_u16(this + index * 2 + 0x6B4, 0x3D);
                        platform::write_u8(
                            this + index + 0x6C4,
                            platform::read_u8(this + index + 0x6CC),
                        );
                        platform::write_u8(this + index + 0x6D8, 1);
                        call1(W146_FN_80170A00, offset.as_mut_ptr() as u32);
                        write_f32(player + 0xAC, px + offset[0] * pull);
                        write_f32(player + 0xB0, py + offset[1] * pull);
                        platform::write_u32(player + 0xB4, pz);
