/// Classifies one point into side `3` (both probes clear), `1` or `2`.
///
/// The four probes are the two cell tests `0x80070BA0`/`0x80070BF0` at
/// `x +/- 4.0`; bit `0x400` of the first result and low byte `< 2` of the
/// second encode "blocked" (`docs/SPEC_WAVE146_ENEMIES.md` rank 2). The `word`
/// is the actor's `+4` descriptor; its bit 16 selects between side `1` and `2`.
#[inline]
unsafe fn w147_classify(px: f32, py: f32, half_width: f32, layer: u32, word: u32) -> u8 {
    let left = call3_f64_f64(
        W147_FN_80070BA0,
        (px + half_width) as f64,
        py as f64,
        layer,
    );
    let left_low = (call3_f64_f64(
        W147_FN_80070BF0,
        (px + half_width) as f64,
        py as f64,
        layer,
    ) & 0xFF) as u8;
    let right = call3_f64_f64(
        W147_FN_80070BA0,
        (px - half_width) as f64,
        py as f64,
        layer,
    );
    let right_low = (call3_f64_f64(
        W147_FN_80070BF0,
        (px - half_width) as f64,
        py as f64,
        layer,
    ) & 0xFF) as u8;

    let clear_left = (left & 0x400) == 0 || left_low < 2;
    let clear_right = (right & 0x400) == 0 || right_low < 2;
    if clear_left && clear_right {
        3
    } else if (word >> 16) & 1 == 0 {
        1
    } else {
        2
    }
}

