    platform::write_u32(this + 0x988, 0);
    if call0_ret_u32(0x800C_D250) != 0 {
        platform::write_u32(this + 0x988, 1);
        platform::write_u32(this + 0x9A0, 0xFF);
    }

    let word = platform::read_u32(this + 4);
    let lane = (word >> 8) & 0xF;
    let count = (word & 0xF) + 1;
    let origin = read_f32(0x80B2_FAD8);
    let spacing = read_f32(0x80B2_FADC);
    let y = origin - spacing * lane as f32;
    write_f32(this + 0xB4, y);
    platform::write_u8(this + 0x348, ((word >> 4) & 0xF) as u8);
    write_f32(this + 0x97C, spacing * -(count as f32));
    write_f32(this + 0x980, spacing * count as f32);
    platform::write_u32(this + 0x890, platform::read_u32(this + 0xAC));
    platform::write_u32(this + 0x894, platform::read_u32(this + 0xB0));
    write_f32(this + 0x898, y);
    platform::write_u8(this + 0x99C, 0xFF);

    fn_80ab1510(this);
    platform::write_u16(
        this + 0x102,
        platform::read_u16(0x80B2_FA74 + platform::read_u8(this + 0x348) as usize * 2),
    );

    let colour = read_f32(0x80B5_4B9C);
    write_f32(this + 0xDC, colour);
    write_f32(this + 0xE0, colour);
    write_f32(this + 0xE4, colour);

    call3(
        0x8008_C3E0,
        (this + 0x148) as u32,
        this as u32,
        0x80B2_FA90,
    );
    let minus_four = read_f32(0x80B2_FAE0);
    let zero = read_f32(0x80B2_FAE4);
    let eight = read_f32(0x80B2_FAE8);
    write_f32(this + 0x864, minus_four);
    write_f32(this + 0x868, zero);
    write_f32(this + 0x86C, eight);
    write_f32(this + 0x870, eight);
    write_f32(this + 0x164, minus_four);
    write_f32(this + 0x168, zero);
    write_f32(this + 0x16C, eight);
    write_f32(this + 0x170, eight);
    platform::write_u8(this + 0x1E6, 1);
    call1(0x8008_C330, (this + 0x148) as u32);

    call3(
        0x8008_C3E0,
        (this + 0x7C0) as u32,
        this as u32,
        0x80B2_FA90,
    );
    let twelve = read_f32(0x80B2_FAEC);
    write_f32(this + 0x874, twelve);
    write_f32(this + 0x878, zero);
    write_f32(this + 0x87C, eight);
    write_f32(this + 0x880, eight);
    write_f32(this + 0x7DC, twelve);
    write_f32(this + 0x7E0, zero);
    write_f32(this + 0x7E4, eight);
    write_f32(this + 0x7E8, eight);
    platform::write_u8(this + 0x85E, 1);
    platform::write_u8(this + 0x860, platform::read_u8(0x8042_9D28));
