        let mut pos = [
            platform::read_u32(this + 0xAC),
            platform::read_u32(this + 0xB0),
            platform::read_u32(this + 0xB4),
        ];
        let mut rot = [
            platform::read_u16(this + 0x100),
            platform::read_u16(this + 0x102),
            platform::read_u16(this + 0x104),
        ];
        call3(
            0x8006_4AF0,
            pos.as_mut_ptr() as u32,
            rot.as_mut_ptr() as u32,
            1,
        );
        call4_f64x3(
            0x801C_0BD0,
            f32::from_bits(pos[0]) as f64,
            f32::from_bits(pos[1]) as f64,
            f32::from_bits(pos[2]) as f64,
            (this + 0x7C) as u32,
        );
        let mut ry = rot[1];
        call2(0x8016_EDD0, (this + 0x7C) as u32, (&mut ry as *mut u16) as u32);
        let mut rx = rot[0];
        call2(0x8016_ECB0, (this + 0x7C) as u32, (&mut rx as *mut u16) as u32);
        let mut rz = rot[2];
        call2(0x8016_EEF0, (this + 0x7C) as u32, (&mut rz as *mut u16) as u32);

        call2(0x8016_A170, (this + 0x544) as u32, (this + 0x7C) as u32);
        call2(0x8016_A150, (this + 0x544) as u32, (this + 0xDC) as u32);
        call2(0x8016_A1A0, (this + 0x544) as u32, 0);

        call3(
            0x8016_8180,
            (this + 0x544) as u32,
            4,
            bone.as_mut_ptr() as u32,
        );
        platform::write_u32(this + 0x89C, bone[3]);
        platform::write_u32(this + 0x8A0, bone[7]);
        platform::write_u32(this + 0x8A4, bone[11]);
        call3(
            0x8016_8180,
            (this + 0x544) as u32,
            0,
            bone.as_mut_ptr() as u32,
        );
        platform::write_u32(this + 0x8A8, bone[3]);
        platform::write_u32(this + 0x8AC, bone[7]);
        platform::write_u32(this + 0x8B0, bone[11]);
