    call1(FN_800955F0, this as u32);

    let angle = platform::read_u16(this + 0x550).wrapping_add(0x300);
    platform::write_u16(this + 0x550, angle);

    // observed: `psq_l f1,0(r1+0xA),qr3,W=1` re-reads the halfword just stored;
    // `GQR3 = 0x00050005` makes it `(f32)(u16)` with scale 1.
    let widened = platform::read_u16(this + 0x550) as f32;
    let warped = call1_f64_ret_f64(FN_80237BD0, (read_f32(0x80B3_2874) * widened) as f64);

    let stage = platform::read_u32(0x8042_9DD0) as usize;
    let lift = (read_f32(0x80B3_2878) as f64 * warped) as f32;
