// --- 133b.17 `0x80B27ED0` per-slot relay -------------------------------------

/// Re-heads one per-slot scene object and re-places it from the parent.
///
/// `0x80162D00` resolves the scene handle at `+0x6E8 + 4*slot`; a null result
/// ends the body. The target's `+0x102` becomes the incoming angle plus the
/// per-slot bias at `+0x884 + 2*slot`. With `+0x8AC == 1` the per-slot offset
/// `(x, y, z)` at `+0x774`/`+0x7B8`/`+0x7FC` is rotated through
/// `0x800BC070(this+0x584, ...)` and added to the base at `+0x738..0x740`;
/// otherwise the incoming angle drives a table sine/cosine pair that rotates
/// only the `x`/`z` radii into the base. Both arms finish with
/// `0x80B27DC0(radius x, s16[this+0x102])` stored into `+0xDC`/`+0xE0`/`+0xE4`.
///
/// # Original
/// - Ghidra: `FUN_80b27ed0` at `0x80B27ED0` (432 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80b27ed0_FUN_80b27ed0.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the relay parent; `+0x6E8` the scene-handle table, `+0x738` the
///   base position, `+0x884` the per-slot angle bias, `+0x8AC` the transform
///   selector.
/// - `angle`: heading to write (incoming `r4`, a signed halfword).
/// - `slot`: slot index (incoming `r5`).
///
/// # Side effects
/// Writes the target's `+0x102`, `+0xAC`/`+0xB0`/`+0xB4` and `+0xDC`/`+0xE0`/
/// `+0xE4`.
///
/// # Safety
/// The scene handle must resolve, and each of the three tables must cover the
/// requested `slot`.
///
/// # Confidence
/// medium - the two position arms, the three speed stores and the two `qr3`
/// loads are literal in the raw stream. The `qr3` loads widen the **incoming**
/// `r4` angle (`sth r28` before `psq_l`), not the `+0x102` heading the
/// specification assumed; the rotate arm does write y as well. Field roles other
/// than the position are `// inferred:`.
pub unsafe fn fn_80b27ed0(this: usize, angle: i16, slot: u32) {
    let handle = platform::read_u32(this + 0x6E8 + slot as usize * 4);
    let target = call1(FN_80162D00, handle) as usize;
    if target == 0 {
        return;
    }

    let bias = platform::read_u16(this + 0x884 + slot as usize * 2) as i16;
    platform::write_u16(target + 0x102, angle.wrapping_add(bias) as u16);

    let offset = this + slot as usize * 4;
    if platform::read_u32(this + 0x8AC) == 1 {
        let mut local = [
            platform::read_u32(offset + 0x774),
            platform::read_u32(offset + 0x7B8),
            platform::read_u32(offset + 0x7FC),
        ];
        let mut rotated = [0u32; 3];
        call3(
            W137_FN_800BC070,
            (this + 0x584) as u32,
            local.as_mut_ptr() as u32,
            rotated.as_mut_ptr() as u32,
        );
        write_f32(
            target + 0xAC,
            read_f32(this + 0x738) + f32::from_bits(rotated[0]),
        );
        write_f32(
            target + 0xB0,
            read_f32(this + 0x73C) + f32::from_bits(rotated[1]),
        );
        write_f32(
            target + 0xB4,
            read_f32(this + 0x740) + f32::from_bits(rotated[2]),
        );
    } else {
        let radius_x = read_f32(offset + 0x774);
        let radius_z = read_f32(offset + 0x7FC);
        // observed: both `qr3` loads widen the incoming `angle` (the `sth r28`
        // copies), not the `+0x102` heading the body has just written.
        let phase = angle as u16 as f32 * read_f32(0x80B3_2C78);
        let cosine = w141_cos16(phase);
        let sine = w141_sin16(phase);
        write_f32(
            target + 0xAC,
            read_f32(this + 0x738) + (cosine * radius_x + sine * radius_z),
        );
        write_f32(
            target + 0xB4,
            read_f32(this + 0x740) + (cosine * radius_z - sine * radius_x),
        );
    }

    let speed = w151_radius_speed(
        read_f32(offset + 0x774),
        platform::read_u16(this + 0x102) as i16 as i32,
    );
    write_f32(target + 0xDC, speed);
    write_f32(target + 0xE0, speed);
    write_f32(target + 0xE4, speed);
}

// --- 133c. Section-local ABI adapters ----------------------------------------

/// `0x80078410` as the caller reaches it: two single-precision arguments in
/// `f1`/`f2`, then the manager word in `r3` and the id in `r4`.
#[inline]
unsafe fn w151_effect_xy(x: f32, y: f32, manager: u32, kind: u32) -> u32 {
    let f = crate::platform::guest_fn!(W151_FN_80078410, fn(f32, f32, u32, u32) -> u32);
    f(x, y, manager, kind)
}

/// `0x80146E20`: `(player, id)` in `r3`/`r4`, two single-precision values in
/// `f1`/`f2`.
#[inline]
unsafe fn w151_motion_pair(addr: usize, player: u32, id: u32, first: f32, second: f32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(u32, u32, f32, f32) -> u32);
    f(player, id, first, second)
}

/// `0x80B27DC0`: one `f32` radius in `f1` and one `s16` angle in `r4`, returning
/// the per-link speed in `f1`.
#[inline]
unsafe fn w151_radius_speed(radius: f32, angle: i32) -> f32 {
    let f = crate::platform::guest_fn!(0x80B2_7DC0usize, fn(f32, i32) -> f32);
    f(radius, angle)
}

