// --- 137b. Section-local float adapters -------------------------------------

/// Calls `fn(f32, u32) -> u32`: `f1` is a single-precision value, `r3` an
/// integer. The stream loads both with `lfs`/`lwz`, so no promotion happens.
#[inline]
unsafe fn w155_call_fu(addr: usize, first: f32, second: u32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f32, u32) -> u32);
    f(first, second)
}

/// Calls `fn(f32, u32, u32) -> u32`: `f1` plus `r3`/`r4`.
#[inline]
unsafe fn w155_call_fuu(addr: usize, first: f32, second: u32, third: u32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f32, u32, u32) -> u32);
    f(first, second, third)
}

/// Calls `fn(f32, f32, u32, u32, u32, u32) -> u32`: the six-argument
/// `0x80078470` effect shape, with the two coordinates in `f1`/`f2` and four
/// integer registers `r3..r6`. The extra `r6` exists because
/// [`fn_80a03c30`]'s tail branch carries the literal `24` there.
#[inline]
unsafe fn w155_call_ffuuuu(
    addr: usize,
    x: f32,
    y: f32,
    manager: u32,
    layer: u32,
    count: u32,
    sixth: u32,
) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f32, f32, u32, u32, u32, u32) -> u32);
    f(x, y, manager, layer, count, sixth)
}

/// Calls `fn(f32, u32, u32, u32) -> u32`: `f1` plus `r3..r5`. Used by the
/// `0x800B6830` ground-holder attach, whose angle reaches it with `lfs`.
#[inline]
unsafe fn w155_call_fuuu(addr: usize, first: f32, second: u32, third: u32, fourth: u32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f32, u32, u32, u32) -> u32);
    f(first, second, third, fourth)
}

// --- 137c.1 `0x80A03C30` `daEnBuku_c` 24-frame stage-effect timer -----------

/// Counts `+0x69C` down and, on the frame it reaches zero, fires one stage
/// effect `32.0` units to the side of the `+0x688`/`+0x68C` anchor and reloads
/// the timer with `24`.
///
/// The countdown is the usual two-load shape: the store only happens while the
/// word is non-zero, and the guard re-reads it, so a wrap cannot skip the body.
/// The side byte `+0x348` indexes the `{32.0f, -32.0f}` table at
/// `0x80B2A9A8`, so the request x is `anchor_x +- 32.0` and y is the raw
/// `+0x68C`. `r6` still holds the literal `24` at the tail branch, so the
/// request carries the same value in its sixth register.
///
/// # Original
/// - Ghidra: `FUN_80a03c30` at `0x80A03C30` (92 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80a03c30_FUN_80a03c30.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the `daEnBuku_c` actor; `+0x69C` is the timer, `+0x688`/`+0x68C`
///   the effect anchor and `+0x348` the side index.
///
/// # Side effects
/// Writes `+0x69C` and tail-branches to `0x80078470` with
/// `(x, y, *(u32*)0x80429DD0, 3, 1, 24)`.
///
/// # Safety
/// The actor and the pointer at `0x80429DD0` must be live.
///
/// # Confidence
/// high - every operand, both table entries and the six staged registers are
/// literal in the ELF words; the export's `halt_baddata` is only the tail `b`.
pub unsafe fn fn_80a03c30(this: usize) {
    let timer = platform::read_u32(this + 0x69C) as i32;
    if timer != 0 {
        // observed: `addi r4,r4,-1` / `stw r4,0x69C(r3)`.
        platform::write_u32(this + 0x69C, timer.wrapping_sub(1) as u32);
    }
    // observed: the second `lwz`/`cmpwi` pair is a fresh load.
    if platform::read_u32(this + 0x69C) != 0 {
        return;
    }

    let side = platform::read_u8(this + 0x348) as usize;
    let x = read_f32(this + 0x688) + read_f32(W155_F32_80B2A9A8 + side * 4);
    let y = read_f32(this + 0x68C);
    // observed: `stw r6,0x69C(r3)` with `r6 = 0x18`.
    platform::write_u32(this + 0x69C, 24);
    let manager = platform::read_u32(W155_PTR_80429DD0);
    let _ = w155_call_ffuuuu(FN_80078470, x, y, manager, 3, 1, 24);
}

// --- 137c.2 `0x80AF3850` burst-cannon steer-target snap ---------------------

/// Snaps the burst cannon's guide angle to the nearest multiple of `800`.
///
/// The angle comes from [`fn_80af38b0`] (clamped to `-13500..=13500`) and is
/// first biased by `+400` for a non-negative value or `-400` for a negative
/// one; the biased value is then divided by `800` with the compiler's
/// `0x51EB851F` reciprocal-multiply sequence, which truncates toward zero, and
/// multiplied back. The result is a `s16` angle: `-1200 -> -1600`,
/// `-1199 -> -800`, `399 -> 0`, `400 -> 800`, `13500 -> 13600`.
///
/// # Original
/// - Ghidra: `FUN_80af3850` at `0x80AF3850` (88 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80af3850_FUN_80af3850.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x778` is the controller-id ring read by
///   [`fn_80af38b0`].
///
/// # Returns
/// The steer target as a sign-extended `s16` angle in the same units as
/// `+0x7A4`: a multiple of `800`.
///
/// # Side effects
/// None. The call to [`fn_80af38b0`] only reads the actor and its controller
/// record.
///
/// # Safety
/// `this` and the `+0x778` slot must be live.
///
/// # Confidence
/// high - the bias, the reciprocal multiply, the sign fix and the final `extsh`
/// are literal, and the only callee is translated ([`fn_80af38b0`]).
pub unsafe fn fn_80af3850(this: usize) -> i32 {
    // observed: `bl 0x80AF38B0` then `extsh r0,r0` on the `r3` result.
    let value = (fn_80af38b0(this) as u16) as i16;
    // observed: `addi r0,r3,-400` / `addi r0,r3,400` with `blt` between them.
    let biased = if value < 0 {
        value.wrapping_sub(400)
    } else {
        value.wrapping_add(400)
    };
    // observed: `mulhw` with `0x51EB851F`, `srawi 8`, plus one for a negative
    // quotient - that is exactly a truncating divide by 800.
    let quotient = (biased as i32) / 800;
    // observed: `mulli r0,r0,800` then `extsh r3,r0`.
    ((quotient * 800) as u16 as i16) as i32
}

