pub unsafe fn fn_80a07c80(this: usize) -> u32 {
    // observed: `addi r5,r3,0x710` / `li r4,0` / `addi r3,r3,0x5B4` /
    // `b 0x80168180`.
    call3(FN_80168180, (this + 0x5B4) as u32, 0, (this + 0x710) as u32)
}

// --- 137f.2 `0x80AF3840` guide-angle step thunk -----------------------------

/// Steps the `+0x7A4` guide angle toward an incoming halfword and returns the
/// step helper's verdict.
///
/// `r4` is sign-extended from its low half with `extsh`, `r5` is the literal
/// `0x400` (`1024`, the step bound) and `r3` is the address of the angle, then
/// the 16-byte body tail-branches to `0x8015F4F0`.
///
/// # Original
/// - Ghidra: `FUN_80af3840` at `0x80AF3840` (16 bytes)
/// - Evidence: `work/ghidra/rel-d_enemiesNP/export/80af3840_FUN_80af3840.c`
/// - Synthetic base: `0x80A00000`; this is not a runtime address.
///
/// # Arguments
/// - `this`: the actor; `+0x7A4` is the current guide angle (`s16`).
/// - `angle`: the target angle; only the low 16 bits are used and they are
///   sign-extended.
///
/// # Returns
/// The helper's `r3` verdict.
///
/// # Safety
/// `this + 0x7A4` must be a valid `s16` angle word.
///
/// # Confidence
/// medium - the four instructions are literal; the callee's argument roles are
/// inferred from the `(s16*, s16, size)` shape and its callers.
pub unsafe fn fn_80af3840(this: usize, angle: i32) -> u32 {
    // observed: `extsh r4,r4` / `li r5,0x400` / `addi r3,r3,0x7A4`.
    let halfword = (angle as u16) as i16;
    call3(
        FN_8015F4F0,
        (this + 0x7A4) as u32,
        (halfword as i32) as u32,
        0x400,
    )
}

