        write_f32(this + 0xEC, read_f32(W156_F32_80B2EAD0));
        let mut position = [0u32; 3];
        let _ = call2(FN_8004A7B0, position.as_mut_ptr() as u32, player as u32);
        platform::write_u32(this + 0xB0, position[1]);
