    unsafe fn restore_home(this: usize) {
        platform::write_u32(this + 0xAC, platform::read_u32(this + 0x6E8));
        platform::write_u32(this + 0xB0, platform::read_u32(this + 0x6EC));
        platform::write_u32(this + 0xB4, platform::read_u32(this + 0x6F0));
    }

