    unsafe fn save_position(this: usize) {
        platform::write_u32(this + 0x6F4, platform::read_u32(this + 0xAC));
        platform::write_u32(this + 0x6F8, platform::read_u32(this + 0xB0));
        platform::write_u32(this + 0x6FC, platform::read_u32(this + 0xB4));
    }

