/// The image writes `first` at `base + 0`, `first + 1 .. first + 5` at
/// `+0x04..+0x14`, and `first + 6` at `+0x18`, `+0x1C` and `+0x20`, then sets
/// the guard byte to `1`.
unsafe fn c243_fill_sound_table(guard: usize, base: usize, first: u32) {
    if platform::read_u8(guard) != 0 {
        return;
    }
    platform::write_u32(base, first);
    for offset in 1..6u32 {
        platform::write_u32(base + offset as usize * 4, first + offset);
    }
    for offset in 6..9u32 {
        platform::write_u32(base + offset as usize * 4, first + 6);
    }
    platform::write_u8(guard, 1);
}

/// Sign-extends a byte field and clamps it into `0..=8`.
