/// `extsb` widens the byte, `cmpli 9` compares it as *unsigned*, and the branch
/// replaces every value at or above `9` - including sign-extended negatives -
/// with `8`.
unsafe fn c243_class_index(other: usize, offset: usize) -> u32 {
    let raw = platform::read_u8(other + offset) as i8;
    if (raw as u32) < 9 {
        raw as u32
    } else {
        8
    }
}

