    let w04 = platform::read_u32(REACTION_PARAMS_802F_08E0_C247 + 0x04);
    let w08 = platform::read_u32(REACTION_PARAMS_802F_08E0_C247 + 0x08);
    let w0C = platform::read_u32(REACTION_PARAMS_802F_08E0_C247 + 0x0C);
    let w10 = platform::read_u32(REACTION_PARAMS_802F_08E0_C247 + 0x10);
    let w14 = platform::read_u32(REACTION_PARAMS_802F_08E0_C247 + 0x14);
    let w18 = platform::read_u32(REACTION_PARAMS_802F_08E0_C247 + 0x18);

    let other_vtable = platform::read_u32(other + 0x60) as usize;
    let kind_ptr = call1(platform::read_u32(other_vtable + 0x6C) as usize, other as u32) as usize;
    let kind_byte = platform::read_u8(kind_ptr);

