        platform::write_u32(object + 0x04, sentinel);
        platform::write_u32(object, sentinel);
        platform::write_u32(E254_LIST2_SENTINEL + 4, object as u32);
        platform::write_u32(E254_LIST2_SENTINEL, object as u32);
