/// `0x80329958`: vtable the constructor writes at `0x80114B64` to the `+0x58C`
/// member, and that [`fn_80115440`] restores before releasing it
/// (`lis r4,0x8033` + `addi r4,r4,-26280`).
const W287_VTABLE_80329958: usize = 0x8032_9958;

/// Virtual call with no payload, returning the callee's word.
///
/// # Safety
/// `object` must hold a live vtable pointer and the entry at `slot` must be a
/// `this`-only method.
#[inline]
unsafe fn a287_vcall0(object: usize, slot: usize) -> u32 {
    let vtable = platform::read_u32(object) as usize;
    let entry = platform::read_u32(vtable + slot) as usize;
    let f = crate::platform::guest_fn!(entry, fn(usize) -> u32);
    f(object)
}

